/* ---------------- Trạng thái ---------------- */

function narrPick(v) {
  var s = String(v == null ? '' : v);
  for (var i = 0; i < NARR_TIERS.length; i++) if (NARR_TIERS[i] === s) return s;
  return 'off';
}
function narrTag(v) {
  var s = narrPick(v);
  return s === 'off' ? 'Tắt' : (s === 'lite' ? 'Nhẹ' : 'Mạnh');
}
function narrNext(v) {
  var s = narrPick(v);
  return s === 'off' ? 'lite' : (s === 'lite' ? 'full' : 'off');
}
/* Khi sắp bật chống toàn tri, có cần giải thích trước một lần hay không.
   Nó là công tắc duy nhất sẽ "cấm viết độc thoại nội tâm, cấm quyết định thay nhân vật", người muốn cướp lời bắt buộc phải biết trước;
   sau khi tắt nhắc nhở thì sẽ luôn im lặng, không chặn nữa. */
function narrTipNeeded(next, tip) {
  var n = narrPick(next);
  if (n === 'off') return false;
  return String(tip == null ? 'on' : tip) !== 'off';
}

/* Tên: lấy được name1 của ST thì đổi thành tên thật, không lấy được thì lùi về "bạn".
   Chú ý đừng để lại ngoặc nhọn trong prompt — một số kênh sẽ nuốt mất <user> vì coi đó là tag không xác định. */
function narrUserName() {
  try {
    var c = stCtx();
    if (!c) return '';
    var n = String(c.name1 == null ? '' : c.name1).trim();
    n = n.replace(/[〔〕【】\[\]<>]/g, '').slice(0, 24).trim();
    return n;
  } catch (e) { return ''; }
}

function narrFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('<user>') < 0) return s;
  var n = narrUserName() || 'bạn';
  return s.split('<user>').join(n);
}

/* Ghép thành toàn bộ khối cần inject cho lượt này; khi cả hai đều tắt thì trả về chuỗi rỗng */
function narrBody() {
  var parts = [];
  var charm = NARR_CHARM[narrPick(cfg && cfg.charm)] || '';
  var know = NARR_KNOW[narrPick(cfg && cfg.know)] || '';
  if (charm) parts.push(narrFill(charm));
  if (know) parts.push(narrFill(know));      /* Chống toàn tri ở lớp trong: gần vị trí sinh văn bản nhất */
  if (!parts.length) return '';
  return NARR_OPEN + '\n' + parts.join('\n') + '\n' + NARR_CLOSE;
}

function narrLabel() {
  var a = (cfg && cfg.know !== 'off') ? ('Chống toàn tri ' + narrTag(cfg.know)) : '';
  var b = (cfg && cfg.charm !== 'off') ? ('Bỏ mị ngọt ' + narrTag(cfg.charm)) : '';
  if (a && b) return a + '+' + b;
  return a || b || 'Tắt';
}

/* Ước tính thô token: tiếng Trung ~0.7 tok/chữ, chỉ dùng để cho panel một độ lớn tham khảo, không dùng làm căn cứ tính phí */
function narrTokens() {
  var b = narrBody();
  if (!b) return 0;
  return Math.round(b.length * 0.7);
}

/* Bóc khối đã inject lần trước. Không tìm thấy tag thì giữ nguyên trả về — tuyệt đối không "đoán mò rồi xóa". */
function narrStripOnce(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf('〔' + NARR_TAG);
  if (i < 0) return t;
  var j = t.indexOf(NARR_CLOSE, i);
  if (j < 0) return t;
  j += NARR_CLOSE.length;
  var head = t.slice(0, i);
  var tail = t.slice(j);
  /* Nuốt luôn khoảng trắng ở hai đầu, nếu không mỗi lượt inject lại sẽ sinh thêm một dòng trống, càng cuộn càng dài */
  head = head.replace(/[ \t]+$/, '');
  tail = tail.replace(/^[ \t\r\n]+/, '');
  if (!tail) return head.replace(/[\s]+$/, '');
  return head + (head ? '\n\n' : '') + tail;
}

/* Lịch sử sót lại có thể để lại hai khối (bản cũ inject + bản này lại inject), bóc một khối một lần là không đủ.
   Giới hạn 8 lần chỉ để phòng chống lỗi lặp vô hạn, bình thường một lượt là xong. */
function narrStrip(s) {
  var t = String(s == null ? '' : s);
  for (var k = 0; k < 8; k++) {
    var n = narrStripOnce(t);
    if (n === t) break;
    t = n;
  }
  return t;
}

/* Inject thực tế: chỉ sửa bản sao body truyền vào */
function narrApply(body) {
  var out = [];
  if (!body || typeof body !== 'object') return out;
  var msgs = (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages))
    ? body.request.messages
    : (Array.isArray(body.messages) ? body.messages : null);
  if (!msgs || !msgs.length) return out;

  /* Tìm user đầu tiên từ cuối lên: trong lượt /continue của phá giáp, tin nhắn cuối là placeholder assistant */
  var idx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var m = msgs[i];
    if (m && String(m.role || '') === 'user') { idx = i; break; }
  }
  if (idx < 0) return out;

  var m2 = msgs[idx];
  var old = String(textOfMsg(m2) || '');
  var base = narrStrip(old);
  var block = narrBody();

  if (!block) {
    if (base !== old) { setMsgText(m2, base); out.push('Tự sự: Xóa sạch'); }
    return out;
  }

  var sep = '';
  if (base) sep = /\n$/.test(base) ? '\n' : '\n\n';
  var next = base + sep + block;
  if (next !== old) {
    setMsgText(m2, next);
    out.push('Tự sự: ' + narrLabel());
  }
  return out;
}

