/* ---------------- Cấu hình ---------------- */

function oocFlag(v, dflt) {
  if (v === undefined || v === null) return dflt;
  return !!v;
}

/* Van tổng tắt -> trả về null (bên gọi đều coi như "không làm gì").
   Lưu ý: Đọc giá trị lưu trong cfg; giá trị mặc định của CFG_DEFAULT là off, migrate không chạy lại. */
function oocCfg() {
  var c = (cfg && typeof cfg === 'object') ? cfg : null;
  if (!c) return null;
  if (String(c.ooc == null ? 'off' : c.ooc) !== 'on') return null;
  return {
    roll: oocFlag(c.oocRoll, true),
    tpl: oocFlag(c.oocTpl, true),
    chg: oocFlag(c.oocChg, false),
    voice: oocFlag(c.oocVoice, true)
  };
}

/* Từng mục có đang bật không (dùng cho render panel; khi van tổng tắt coi như tắt hết) */
function oocOnOf(item) {
  var c = oocCfg();
  if (!c) return false;
  return !!c[item];
}

/* ---------------- Context của Host (bản ST cũ có thể không có gì) ---------------- */

function oocCtx() {
  try {
    if (typeof stCtx === 'function') {
      var c = stCtx();
      if (c) return c;
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e1) {}
  return null;
}

/* Tên World Book gắn với nhân vật này; chưa gắn thì trả về chuỗi rỗng */
function oocBook() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var list = c.characters;
    var id = c.this_chid;
    if (list == null || id == null || id === '') return '';
    var n = +id;
    if (!isFinite(n) || n < 0) return '';
    var ch = list[n];
    if (!ch) return '';
    var d = ch.data;
    var ext = d && d.extensions;
    var w = ext && ext.world;
    return String(w == null ? '' : w).trim();
  } catch (e) { return ''; }
}

/* Mục World Book -> Danh sách nhân vật. Chỉ nhận hai cách viết:
   P1  comment mang tiền tố [角色] / [人物] / [NPC]...;
   P2  comment bản thân nó là tên thuần túy từ 2~6 chữ, và mỗi key cũng đều là tên thuần túy từ 2~6 chữ. */
var OOC_NAME_RE = /^[\u4e00-\u9fa5\u00C0-\u024F\u1E00-\u1EFFA-Za-z· ]{2,24}$/;
var OOC_P1_RE = /^\[(角色|人物|Nhân vật|nhân vật|NPC|npc|char|Char)\]\s*/;

function oocTrim(s) {
  return String(s == null ? '' : s).replace(/^[\s\u3000]+|[\s\u3000]+$/g, '');
}

function oocKeys(e) {
  var out = [];
  if (!e || !Array.isArray(e.key)) return out;
  for (var i = 0; i < e.key.length; i++) {
    var k = oocTrim(e.key[i]);
