   key là tên sách; chỉ cache toàn bộ dữ liệu đã parse thành công. */
var OOC_BOOK_CACHE = {};
var OOC_BOOK_WAIT = {};
var OOC_BOOK_TTL = 30000;

function oocBookCached(book, c) {
  var hit = OOC_BOOK_CACHE[book];
  if (hit) {
    if ((Date.now() - hit.at) < OOC_BOOK_TTL) return hit.data;
    delete OOC_BOOK_CACHE[book];
  }
  var data;
  try { data = c.loadWorldInfo(book); } catch (e0) { return null; }
  if (data && typeof data.then === 'function') {
    /* Không nhận diện được Promise, cũng không thể await ở đây — gắn một then để điền ngược lại, lượt này tạm thời coi như không lấy được */
    if (!OOC_BOOK_WAIT[book]) {
      OOC_BOOK_WAIT[book] = 1;
      try {
        data.then(function (d) {
          delete OOC_BOOK_WAIT[book];
          if (d && typeof d === 'object') OOC_BOOK_CACHE[book] = { data: d, at: Date.now() };
        }, function () { delete OOC_BOOK_WAIT[book]; });
      } catch (e1) { delete OOC_BOOK_WAIT[book]; }
    }
    return null;
  }
  if (!data || typeof data !== 'object') return null;
  return data;
}

function oocPeople(bookName) {
  var out = [];
  var book = oocTrim(bookName);
  if (!book) return out;
  var c = oocCtx();
  if (!c || typeof c.loadWorldInfo !== 'function') return out;
  var data = oocBookCached(book, c);
  if (!data) return out;
  var ent = data.entries;
  if (!ent || typeof ent !== 'object') return out;

  var seen = {};
  var i, e, cm, nm, keys, m;
  var uids = [];
  if (Array.isArray(ent)) {
    for (i = 0; i < ent.length; i++) uids.push(i);
  } else {
    for (var k in ent) if (Object.prototype.hasOwnProperty.call(ent, k)) uids.push(k);
  }

  for (i = 0; i < uids.length && out.length < 40; i++) {
    e = ent[uids[i]];
    if (!e || typeof e !== 'object') continue;
    if (e.disable === true) continue;
    cm = oocTrim(e.comment);
    if (!cm) continue;
    nm = '';
    keys = oocKeys(e);
    m = OOC_P1_RE.exec(cm);
    if (m) {
      nm = oocTrim(cm.slice(m[0].length));
      if (!nm) continue;
    } else if (OOC_NAME_RE.test(cm) && keys.length) {
      var ok = true;
      for (var j = 0; j < keys.length; j++) {
        if (!OOC_NAME_RE.test(keys[j])) { ok = false; break; }
      }
      if (!ok) continue;
      nm = cm;
    } else {
      continue;
    }
    if (seen[nm]) continue;
    seen[nm] = 1;
    out.push({ name: nm, keys: keys });
  }
  return out;
}

/* Có mặt: Sắp xếp theo số lần key xuất hiện trong hai tin nhắn gần nhất, lấy top 6.
   Số lần bằng nhau thì xếp theo thứ tự trước sau trong World Book, đảm bảo danh sách ổn định trong cùng một đoạn đối thoại. */
function oocPresent(people, text) {
  var out = [];
  if (!people || !people.length) return out;
  var t = String(text == null ? '' : text);
  if (!t) return out;
  var hit = [];
  for (var i = 0; i < people.length; i++) {
    var p = people[i];
    if (!p) continue;
    var ks = p.keys || [];
    var n = 0;
    for (var j = 0; j < ks.length; j++) {
      var k = String(ks[j] == null ? '' : ks[j]);
      if (!k) continue;
      var at = t.indexOf(k);
      while (at >= 0) {
        n++;
        at = t.indexOf(k, at + k.length);
        if (n > 99) break;
      }
    }
    if (n > 0) hit.push({ name: String(p.name || ''), n: n, i: i });
  }
  if (!hit.length) return out;
  hit.sort(function (a, b) { return (b.n - a.n) || (a.i - b.i); });
  for (var q = 0; q < hit.length && q < 6; q++) out.push(hit[q].name);
  return out;
}

/* Chính văn của hai tin nhắn gần nhất; ctx.chat không khả dụng thì trả về chuỗi rỗng */
function oocRecent() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var ch = c.chat;
    if (!ch || !ch.length) return '';
    var from = ch.length - 2;
    if (from < 0) from = 0;
    var parts = [];
    for (var i = from; i < ch.length; i++) {
      var m = ch[i];
      if (!m) continue;
      parts.push(String(m.mes == null ? '' : m.mes));
    }
    return parts.join('\n');
  } catch (e) { return ''; }
}

/* ---------------- Tùy chọn xung đột (chỉ trong phiên này, không lưu cấu hình) ----------------
   'script' = Dùng của chúng ta; 'preset' = Nghe theo preset (đoạn này sẽ không inject nữa). */
var OOC_CHOICE = {};

function oocChoice(item) {
  var v = OOC_CHOICE[String(item == null ? '' : item)];
  return (v === 'script' || v === 'preset') ? v : '';
}

function oocSetChoice(item, v) {
  var k = String(item == null ? '' : item);
  if (OOC_ITEMS.indexOf(k) < 0) return '';
  if (v !== 'script' && v !== 'preset') { delete OOC_CHOICE[k]; return ''; }
  OOC_CHOICE[k] = v;
  return v;
}

function oocResetChoice() {
  for (var i = 0; i < OOC_ITEMS.length; i++) delete OOC_CHOICE[OOC_ITEMS[i]];
}

/* ---------------- Ghép nối ---------------- */

/* {{user}} -> Tên thật (không lấy được thì dùng "bạn"). Ở đây không đụng tới ngoặc nhọn, trong văn bản cũng không có <user>. */
function oocFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('{{user}}') < 0) return s;
  var n = '';
  try { if (typeof narrUserName === 'function') n = narrUserName(); } catch (e) {}
  return s.split('{{user}}').join(n || 'bạn');
}

/* Toàn bộ khối cần inject cho lượt này; tắt van tổng / tắt cả bốn mục thì trả về chuỗi rỗng */
function oocText() {
  var c = oocCfg();
  if (!c) return '';
  var parts = [];

  /* Tính trước "lượt này đã nhắc tới ai". Trong World Book không nhận diện được nhân vật nào thì không chặn
     (có thể do chưa gắn World Book, không thể vì thế mà tắt tính năng); nhưng chỉ cần nhận diện được nhân vật,
     mà hai tin nhắn gần nhất không hề nhắc tới ai, thì toàn bộ khối không inject — khi không có ai ở hiện trường
     mà nhắc model "đừng viết OOC" chỉ tổ tạo noise, lại tốn token vô ích. */
  var names = [];
  var known = 0;
  try {
    var book = oocBook();
    if (book) {
      var people = oocPeople(book);
      known = people.length;
      if (known) names = oocPresent(people, oocRecent());
    }
  } catch (e0) { names = []; known = 0; }
  if (known > 0 && !names.length) return '';

  /* 1) Điểm danh: Không nhận diện được nhân vật thì không inject đoạn này (viết "Các nhân vật liên quan trong lượt này: ." là vô nghĩa) */
  if (c.roll && oocChoice('roll') !== 'preset') {
    if (names.length) parts.push(oocFill(oocRollSeg(names)));
  }

  /* 2~4) Chống rập khuôn -> Ngưỡng thay đổi -> Giữ nguyên giọng điệu (thứ tự cố định, không ghép theo thứ tự công tắc) */
  if (c.tpl && oocChoice('tpl') !== 'preset') parts.push(oocFill(OOC_SEG_TPL));
  if (c.chg && oocChoice('chg') !== 'preset') parts.push(oocFill(OOC_SEG_CHG));
  if (c.voice && oocChoice('voice') !== 'preset') parts.push(oocFill(OOC_SEG_VOICE));

  return parts.join('\n\n');
}

/* Ước tính thô token (tiếng Trung ~0.7 tok/chữ), chỉ để panel có một mức độ lớn tham khảo */
function oocTokens() {
  var t = '';
  try { t = oocText(); } catch (e) { t = ''; }
  return t ? Math.round(t.length * 0.7) : 0;
}

function oocLabel() {
  var c = oocCfg();
  if (!c) return 'Tắt';
  var out = [];
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k] || oocChoice(k) === 'preset') continue;
    out.push(OOC_LABEL[k]);
  }
  return out.length ? out.join('+') : 'Tắt';
}

/* ---------------- Inject ---------------- */

/* Bóc khối đã inject lần trước.
   Khối của chúng ta luôn dán nguyên vẹn ở đuôi (bốn đoạn đều mang cùng một tiêu đề, trong khối không có nội dung của người khác),
   vì vậy chỉ cần cắt từ ký hiệu đầu tiên tới cuối là được; bóc xong thu dọn khoảng trắng ở đuôi, tránh mỗi lượt dư thêm một dòng trống. */
function oocStrip(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf(OOC_TAG);
  if (i < 0) return t;
  return t.slice(0, i).replace(/[ \t\r\n]+$/, '');
}

/* Kênh extension prompt: Lấy được ctx và nó thực sự có setExtensionPrompt mới tính */
function oocChannel() {
  try {
    var c = oocCtx();
    if (c && typeof c.setExtensionPrompt === 'function') return c;
  } catch (e) {}
  return null;
}

/* Ghi vào extension prompt. true = lượt này đi theo kênh này; false = chuyển giao cho oocBodyPatch dự phòng.
   Khi văn bản rỗng thì ghi chuỗi rỗng, tương đương với dọn sạch khối còn sót lại từ lượt trước (nếu không tắt van tổng xong nó vẫn còn đó). */
function oocApply() {
  var text = '';
  try { text = oocText(); } catch (e0) { text = ''; }
  var c = oocChannel();
  if (!c) return false;
  try {
    c.setExtensionPrompt(OOC_KEY, text, 1, 4, false, 0);
    return true;
  } catch (e1) { return false; }
}

/* Kênh dự phòng: Dán vào đuôi content của tin nhắn role==='user' cuối cùng (cùng vị trí với narrApply).
   Chỉ sửa bản sao body truyền vào, lịch sử chat không đổi dù chỉ một byte.
   Trả về mảng mô tả thay đổi, bên gọi bắt buộc phải push vào out.changed, nếu không sẽ không serialize. */
function oocBodyPatch(body) {
  var out = [];
  if (!body || typeof body !== 'object') return out;
  var msgs = (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages))
    ? body.request.messages
    : (Array.isArray(body.messages) ? body.messages : null);
  if (!msgs || !msgs.length) return out;

  var idx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var m = msgs[i];
    if (m && String(m.role || '') === 'user') { idx = i; break; }
  }
  if (idx < 0) return out;

  var m2 = msgs[idx];
  var old = '';
  try { old = String(textOfMsg(m2) || ''); } catch (e0) { old = ''; }
  var base = oocStrip(old);
  var block = '';
  try { block = oocText(); } catch (e1) { block = ''; }

  if (!block) {
    if (base !== old) {
      try { setMsgText(m2, base); } catch (e2) { return out; }
      out.push('Chống OOC: Xóa sạch');
    }
    return out;
  }

  var sep = '';
  if (base) sep = /\n$/.test(base) ? '\n' : '\n\n';
  var next = base + sep + block;
  if (next !== old) {
    try { setMsgText(m2, next); } catch (e3) { return out; }
    out.push('Chống OOC:' + oocLabel());
  }
  return out;
}

/* ---------------- Signature của preset: Preset có tự mang chỉ thị cùng loại hay không ----------------
   Bốn nhóm từ khóa của §1, chỉ nhận diện có hay không, không nhận diện mức độ mạnh yếu. Quét các mục "thực sự bật":
   Trong prompt_order[].order[] có enabled===true, dùng .identifier để map ngược về prompts[i],
   không map được thì so khớp theo index ở cùng vị trí (preset cũ không có identifier). */
var OOC_SIG_WORDS = {
  tpl: ['mẫu', 'khuôn mẫu', 'rập khuôn', 'tình tiết', '模板', '脸谱', '刻板', '桥段', 'stereotyp', 'trope', 'cliché'],
  chg: ['thay đổi', 'nguyên do', 'chuyển biến', 'động cơ', '变化', '缘由', '转变', '动机', 'event', 'process'],
  voice: ['giọng điệu', 'cách nói', 'khẩu khí', 'câu cửa miệng', '口吻', '说话方式', '口头禅', 'voice', 'tone', 'speech pattern'],
  roll: ['World Book', 'worldbook', 'thiết lập nhân vật', 'nhân thiết', '世界书', '人设', '角色设定', 'lorebook', 'persona']
};

function oocHitWord(words, text) {
  var s = String(text == null ? '' : text).toLowerCase();
  for (var i = 0; i < words.length; i++) {
    var w = String(words[i] || '').toLowerCase();
    if (w && s.indexOf(w) >= 0) return w;
  }
  return '';
}

function oocSigName(p, text) {
  var nm = oocTrim(p && (p.name || p.identifier));
  var sn = String(text == null ? '' : text).replace(/\s+/g, ' ').replace(/^[\s\u3000]+/, '').slice(0, 20);
  if (nm && sn) return nm + ' · ' + sn;
  return nm || sn;
}

/* Object preset hiện tại; không lấy được thì trả về null (không lấy được = không hiện popup, không phán đoán nhầm) */
function oocPreset() {
  try {
    var c = oocCtx();
    if (c) {
      if (c.preset && Array.isArray(c.preset.prompt_order)) return c.preset;
      if (c.presetManager && Array.isArray(c.presetManager.prompt_order)) return c.presetManager;
      if (typeof c.getPresetManager === 'function') {
        var pm = c.getPresetManager();
        if (pm && Array.isArray(pm.prompt_order)) return pm;
      }
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getPresetManager === 'function') {
      var pm2 = st.getPresetManager();
      if (pm2 && Array.isArray(pm2.prompt_order)) return pm2;
    }
  } catch (e1) {}
  return null;
}

function oocMatchPrompt(prompts, o, j) {
  var id = (o && o.identifier != null) ? String(o.identifier) : '';
  if (id) {
    for (var i = 0; i < prompts.length; i++) {
      var p = prompts[i];
      if (p && String(p.identifier == null ? '' : p.identifier) === id) return p;
    }
  }
  var q = prompts[j];
  return (q && typeof q === 'object') ? q : null;
}

function oocSig(preset) {
  var sig = { tpl: false, chg: false, voice: false, roll: false, hits: {} };
  var p = null;
  try { p = preset || oocPreset(); } catch (e0) { p = null; }
  if (!p || typeof p !== 'object') return sig;
  var prompts = Array.isArray(p.prompts) ? p.prompts : [];
  var orders = Array.isArray(p.prompt_order) ? p.prompt_order : [];
  if (!orders.length) return sig;

  var used = {};
  for (var i = 0; i < orders.length; i++) {
    var ord = orders[i] && orders[i].order;
    if (!Array.isArray(ord)) continue;
    for (var j = 0; j < ord.length; j++) {
      var o = ord[j];
      if (!o || o.enabled !== true) continue;      /* Chỉ nhận các mục thực sự bật */
      var pr = oocMatchPrompt(prompts, o, j);
      if (!pr) continue;
      var mk = String(pr.identifier == null ? j : pr.identifier);
      if (used[mk]) continue;
      used[mk] = 1;
      var text = String(pr.content == null ? '' : pr.content);
      if (!text) continue;
      for (var t = 0; t < OOC_ITEMS.length; t++) {
        var k = OOC_ITEMS[t];
        if (sig[k]) continue;
        if (!oocHitWord(OOC_SIG_WORDS[k], text)) continue;
        sig[k] = true;
        sig.hits[k] = oocSigName(pr, text);
      }
    }
  }
  return sig;
}

/* Các mục cần hỏi: Đang bật + Preset cũng quản lý + Chưa từng xác định.
   Một khi người dùng tick vào "Sau này đều theo cách này" (cfg.oocPolicy), sẽ trực tiếp áp dụng policy toàn cục, không hỏi lại nữa. */
function oocAsk() {
  var out = [];
  var c = oocCfg();
  if (!c) return out;
  var pol = String((cfg && cfg.oocPolicy) || '');
  if (pol !== 'script' && pol !== 'preset') pol = '';
  var sig = null;
  try { sig = oocSig(); } catch (e0) { return out; }
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k]) continue;
    if (!sig[k]) continue;
    if (oocChoice(k)) continue;
    if (pol) { OOC_CHOICE[k] = pol; continue; }
    out.push(k);
  }
  return out;
}

/* ---------------- Panel ---------------- */

/* Chữ trên sub-chip: Bật / Tắt / Nghe theo preset (khi nghe theo preset chip sẽ hiển thị màu xám) */
var OOC_ICON = { roll: '🧩', tpl: '🚫', chg: '🔒', voice: '🗣' };

function oocChipLabel(item) {
  var k = String(item == null ? '' : item);
  var nm = OOC_LABEL[k] || k;
  var ic = OOC_ICON[k] || '🎛';
  if (oocChoice(k) === 'preset') return ic + ' ' + nm + ':Nghe theo preset';
  return ic + ' ' + nm + ':' + (oocOnOf(k) ? 'Bật' : 'Tắt');
}

/* Dòng trạng thái: World Book + Nhận diện được mấy nhân vật. Chỉ đọc, không sửa đổi bất kỳ trạng thái nào. */
function oocStatusLine() {
  try {
    var book = oocBook();
    if (!book) return 'Nhân vật này chưa gắn World Book';
    var people = oocPeople(book);
    if (!people.length) return 'World Book: ' + book + ' · Không nhận diện được mục nhân vật';
    return 'World Book: ' + book + ' · Đã nhận diện ' + people.length + ' nhân vật';
  } catch (e) { return ''; }
}

/* ===== 5_route.js ===== */
/* ============================================================================
 * Anti-Route v7 — 5/6 Route
 * Cổng kiểm soát tính khả kiểm của kênh / Ghim chặt alias / Báo cáo tinh gọn / KPI tỷ lệ routing / Kiểm tra tính khả quan sát của cấp độ
 * Nguyên tắc: Toàn bộ là "đầu dò chạy song song + hiển thị", không thêm bất kỳ tính toán nào vào luồng sinh văn bản
 * ========================================================================== */

var CH_KEY = 'ar7.ch';
var ALIAS_CACHE = null;

/* ---------------- Trạng thái kênh ---------------- */

function chKeyOf(base, key) {
  return String(hashStr(String(base || '').replace(/\/+$/, '') + '|' + String(key || '')));
}

/* Base URL kênh hiện tại: Ưu tiên giá trị điền trong panel, kế tiếp dùng base thực tế gửi đi ở lượt trước */
function curBase() {
  var b = String(cfg.dualBase || '').replace(/\/+$/, '');
  if (b) return b;
  try { if (lastReq && lastReq.base) return String(lastReq.base).replace(/\/+$/, ''); } catch (e) {}
  return '';
}

function readChAll() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(CH_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeChAll(o) {
  try { HOST.localStorage.setItem(CH_KEY, JSON.stringify(o)); } catch (e) {}
}

function chState() {
  var b = curBase();
  if (!b) return { echoes: null, at: 0, base: '' };
  var all = readChAll();
  var st = all[chKeyOf(b, cfg.dualKey || '')];
  if (!st || typeof st !== 'object') return { echoes: null, at: 0, base: b };
  st.base = b;
  return st;
}

function setChState(st) {
  var b = curBase();
  if (!b) return false;
  var all = readChAll();
  var next = { echoes: st.echoes, at: nowMs(), base: b, note: st.note || '' };
  all[chKeyOf(b, cfg.dualKey || '')] = next;
  writeChAll(all);
  return true;
}

/* Nhãn tính khả kiểm: true = echo không thể kiểm / false = có thể kiểm / null = chưa kiểm */
function verifiableLabel() {
  var st = chState();
  if (st.echoes === true) return 'Không thể kiểm';
  if (st.echoes === false) return 'Có thể kiểm';
  return 'Chưa kiểm';
}

function verifiableCode() {
  var st = chState();
  if (st.echoes === true) return 'no';
  if (st.echoes === false) return 'yes';
  return 'unknown';
}

/* ---------------- Đầu dò tối thiểu ---------------- */

function probeFetchFn() {
  try { if (typeof probeFetch === 'function' && probeFetch) return probeFetch; } catch (e) {}
  try { return HOST.fetch; } catch (e) { return null; }
}

function probeOnce(url, bodyObj, ms) {
  return new Promise(function (resolve) {
    var done = false;
    var timer = setTimeout(function () {
      if (done) return;
      done = true;
      resolve({ status: 0, model: '', err: 'timeout' });
    }, ms || 20000);
    var f = probeFetchFn();
    if (!f) { clearTimeout(timer); resolve({ status: 0, model: '', err: 'no-fetch' }); return; }
    var init = {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bodyObj)
    };
    try {
      if (cfg.dualKey) init.headers.Authorization = 'Bearer ' + cfg.dualKey;
    } catch (e) {}
    var p;
    try {
      p = f.call(HOST, url, init);
    } catch (e) {
      clearTimeout(timer); resolve({ status: 0, model: '', err: 'throw' }); return;
    }
    p.then(function (res) {
      var out = { status: res.status, model: '', err: '', ctx: '' };
      return res.text().then(function (t) {
        out.raw = String(t || '').slice(0, 4000);
        try {
          var j = JSON.parse(t);
          out.model = String(j.model || (j.candidates && j.candidates[0] && j.candidates[0].modelVersion) || '');
          if (j.error && j.error.message) out.err = String(j.error.message).slice(0, 120);
        } catch (e) {
          var m = /"(?:model|modelVersion)"\s*:\s*"([^"]{1,120})"/.exec(t || '');
          if (m) out.model = m[1];
          if (/131072|token count exceeds/i.test(t || '')) out.ctx = '131072';
        }
        return out;
      }).catch(function () { return out; });
    }).then(function (out2) {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve(out2);
    }).catch(function () {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve({ status: 0, model: '', err: 'network' });
    });
  });
}

/* Đầu dò tên ma: 4xx => Phân phối theo tên (có thể kiểm); 200 => Không đọc tên (echo) */
function runChannelVerify() {
  var base = String(cfg.dualBase || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: 'Điền Reverse Proxy Base trước' });
  var real = String(cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon');
  var ghost = real + '-zzz-nonexistent';
  var url = openAIUrl(base);
  var body = {
    model: ghost,
    messages: [{ role: 'user', content: 'ping' }],
    max_tokens: 16,
    stream: false
  };
  return probeOnce(url, body, 20000).then(function (r) {
    var echoes = null, note = '', why = '';
    var msg = String((r && r.err) || '');
    if (r.status >= 400 && r.status < 500 && r.status !== 429) {
      /* 4xx không đồng nghĩa với "phân phối theo tên": 401/403 là xác thực chưa qua, 402 là hết tiền,
         hai loại này hoàn toàn chưa đi đến bước tra cứu model, không thể dùng làm bằng chứng. */
      if (r.status === 401 || r.status === 403) {
        why = 'auth';
        note = 'Xác thực bị từ chối (HTTP ' + r.status + '): Request chưa đi đến bước "phân phối theo tên", không thể phán đoán';
      } else if (r.status === 402) {
        why = 'quota';
        note = 'Hạn ngạch/Thanh toán bị từ chối (HTTP 402): Không thể phán đoán';
      } else if (/model|not found|does not exist|unknown|no such|invalid/i.test(msg)) {
        why = 'rejected';
        echoes = false;
        note = 'Tên ma bị từ chối (HTTP ' + r.status + '): Gateway phân phối theo tên, trường model có thể làm bằng chứng';
      } else {
        why = 'unclear';
        note = 'HTTP ' + r.status + ' bị từ chối, nhưng lỗi không liên quan đến tên model' + (msg ? ' (' + msg + ')' : '') + ': Không thể phán đoán';
      }
    } else if (r.status === 200) {
      why = 'echo';
      echoes = true;
      note = 'Tên ma cũng trả về 200 => Gateway không đọc model, model trả về đều bị coi là nhãn/echo';
    } else if (r.status === 0) {
      why = 'net';
      note = 'Thăm dò thất bại: ' + (r.err || 'Lỗi mạng');
    } else {
      why = 'unclear';
      note = 'HTTP ' + r.status + ', không thể xác định tính chất (thử lại sau)';
    }
    if (echoes !== null) setChState({ echoes: echoes, note: note });
    render();
    return { ok: echoes !== null, echoes: echoes, status: r.status, note: note,
      ghost: ghost, why: why, err: msg, raw: String((r && r.raw) || '').slice(0, 300) };
  });
}

/* ---------------- Ghim chặt alias ---------------- */

function aliasBaseName() {
  var m = String(cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon');
  return m.replace(/^(?:google\/|models\/|pg-)/i, '');
}

function aliasCandidates() {
  var x = aliasBaseName();
  var list = [
    x,
    'google/' + x,
    'models/' + x,
    'pg-' + x,
    x + '-high'
  ];
  var seen = {}, out = [];
  for (var i = 0; i < list.length; i++) {
    var v = list[i];
    if (!v || seen[v]) continue;
    seen[v] = 1;
    out.push(v);
  }
  return out.slice(0, 5);
}

function runAliasSweep() {
  var base = String(cfg.dualBase || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: 'Điền Reverse Proxy Base trước' });
  var url = openAIUrl(base);
  var cands = aliasCandidates();
  var rows = [];
  var chain = Promise.resolve();
  cands.forEach(function (name) {
    chain = chain.then(function () {
      var body = { model: name, messages: [{ role: 'user', content: 'ping' }], max_tokens: 16, stream: false };
      return probeOnce(url, body, 20000).then(function (r) {
        var ok = r.status === 200;
        var same = String(r.model || '').replace(/^models\//i, '').toLowerCase() === String(name).replace(/^models\//i, '').toLowerCase();
        rows.push({
          alias: name, status: r.status, model: r.model || '—',
          ctx: r.ctx, ok: ok, echo: ok && same
        });
      });
    });
  });
  return chain.then(function () {
    ALIAS_CACHE = rows;
    render();
    return { ok: true, rows: rows };
  });
}

/* ---------------- Báo cáo tinh gọn (Chỉ đọc) ---------------- */

function slimReport(raw) {
  var body = null;
  try { body = JSON.parse(raw || (lastReq && lastReq.raw) || ''); } catch (e) { return null; }
  if (!body) return null;
  var msgs = Array.isArray(body.messages) ? body.messages : [];
  var text = '';
  for (var i = 0; i < msgs.length; i++) {
    var c = msgs[i] && msgs[i].content;
    if (typeof c === 'string') text += c + '\n\n';
  }
  var paras = text.split(/\n{2,}/).filter(function (p) { return p.trim().length >= 80; });
  var seen = {}, dupParas = 0, dupChars = 0;
  for (var j = 0; j < paras.length; j++) {
    var k = paras[j].trim().slice(0, 200);
    if (seen[k]) { dupParas++; dupChars += paras[j].length; } else seen[k] = 1;
  }
  var em = text.match(/(?:chú ý|nhấn mạnh|quan trọng|bắt buộc|nhất thiết|chớ quên|注意|强调|重要|必须|务必|切记)[：:，,]/gi) || [];
  var sysCount = 0;
  for (var t = 0; t < msgs.length; t++) if (msgs[t] && msgs[t].role === 'system') sysCount++;
  return {
    chars: text.length,
    messages: msgs.length,
    systemCount: sysCount,
    dupParas: dupParas,
    dupChars: dupChars,
    emphasis: em.length,
    advice: (dupParas > 0 ? 'Có ' + dupParas + ' đoạn trùng lặp (khoảng ' + dupChars + ' ký tự), có thể gộp.' : 'Không phát hiện đoạn trùng lặp.') +
            (em.length > 12 ? ' Từ ngữ mang tính nhấn mạnh xuất hiện ' + em.length + ' lần, mật độ tương đối cao.' : '')
  };
}

/* ---------------- KPI tỷ lệ routing ---------------- */

function wilson(k, n) {
  if (!n) return { lo: 0, hi: 0, p: 0 };
  var z = 1.96, p = k / n;
  var d = 1 + z * z / n;
  var c = p + z * z / (2 * n);
  var a = z * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n));
  var lo = (c - a) / d, hi = (c + a) / d;
  return { p: p, lo: Math.max(0, lo), hi: Math.min(1, hi) };
}

function kpi() {
  var log = readLog() || [];
  var eff = 0, bad = 0;
  for (var i = 0; i < log.length; i++) {
    var r = log[i];
    if (!r) continue;
    if (r.internal) continue;   /* Request nội bộ của plugin không tính vào mẫu số của tỷ lệ routing */
    var conf = r.conf || 'C';
    if (conf !== 'A' && conf !== 'B') continue;
    if (r.code === 'skip') continue;   /* Không nằm trong phạm vi kiểm tra thì không tính vào tỷ lệ routing */
    if (r.code === 'unknown' || r.code === 'empty' || r.code === 'error') continue;
    eff++;
    if (r.code === 'diff' || r.code === 'thin' || r.code === 'echo') bad++;
  }
  var w = wilson(bad, eff);
  return { bad: bad, eff: eff, pct: eff ? Math.round(w.p * 1000) / 10 : 0, lo: Math.round(w.lo * 1000) / 10, hi: Math.round(w.hi * 1000) / 10, verifiable: verifiableCode() };
}

/* ---------------- Kiểm tra tính khả quan sát của cấp độ ---------------- */

var LEVEL_TEST = { running: false, result: null };

function levelProbe(levelLabel, effort) {
  var base = String(cfg.dualBase || '').replace(/\/+$/, '');
  var url = openAIUrl(base);
  var body = {
    model: cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon',
    messages: [{ role: 'user', content: 'Dùng một câu giải thích: Tại sao bầu trời lại có màu xanh?' }],
    max_tokens: 96,
    stream: false,
    reasoning_effort: effort
  };
  var t0 = nowMs();
  return probeOnce(url, body, 60000).then(function (r) {
    var dt = nowMs() - t0;
    var chars = 0;
    try {
      var j = JSON.parse(r.model ? '' : '');
    } catch (e) {}
    return { level: levelLabel, effort: effort, status: r.status, ms: dt, model: r.model, err: r.err };
  });
}

function runLevelCheck() {
  if (LEVEL_TEST.running) return Promise.resolve({ ok: false, msg: 'Đang chạy' });
  var base = String(cfg.dualBase || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: 'Điền Reverse Proxy Base trước' });
  LEVEL_TEST.running = true;
  render();
  return levelProbe('Cao', 'high')
    .then(function (a) { return levelProbe('Thấp', 'minimal').then(function (b) { return [a, b]; }); })
    .then(function (arr) {
      var a = arr[0], b = arr[1];
      var verdict = 'unknown', note = '';
      if (!a.status || !b.status) {
        note = 'Cả hai mức đều không nhận được phản hồi (' + (a.err || b.err || 'Lỗi mạng') + '), không thể phán đoán';
      } else if (a.status !== 200 && b.status !== 200) {
        note = 'Cả hai mức đều không phải 200 (' + a.status + '/' + b.status + '), không thể phán đoán';
      } else {
        var faster = b.ms > 0 && a.ms > 0 ? (a.ms / b.ms) : 0;
        if (faster >= 1.25 || faster <= 0.8) { verdict = 'honored'; note = 'Độ chênh lệch thời gian giữa hai mức là ' + Math.round((faster - 1) * 100) + '%, tham số dường như được tôn trọng'; }
        else { verdict = 'ignored'; note = 'Thời gian tiêu tốn của hai mức gần như nhau (' + a.ms + 'ms vs ' + b.ms + 'ms), reasoning_effort nghi vấn bị bỏ qua'; }
      }
      LEVEL_TEST.running = false;
      LEVEL_TEST.result = { verdict: verdict, note: note, rows: arr };
      render();
      return { ok: true, verdict: verdict, note: note, rows: arr };
    })['catch'](function (e) {
      LEVEL_TEST.running = false;
      render();
      return { ok: false, msg: String(e && e.message || e) };
    });
}

/* ---------------- v7.4 Kiểm toán khóa / Khiên từ bên ngoài ---------------- */

var LOCK_FIELDS = ['allow_fallbacks', 'openrouter_allow_fallbacks', 'openrouter_use_fallback', 'provider.allow_fallbacks'];
var LAST_AUDIT = null;
var LAST_FOREIGN = 0;

function readLockField(body, path) {
  if (!body || typeof body !== 'object') return undefined;
  if (path.indexOf('.') < 0) return Object.prototype.hasOwnProperty.call(body, path) ? body[path] : undefined;
  var parts = path.split('.');
  var cur = body;
  for (var i = 0; i < parts.length; i++) {
    if (!cur || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, parts[i])) return undefined;
    cur = cur[parts[i]];
  }
  return cur;
}

function lockAudit(body) {
  var rows = [], pinned = 0, present = 0;
  for (var i = 0; i < LOCK_FIELDS.length; i++) {
    var v = readLockField(body, LOCK_FIELDS[i]);
    var has = v !== undefined;
    var ok = has && v === false;
    if (has) present++;
    if (ok) pinned++;
    rows.push({ name: LOCK_FIELDS[i], present: has, locked: ok });
  }
  LAST_AUDIT = { total: LOCK_FIELDS.length, present: present, pinned: pinned, rows: rows };
  return LAST_AUDIT;
}

function auditLabel() {
  return LAST_AUDIT ? (LAST_AUDIT.pinned + '/' + LAST_AUDIT.total) : '—';
}

function auditColor() {
  if (!LAST_AUDIT) return 'gray';
  if (LAST_AUDIT.pinned === LAST_AUDIT.total) return 'ok';
  if (LAST_AUDIT.pinned > 0) return 'warn';
  return 'gray';
}

function foreignShield(body) {
  var msgs = body && Array.isArray(body.messages) ? body.messages : null;
  if (!msgs || !msgs.length) { LAST_FOREIGN = 0; return 0; }
  var hits = 0;
  var n = Math.min(12, msgs.length);
  for (var i = 0; i < n; i++) {
    var m = msgs[i];
    if (!m) continue;
    var t = typeof m.content === 'string' ? m.content : '';
    if (!t) continue;
    var c1 = (t.match(/<!--/g) || []).length;
    if (c1 >= 2) hits++;
    var c2 = (t.match(/^\[[a-zA-Z0-9_]{4,}\]:\s*#/gm) || []).length;
    if (c2 >= 2) hits++;
    var c3 = (t.match(/[\u200b\u200c\u200d\ufeff]{3,}/g) || []).length;
    if (c3 >= 2) hits++;
    if (/\[(?:IZUMI_ANTI_ROUTE|ANTI_ROUTE|GEMINI_ANTI_ROUTE)\]/i.test(t)) hits++;
  }
  LAST_FOREIGN = hits;
  return hits;
}

function foreignCount() { return LAST_FOREIGN; }

/* ===== 13_stats.js ===== */
/* ============================================================================
 * Anti-Route v7 — 13/Stats Sổ cái kênh / Thẻ fingerprint / Xuất bản ghi / Đối chứng A-B
 * Nguyên tắc: Chỉ làm "đo lường và hiển thị". Không đụng tới request sinh văn bản, không clone 200, không quyết định thay người dùng.
 *   - Sổ cái: Lũy kế các lượt có kết luận theo kênh (không bị giới hạn 40 mục của log), đưa ra khoảng Wilson
 *   - Thẻ fingerprint: Gom việc "kênh này có kiểm tra được không" thành một câu, kênh echo tự động giảm trọng số
 *   - Xuất: Một đoạn văn bản có thể paste <= 1800 chữ + một dòng payload base64 cho máy đọc
 *   - A/B: Request trần vs Cấu hình hiện tại, mỗi bên 2 lần, chỉ báo xu hướng không kết luận
 * ========================================================================== */

var LED_KEY = 'ar7.led';
var AB_STATE = { running: false, last: null };

function statBase() {
  try { return String(curBase() || '').replace(/\/+$/, ''); } catch (e) { return ''; }
}

/* Sổ cái gộp theo base: Cùng một reverse proxy đổi key không nên tách riêng */
function statKey() {
  var b = statBase();
  return b ? String(hashStr(b)).slice(0, 10) : 'local';
}

function readLed() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(LED_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeLed(o) {
  try { HOST.localStorage.setItem(LED_KEY, JSON.stringify(o)); } catch (e) {}
}

function ledEmpty() {
  return { n: 0, same: 0, diff: 0, thin: 0, echo: 0, blocked: 0, weak: 0, at: 0 };
}

function ledRow() {
  var all = readLed();
  var r = all[statKey()];
  if (!r || typeof r !== 'object') return ledEmpty();
  var o = ledEmpty();
  var keys = ['n', 'same', 'diff', 'thin', 'echo', 'blocked', 'weak', 'at'];
  for (var i = 0; i < keys.length; i++) {
    var v = Number(r[keys[i]]);
    o[keys[i]] = isFinite(v) ? v : 0;
  }
  return o;
}

/* Chỉ ghi nhận các lượt "có kết luận": Request nội bộ, cấp C, unknown/empty/error đều không tính vào mẫu số.
   Đây chính là lý do tỷ lệ routing trước đây luôn bị ước tính quá cao — mẫu số bị lẫn những lượt không hợp lệ. */
function ledAdd(rec) {
  try {
    if (!rec || rec.internal) return;
    var conf = rec.conf || 'C';
    var c = rec.code;
    if (c !== 'same' && c !== 'diff' && c !== 'thin' && c !== 'echo' && c !== 'blocked') return;
    var all = readLed();
    var k = statKey();
    var r = all[k];
    if (!r || typeof r !== 'object') r = ledEmpty();
    r.at = nowMs();
    if (conf === 'A' || conf === 'B') {
      r.n = Number(r.n || 0) + 1;
      r[c] = Number(r[c] || 0) + 1;
    } else {
      /* Cấp C cũng ghi, nhưng chỉ ghi vào ô "bằng chứng yếu": Lẫn vào tỷ lệ bị tráo sẽ biến suy đoán thành sự thật */
      r.weak = Number(r.weak || 0) + 1;
    }
    all[k] = r;
    writeLed(all);
  } catch (e) {}
}

/* Tỷ lệ bị tráo = Ba loại không nên xuất hiện (bị tráo / không suy nghĩ / echo) chiếm bao nhiêu phần trong tổng số lượt có kết luận */
function ledStat() {
  var r = ledRow();
  var bad = r.diff + r.thin + r.echo;
  var w = wilson(bad, r.n);
  return {
    n: r.n, bad: bad,
    pct: r.n ? Math.round(w.p * 1000) / 10 : 0,
    lo: Math.round(w.lo * 1000) / 10,
    hi: Math.round(w.hi * 1000) / 10,
    enough: r.n >= 5,
    row: r
  };
}

function ledLine() {
  var s = ledStat();
  if (!s.n) return 'Sổ cái kênh: Vẫn chưa có lượt nào có kết luận (hãy chat vài lượt trước)';
  var ci = s.enough ? (' (khoảng 95% ' + s.lo + '–' + s.hi + '%)') : ' (chưa đủ mẫu, tạm thời đừng xem là kết luận)';
  var weak = Number(s.row && s.row.weak || 0);
  return 'Sổ cái kênh n=' + s.n + ' · Bị tráo ' + s.pct + '%' + ci +
    (weak ? ', ngoài ra có ' + weak + ' lượt bằng chứng quá yếu chưa tính vào' : '');
}

/* ---------------- Thẻ fingerprint kênh (Không lưu trữ mới, chỉ gom các quan sát sẵn có thành một câu) ---------------- */

function fpCard() {
  var b = statBase() || '(Kênh chưa xác định)';
  var st = { echoes: null };
  try { st = chState() || st; } catch (e) {}
  var ver = (st.echoes === true) ? 'Echo (tên không khớp không thể làm bằng chứng)'
    : (st.echoes === false ? 'Có thể kiểm (tên có thể làm bằng chứng)' : 'Chưa kiểm (hãy bấm "🔭 Kiểm tra kênh" trước)');
  var ali = 0;
  try { ali = (ALIAS_CACHE && ALIAS_CACHE.length) || 0; } catch (e2) { ali = 0; }
  var s = ledStat();
  var lines = [
    '🏷 Kênh ' + String(b).replace(/^https?:\/\//, '').slice(0, 42),
    'Tính khả kiểm: ' + ver,
    'Alias: ' + (ali ? ali + ' mục khả dụng' : 'Chưa quét (bấm "🏷 Quét alias")'),
    'Sổ cái: ' + (s.n ? ('n=' + s.n + ', bị tráo ' + s.pct + '%' + (s.enough ? '' : ' (chưa đủ mẫu)')) : 'Trống'),
    'Kết luận: ' + (st.echoes === true
      ? 'Kênh này sẽ echo tên model của bạn, mọi trường hợp "bị tráo" xuyên họ model đều bị hạ cấp xuống "không thể phán đoán".'
      : (st.echoes === false ? 'Tên có thể dùng làm bằng chứng cấp B; chỉ khi xuyên họ model và tự xưng trong response body mới là cấp A.' : 'Kênh chưa kiểm chỉ có bằng chứng cấp C, đừng dùng nó để kết luận.'))
  ];
  return lines.join('\n');
}

/* ---------------- Xuất bản ghi ---------------- */

function b64(s) {
  try {
    if (HOST.btoa) return HOST.btoa(unescape(encodeURIComponent(String(s))));
  } catch (e) {}
  return '';
}

function redact(s) {
  return String(s == null ? '' : s)
    .replace(/sk-[A-Za-z0-9_\-]{6,}/g, 'sk-***')
    .replace(/([?&](?:key|token|api_key)=)[^&\s]+/gi, '$1***');
}

function hhmm(ms) {
  try {
    var d = new Date(ms);
    return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
  } catch (e) { return '--:--'; }
}

/* Lấy từ mới tới cũ, cho đến giới hạn 1800 chữ; thà bớt vài lượt, chứ không xuất một đoạn chữ mờ bị cắt cụt */
function exportText() {
  var log = readLog() || [];
  var s = ledStat();
  var head = [
    'Ánh Sáng Luke V' + VERSION + ' · Xuất bản ghi',
    'Kênh: ' + (statBase() || '(Chưa xác định)'),
    'Sổ cái: n=' + s.n + ', bị tráo ' + s.pct + '% (' + s.lo + '–' + s.hi + '%)' + (s.enough ? '' : ' Chưa đủ mẫu'),
    '---'
  ];
  var body = [];
  var used = head.join('\n').length;
  var picked = [];
  for (var i = log.length - 1; i >= 0; i--) {
    var r = log[i];
    if (!r) continue;
    var line = hhmm(r.at) + ' ' + (r.req || '—') + ' → ' + (r.obs || '—') +
      ' [' + (r.verdict || '?') + '/' + (r.conf || 'C') + ']' +
      (r.status ? ' HTTP' + r.status : '') +
      (r.chars ? ' ' + r.chars + ' chữ' : '') +
      (r.internal ? ' (Nội bộ)' : '') +
      (r.note ? ' — ' + redact(r.note) : '');
    if (used + line.length + 1 > 1700) break;
    used += line.length + 1;
    body.push(line);
    picked.push({
      t: r.at, req: r.req, obs: r.obs, code: r.code, conf: r.conf,
      st: r.status, ch: r.chars, in: r.internal ? 1 : 0, n: redact(r.note)
    });
  }
  var payload = b64(JSON.stringify({
    v: VERSION, base: statBase(), led: { n: s.n, bad: s.bad, pct: s.pct }, rec: picked
  }));
  var out = head.join('\n') + '\n' + body.join('\n');
  if (payload) out += '\n#AR6LOG 1 ' + payload;
  return out;
}

/* ---------------- Đối chứng A/B (Request trần vs Cấu hình hiện tại) ---------------- */

function abBody(framed) {
  var b = {
    model: (cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon'),
    messages: [{ role: 'user', content: 'Hãy nói một câu "Được".' }],
    max_tokens: 24,
    stream: false
  };
  if (!framed) return b;
  try {
    var p = planRequest(JSON.stringify(b), openAIUrl(statBase()), false);
    if (p && p.body && p.body !== JSON.stringify(b)) return JSON.parse(p.body);
  } catch (e) {}
  return b;
}

function abArm(framed) {
  var url = openAIUrl(statBase());
  return probeOnce(url, abBody(framed), 45000).then(function (r) {
    return { framed: framed, status: r.status, model: r.model || '', err: r.err || '' };
  });
}

/* 2x2: Chỉ báo "cấu hình có làm thay đổi tên quan sát được hay không", không đưa ra kết luận "bên nào tốt hơn" */
function abProbe() {
  if (AB_STATE.running) return Promise.resolve({ ok: false, msg: 'Đang chạy' });
  if (!statBase()) return Promise.resolve({ ok: false, msg: 'Điền Reverse Proxy Base trước' });
  AB_STATE.running = true;
  render();
  var seq = [false, true, false, true];
  var out = [];
  var step = function (i) {
    if (i >= seq.length) return Promise.resolve(out);
    return abArm(seq[i]).then(function (r) { out.push(r); return step(i + 1); });
  };
  return step(0).then(function (arr) {
    AB_STATE.running = false;
    var plain = [], framed = [];
    for (var i = 0; i < arr.length; i++) (arr[i].framed ? framed : plain).push(arr[i]);
    var same = function (a) { return a[0] && a[1] && a[0].model && a[0].model === a[1].model; };
    var note;
    if (!plain.length || !plain[0].model) note = 'Request trần không lấy được model, phép đối chứng không thành lập (có thể kênh không ghi trường model)';
    else if (same(plain) && same(framed)) note = 'Hai nhánh đều tự ổn định, và cấu hình không làm thay đổi tên quan sát được — Cấu hình an toàn';
    else if (same(plain) && !same(framed)) note = 'Sau khi bật cấu hình thì tên bắt đầu nhảy — Cấu hình có thể chạm phải vấn đề tương thích của kênh';
    else note = 'Bản thân request trần đã không ổn định — Đây không phải vấn đề cấu hình, mà do chính kênh đang biến động';
    var res = { ok: true, plain: plain, framed: framed, note: note, at: nowMs() };
    AB_STATE.last = res;
    render();
    return res;
  })['catch'](function (e) {
    AB_STATE.running = false;
    render();
    return { ok: false, msg: String(e && e.message || e) };
  });
}

function abLine() {
  if (AB_STATE.running) return '⚖️ Đối chứng A/B đang chạy…';
  var r = AB_STATE.last;
  if (!r) return '⚖️ Đối chứng A/B: Chưa từng chạy (mỗi bên 2 request nhỏ, khoảng 10 giây)';
  var f = function (a) {
    return a.map(function (x) { return (x.model || ('HTTP' + x.status)); }).join(' / ');
  };
  return '⚖️ Trần: ' + f(r.plain) + ' ｜ Có cấu hình: ' + f(r.framed) + ' — ' + r.note;
}

/* ===== 6_float.js ===== */
/* ============================================================================
 * Anti-Route v7 — 6/6 Float
 * Bóng nổi: Tùy chỉnh icon / kích thước / hình dạng / độ trong suốt / hít mép / kéo thả / thu gọn
 *   1) Ảnh cục bộ giới hạn 300KB và downsample xuống 128px (localStorage chỉ có 5MB)
 *   2) Icon liên kết ngoài tải thất bại tự động lùi về emoji
 *   3) Ngưỡng chạm nhẹ/kéo thả 12px + nhấn giữ 400ms mới vào trạng thái kéo
 *   4) Khu vực cài đặt gập độc lập, mặc định thu gọn, không chiếm chỗ bảng phán đoán
 *   5) Không làm ô nhiễm toàn cục HOST nữa (trạng thái để trong state)
 * ========================================================================== */

var FLOAT_IMAGE_KEY = 'ar7.float.image';
var floatImageCache = null;
var floatPreview = null;
var floatDragging = false;

function floatImage() {
  if (floatPreview) return floatPreview;
  if (floatImageCache !== null) return floatImageCache;
  try { floatImageCache = HOST.localStorage.getItem(FLOAT_IMAGE_KEY) || ''; } catch (e) { floatImageCache = ''; }
  return floatImageCache;
}

function floatIconMarkup() {
  var url = floatImage() || cfg.floatIcon || '';
  if (url && /^(https?:\/\/|data:image\/)/i.test(url)) {
    return '<img class="ar6-custom-icon" draggable="false" alt="" src="' + esc(url) + '"' +
      ' onerror="this.style.display=\'none\';var p=this.parentNode;if(p){var s=p.querySelector(\'.ar6-fb\');if(s)s.style.display=\'inline\';}"' +
      ' style="position:absolute!important;inset:0!important;width:100%!important;height:100%!important;' +
      'max-width:none!important;max-height:none!important;min-width:100%!important;min-height:100%!important;' +
      'object-fit:cover!important;object-position:center!important;border-radius:inherit!important;' +
      'margin:0!important;padding:0!important;border:0!important;pointer-events:none!important;display:block!important">' +
      '<span class="ar6-fb" style="display:none;pointer-events:none;font-size:22px">🛡️</span>';
  }
  return '<span style="pointer-events:none;font-size:23px">🛡️</span>';
}

function ar6Rgb(hex, a) {
  var h = String(hex || '#0d1117').replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  var n = parseInt(h, 16);
  if (!isFinite(n)) n = 0x0d1117;
  var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
}

var PAD_OPEN = false;
var PAD_W = 190, PAD_H = 176;

/* Kích thước hộp của root node hiện tại: Bóng / Tay cầm / Bảng điều khiển */
function floatBoxSize() {
  if (PAD_OPEN) return { w: PAD_W, h: PAD_H };
  var n = floatSizePx();
  if (String(cfg.floatMode) === 'tuck') return { w: Math.max(10, Math.round(n * 0.3)), h: n };
  return { w: n, h: n };
}

function floatSizePx() {
  var n = Number(cfg.floatSize) || 44;
  return Math.max(28, Math.min(80, n));
}

function floatTint() {
  var code = 'gray';
  try {
    if (typeof kpi === 'function') {
      var k = kpi();
      /* v8.3: kpi chỉ cung cấp eff, không có total; warn bắt buộc phải phán đoán trước, nếu không sẽ vĩnh viễn không chạm tới */
      var n = Number(k.eff) || 0;
      var bad = Number(k.bad) || 0;
      code = (n >= 4 && bad / n >= 0.15) ? 'warn' : (bad > 0 ? 'bad' : 'ok');
    }
  } catch (e) {}
  if (code === 'bad') return { line: 'rgba(248,81,73,.55)', halo: 'rgba(248,81,73,.16)' };
  if (code === 'warn') return { line: 'rgba(210,153,34,.5)', halo: 'rgba(210,153,34,.14)' };
  return { line: 'rgba(88,166,255,.45)', halo: 'rgba(88,166,255,.14)' };
}

function floatStyle() {
  var box = floatBoxSize();
  var shape = cfg.floatShape === 'square' ? '12px' : '50%';
  if (PAD_OPEN) shape = '14px';
  var op = Math.max(0.12, Math.min(1, (Number(cfg.floatOpacity) || 45) / 100));
  var tint = floatTint();
  /* Trạng thái chờ bán trong suốt dùng nền rgba, chứ không dùng opacity của container — nếu không vòng năng lượng sẽ bị mờ theo */
  /* Bảng điều khiển là panel thao tác: Cố định nền tối, tránh người dùng chỉnh bóng màu sáng dẫn đến không đọc được chữ */
  var bg = PAD_OPEN ? ar6Rgb('#161b22', 0.97) : ar6Rgb(cfg.floatBg || '#0d1117', op);
  return 'width:' + box.w + 'px;height:' + box.h + 'px;min-width:' + box.w + 'px;min-height:' + box.h + 'px;' +
    'padding:0!important;border-radius:' + shape + ';background:' + bg + ';' +
    'border:1px solid ' + (cfg.floatBorder ? tint.line : 'transparent') + ';' +
    'box-shadow:' + (cfg.floatShadow ? ('0 10px 26px rgba(0,0,0,.45),0 0 0 4px ' + tint.halo) : 'none') + ';' +
    'opacity:1;touch-action:none;user-select:none;-webkit-user-select:none;overflow:visible;' +
    'box-sizing:border-box;display:flex;align-items:center;justify-content:center;position:fixed;z-index:2147483000;left:0;top:0;' +
    'cursor:' + (PAD_OPEN ? 'default' : 'grab') + ';' +
    'transition:width .16s,height .16s,border-radius .16s,box-shadow .25s;';
}

var FLOAT_GEOM = { x: null, y: null };

/* ---- v8.1 Nhân bố cục: Vùng an toàn + Tọa độ chuẩn hóa + Hít mép ---- */

function floatVW() {
  var vv = HOST.visualViewport;
  var w = (vv && vv.width) || HOST.innerWidth || 360;
  return Math.round(w);
}

function floatVH() {
  var vv = HOST.visualViewport;
  var h = (vv && vv.height) || HOST.innerHeight || 640;
  return Math.round(h);
}

/* Vùng an toàn: Hai bên chừa PAD, đáy né khu vực nhập liệu và thanh cử chỉ */
function getSafeBox() {
  var pad = (typeof uiMode === 'function' && uiMode() === 'mobile') ? 8 : 12;
  var l = pad, t = pad, r = floatVW() - pad, b = floatVH() - pad - 34;
  try {
    if (DOC && DOC.querySelector) {
      var f = DOC.querySelector('#send_form') || DOC.querySelector('#form_sheld');
      if (f) {
        var fr = f.getBoundingClientRect();
        if (fr && fr.height > 8 && fr.top > 40) b = Math.min(b, Math.round(fr.top) - pad);
      }
    }
  } catch (e) {}
  if (r - l < 80) r = l + 80;
  if (b - t < 80) b = t + 80;
  return { l: l, t: t, r: r, b: b };
}

function floatClampPx(x, y, w, h) {
  var s = getSafeBox();
  var maxX = Math.max(s.l, s.r - w);
  var maxY = Math.max(s.t, s.b - h);
  return {
    x: Math.round(Math.max(s.l, Math.min(maxX, x))),
    y: Math.round(Math.max(s.t, Math.min(maxY, y)))
  };
}

/* Tính tọa độ pixel từ cfg.fxN/fyN/fEdge */
function floatLayoutPx() {
  var b = floatBoxSize();
  var w = b.w, h = b.h;
  var s = getSafeBox();
  var vw = floatVW();
  var nx = (typeof cfg.fxN === 'number') ? cfg.fxN : 1;
  var ny = (typeof cfg.fyN === 'number') ? cfg.fyN : 0.82;
  nx = Math.max(0, Math.min(1, nx));
  ny = Math.max(0, Math.min(1, ny));
  var x = s.l + nx * Math.max(0, (s.r - s.l) - w);
  var y = s.t + ny * Math.max(0, (s.b - s.t) - h);
  var mode = String(cfg.floatMode);
  if (!PAD_OPEN && mode === 'dock') {
    var reveal = Math.max(0.45, Math.min(0.8, (Number(cfg.floatDock) || 45) / 100));
    if (cfg.fEdge === 'l') x = -w * (1 - reveal);
    else if (cfg.fEdge === 'r') x = vw - w * reveal;
  } else if (!PAD_OPEN && mode === 'tuck') {
    x = (cfg.fEdge === 'l') ? 0 : (vw - w);
  }
  return { x: x, y: y, n: w, w: w, h: h };
}

/* Kéo xong ghi ngược lại tọa độ chuẩn hóa */
function floatSaveFromPx(r) {
  if (!r) return;
  var b = r.getBoundingClientRect();
  var box = floatBoxSize();
  var n = box.w;
  var s = getSafeBox();
  var w = Math.max(1, (s.r - s.l) - box.w);
  var h = Math.max(1, (s.b - s.t) - box.h);
  cfg.fxN = Math.max(0, Math.min(1, (b.left - s.l) / w));
  cfg.fyN = Math.max(0, Math.min(1, (b.top - s.t) / h));
  var mid = s.l + (s.r - s.l - box.w) / 2;
  cfg.fEdge = (b.left + box.w / 2 < mid) ? 'l' : 'r';
  cfg.floatX = Math.round(b.left);
  cfg.floatY = Math.round(b.top);
}

function floatApplyPosition(r, docked) {
  if (!r) return;
  var p = floatLayoutPx();
  var dockOn = docked && !PAD_OPEN && cfg.floatMode === 'dock';
  var tuckOn = docked && !PAD_OPEN && cfg.floatMode === 'tuck';
  if (!dockOn && !tuckOn) {
    var c = floatClampPx(p.x, p.y, p.w, p.h);
    p.x = c.x;
    p.y = c.y;
  }
  FLOAT_GEOM.x = Math.round(p.x);
  FLOAT_GEOM.y = Math.round(p.y);
  r.style.left = FLOAT_GEOM.x + 'px';
  r.style.top = FLOAT_GEOM.y + 'px';
  r.style.right = 'auto';
  r.style.bottom = 'auto';
  r.style.width = p.w + 'px';
  r.style.height = p.h + 'px';
  r.style.minWidth = p.w + 'px';
  r.style.minHeight = p.h + 'px';
}

function bindFloatGestures(r) {
  var pill = r.querySelector('.ar6-pill');
  if (!pill) return;
  var sx = 0, sy = 0, ox = 0, oy = 0;
  var downAt = 0, dragging = false, active = false, holdTimer = null, armed = false, moved = false;

  function commit() {
    var n = floatSizePx();
    var b = r.getBoundingClientRect();
    var c = floatClampPx(b.left, b.top, n, n);
    r.style.left = c.x + 'px';
    r.style.top = c.y + 'px';
    floatSaveFromPx(r);
    saveCfg();
    floatApplyPosition(r, true);
  }

  function openPanelFromBall() {
    /* Bóng ở nửa bên nào, panel sẽ mở rộng từ nửa bên đó */
    var vw = floatVW();
    var vh = floatVH();
    var pw = Math.min(vw * 0.92, 380);
    var ph = Math.min(vh * 0.62, 720);
    var b = r.getBoundingClientRect();
    var s = getSafeBox();
    var mx = (b.left + b.width / 2 > vw / 2) ? (s.r - pw) : s.l;
    var my = Math.max(s.t, Math.min(s.b - ph, b.top - 8));
    cfg.mx = Math.round(mx);
    cfg.my = Math.round(my);
    saveCfg();
    minimized = false;
    syncMin();
    render();
  }

  pill.addEventListener('pointerdown', function (e) {
    if (e.button !== undefined && e.button !== 0) return;
    active = true; moved = false; armed = false; dragging = false;
    var b = r.getBoundingClientRect();
    ox = b.left; oy = b.top; sx = e.clientX; sy = e.clientY;
    downAt = Date.now();
    try { pill.setPointerCapture(e.pointerId); } catch (err) {}
    holdTimer = setTimeout(function () { holdTimer = null; armed = true; }, 450);
  }, { passive: true });

  pill.addEventListener('pointermove', function (e) {
    if (!active) return;
    var dx = e.clientX - sx, dy = e.clientY - sy;
    if (!dragging && Math.abs(dx) + Math.abs(dy) < 6) return;
    dragging = true; moved = true;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
    if (e.preventDefault) e.preventDefault();
    var n = floatSizePx();
    var s = getSafeBox();
    var nx = Math.max(-n, Math.min(floatVW() - 1, ox + dx));
    var ny = Math.max(s.t - 24, Math.min(s.b - n, oy + dy));
    r.style.right = 'auto';
    r.style.bottom = 'auto';
    r.style.left = Math.round(nx) + 'px';
    r.style.top = Math.round(ny) + 'px';
  }, { passive: false });

  function end() {
    if (!active) return;
    active = false;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
    if (dragging) { dragging = false; commit(); return; }
    if (armed) { armed = false; try { openPanelFromBall(); } catch (eOpen) {} return; }
    if (Date.now() - downAt < 450) { try { openPad(); } catch (ePad) {} }
  }

  pill.addEventListener('pointerup', end);
  pill.addEventListener('pointercancel', function () {
    active = false; dragging = false;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
  });
}

/* ---- v8.1 Kéo thả panel: Kéo trực tiếp ở thanh tiêu đề/vùng trống, vùng cuộn nhấn giữ 450ms rồi mới kéo ---- */
function installRootDrag(r, kind) {
  if (!r) return;
  if (r.__ar6rd) { r.__ar6kind = kind; return; }
  r.__ar6rd = true; r.__ar6kind = kind;
  var active = false, armed = false, moved = false;
  var sx = 0, sy = 0, ox = 0, oy = 0;
  var holdTimer = null;
  /* v8.30: Xử lý riêng cảm ứng và chuột. Ngón tay chạm vào chính văn có thể cuộn thì không cướp sự kiện ngay lập tức,
     nếu không preventDefault sẽ chặn cuộn nguyên bản — người dùng sẽ thấy "panel không trượt được, trái lại còn bị kéo đi". */
  var touchMode = false, armLong = false;

  function hitInteractive(t) {
    var p = t;
    while (p && p !== r) {
      if (p.getAttribute && p.getAttribute('data-ar6')) return true;
      var tag = (p.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select' || tag === 'button' || tag === 'summary' || tag === 'a') return true;
      p = p.parentNode;
    }
    return false;
  }

  function hitHeader(t) {
    var p = t;
    while (p && p !== r) {
      if (p.className) {
        var cls = String(p.className).split(/\s+/);
        for (var ci = 0; ci < cls.length; ci++) if (cls[ci] === 'ar6-h' || cls[ci] === 'ar6-grip') return true;
      }
      p = p.parentNode;
    }
    return false;
  }

  function hitScroll(t) {
    var p = t;
    while (p) {
      try {
        if (p.nodeType === 1 && p.clientHeight > 0 && p.scrollHeight > p.clientHeight + 2) return true;
      } catch (e) {}
      if (p === r) break;
      p = p.parentNode;
    }
    return false;
  }

  r.addEventListener('pointerdown', function (e) {
    if (e.button !== undefined && e.button !== 0) return;
    var t = e.target || e.srcElement;
    if (!t || hitInteractive(t)) return;
    var isTouch = (e.pointerType === 'touch');
    touchMode = isTouch; armLong = false;
    /* Thanh tiêu đề: Mọi phương thức nhập đều có thể kéo trực tiếp; Chính văn: Chuột có thể kéo, ngón tay bắt buộc nhấn giữ 450ms trước.
       Ngón tay vừa chạm đã armed sẽ nuốt mất thao tác cuộn nguyên bản, người dùng sẽ thấy "không trượt được". */
    var direct = hitHeader(t) || (!isTouch && !hitScroll(t));
    var b = r.getBoundingClientRect();
    active = true; moved = false; armed = false;
    sx = e.clientX; sy = e.clientY; ox = b.left; oy = b.top;
    if (direct) { armed = true; }
    else {
      holdTimer = setTimeout(function () { holdTimer = null; armed = true; armLong = true; }, 450);
    }
  }, { passive: true });

  r.addEventListener('pointermove', function (e) {
    if (!active) return;
    var dx = e.clientX - sx, dy = e.clientY - sy;
    if (!moved && Math.abs(dx) + Math.abs(dy) < 6) return;
    if (!armed) {
      active = false;
      if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
      return;
    }
    moved = true;
    /* Cảm ứng bắt buộc phải sau khi nhấn giữ mới cho phép nuốt sự kiện; chưa nhấn giữ thì đều cho qua để trình duyệt cuộn */
    if (e.preventDefault && (!touchMode || armLong)) e.preventDefault();
    r.style.transition = 'none';
    r.style.transform = 'translate3d(' + Math.round(dx) + 'px,' + Math.round(dy) + 'px,0)';
  }, { passive: false });

  function end(cancelled) {
    if (!active) return;
    active = false;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
    if (moved && !cancelled) {
      /* Đo rect trước (bao gồm translate3d), rồi mới xóa transform — ngược thứ tự sẽ bị nảy về vị trí cũ */
      var b = r.getBoundingClientRect();
      var w = b.width || 320, h = b.height || 240;
      var c = floatClampPx(b.left, b.top, w, h);
      r.style.transform = '';
      r.style.transition = '';
      r.style.left = c.x + 'px';
      r.style.top = c.y + 'px';
      r.style.right = 'auto';
      r.style.bottom = 'auto';
      var k2 = r.__ar6kind || kind;
      if (k2 === 'ball') floatSaveFromPx(r);
      else if (k2 === 'pad') { floatSaveFromPx(r); }
      else { cfg.mx = c.x; cfg.my = c.y; saveCfg(); }
    } else {
      r.style.transform = '';
      r.style.transition = '';
    }
    moved = false; armed = false; armLong = false;
  }

  r.addEventListener('pointerup', function () { end(false); });
  r.addEventListener('pointercancel', function () { end(true); });
}

