  h += '<div style="width:402px;max-width:calc(100vw - 20px);max-height:' + cardBoxMaxH(88) + ';overflow:auto;background:#0d1117;color:#e6edf3;border:1px solid #30363d;border-radius:16px;box-shadow:0 12px 48px rgba(0,0,0,.6)">';
