function jailOffer(j) {
  var cur = jailLastAi();
  var key = cur ? (String(cur.idx) + '|' + String(cur.msg.send_date || '')) : 'noctx';

  /* v0.77: Việc ghi sổ "chuyển biến tốt" đã chuyển tới đầu vào jailAfterFinish (ở đây chỉ nhận được empty/trunc, vĩnh viễn không đi tới ok) */
  JAIL_ASK.at = nowMs();
  JAIL_ASK.code = (j && j.code) || '';
  JAIL_ASK.key = key;
  var node = null;
  try {
    /* v8.0.3: Đăng ký thành layer nổi, bấm hộp xác nhận sẽ không thu gọn panel chính */
    if (typeof CARD === 'object' && CARD) { CARD.open = true; CARD.rid = -1; CARD.tab = 'jail'; }
    node = mountHTML(jailConfirmHTML(j, cur));
  } catch (eM) {
    try { banner('🩹 Không vẽ được hộp xác nhận: ' + String(eM && eM.message || eM), 'bad'); } catch (e2) {}
    return false;
  }
  if (!node) { try { banner('🩹 Chưa gắn được hộp xác nhận, vui lòng bấm tiếp tục thủ công', 'warn'); } catch (e3) {} return false; }
  node.addEventListener('click', function (ev) {
    var t = ev.target;
    var act = (t && t.getAttribute && t.getAttribute('data-ar6-card')) || '';
    if (act === 'jailgo') {
      closeCard();
      var g = jailGate(key);
      if (!g.ok) {
        if (g.why === 'max') banner('🩹 Lượt này đã bù ' + JL.count + ' lần mà vẫn có lỗi, tạm thời dừng tay', 'bad');
        else if (g.why === 'rate') banner('🩹 Bù quá nhiều lần trong vòng một phút, tạm thời dừng tay', 'bad');
        else banner('🩹 Hiện tại không thể bù (' + g.why + ')', 'warn');
        return;
      }
      JL.try++; JL.pendKey = key;          /* v0.77: Bù thủ công cũng phải ghi sổ, nếu không cầu chì sẽ không bao giờ ngắt */
      jailSchedule(j, JL.count + 1, 1);   /* v0.12: Căn chỉnh với var max = 1 trong jailFire, đừng hiển thị (1/2) nữa */
      return;
    }
    if (act === 'jailno') { closeCard(); banner('🩹 Được, không bù nữa', 'gray'); return; }
    if (act === 'jailless') {
      cfg.jailConfirm = false; saveCfg(); closeCard();
      banner('🩹 Phiên này sẽ không hỏi lại, sau này tự động bù (tối đa 1 lần)', 'warn');
      return;
    }
    if (act === 'close' || t === node) closeCard();
  });
  try { banner('🩹 ' + (j.note || 'Giống như bị cắt cụt') + ', có muốn bù không? Bấm nút trong layer nổi', 'warn'); } catch (e4) {}
  return true;
}

function jailAskPending() { return !!(JAIL_ASK.at && (nowMs() - JAIL_ASK.at < 120000)); }

function jailSchedule(j, n, max) {
  JL.count = n;
  JL.at = nowMs();
  JL.lock = true;
  JL.lockAt = nowMs();
  banner('🩹 ' + j.note + ', tự động viết tiếp (' + n + '/' + max + ')…', 'warn');
  var tries = 0;
  var iv = setInterval(function () {
    tries++;
    var busy = false;
    try { busy = isBusy(); } catch (e) {}
    if (!busy) {
      clearInterval(iv);
      JL.lock = false;
      jailFire();
    } else if (tries >= JAIL_WAIT_MAX) {
      clearInterval(iv);
      JL.lock = false;
      banner('🩹 SillyTavern liên tục trong trạng thái sinh văn bản, lượt này không bù nữa', 'warn');
    }
  }, 250);
  WATCHERS.push(iv);
}

/* v0.2: Một dòng nói rõ "đã bù mấy lần, có tác dụng hay không" */
function jailStatLine() {
  var t = Number(JL.try || 0), k = Number(JL.ok || 0);
  if (!t) return 'Phá giáp: Phiên này chưa từng bù (' + (cfg.jail === 'off' ? 'hiện đang tắt' : 'hiện đang bật') + ')';
  var pct = t ? Math.round(k / t * 100) : 0;
  return 'Phá giáp: Bù ' + t + ' lần · Bù xong phục hồi ' + k + ' lần (' + pct + '%)' +
    (t >= 5 && pct === 0 ? ' ｜ Chưa thành công lần nào, đừng bù nữa, hãy đổi kênh' : '');
}

function jailAfterFinish(ev) {
  if (!cfg || !cfg.enabled || cfg.jail === 'off' || cfg.safe) return;
  if (!ev || ev.status !== 200 || ev.error) return;
  /* v8.29: Request nội bộ không có sản phẩm chat, đừng lấy nó phán đoán phản hồi rỗng/cắt cụt */
  if (ev.internal) return;

  var j = jailInspect(ev);
  if (!j) return;

  /* v0.77: Ghi sổ trước rồi mới chặn tiếng vọng — phần kết của phát súng viết tiếp đó chính là lần bị selfAt nuốt mất, tỷ lệ thành công không thể mãi bằng 0 */
  var cur = jailLastAi();
  var key = cur ? (String(cur.idx) + '|' + String(cur.msg.send_date || '')) : 'noctx';
  if (JL.pendKey && key === JL.pendKey && j.code === 'ok') {
    JL.ok++; JL.pendKey = ''; JL.selfAt = 0;
    return;
  }

  /* v8.29: Vừa tự mình viết tiếp xong — lần kết thúc kế tiếp phần lớn là tiếng vọng của phát súng đó, tạm tha một lượt để tránh bù liên hoàn */
  if (JL.selfAt && nowMs() - JL.selfAt < 90000) { JL.selfAt = 0; return; }

  if (j.code === 'refuse') {
    /* v0.2: Từ chối không còn chỉ nói "đã dừng tay", mà nói rõ cho bạn biết là loại nào, bước tiếp theo nên làm gì */
    JL.lastWhy = j.hard ? 'safety' : 'tone';
    banner('🩹 ' + j.note + (j.hard ? ': Mục này đừng bù, hãy đổi kênh hoặc đổi model rồi thử lại' : ': Mục này không bù, hãy xem chính văn bị đứt ở đâu trước'), 'bad');
    return;
  }
  if (j.code !== 'empty' && j.code !== 'trunc') return;
  /* v0.6: Khi Chống cắt cụt đang bật, loại cắt cụt thuộc về nó quản lý, Phá giáp không can thiệp nữa (phản hồi rỗng/từ chối vẫn thuộc Phá giáp) */
  if (j.code === 'trunc' && (ev.__truncCode || (cfg.trunc && cfg.trunc !== 'off'))) return;

  var g = jailGate(key);
  if (!g.ok) {
    if (g.why === 'max') banner('🩹 Lượt này đã bù ' + JL.count + ' lần mà vẫn có lỗi, tạm dừng tay (kiểm tra kênh hoặc preset)', 'bad');
    else if (g.why === 'rate') banner('🩹 Trong một phút đã bù 6 lần, tạm dừng tay (trông giống như vòng lặp vô tận)', 'bad');
    return;
  }
  var max = 1;
  if (cfg.jailConfirm === false && JL.count < 1) {
    JL.try++; JL.pendKey = key;
    jailSchedule(j, JL.count + 1, max);
    return;
  }
  jailOffer(j);
}

/* ===== 14_trunc.js ===== */
/* ===== 14_trunc.js — Ánh Sáng Luke V0.7 Chống cắt cụt (Tắt / Mức nhẹ v2 / Mức vừa) =====
   Hai tầng chức năng, đừng lẫn lộn:

   A. Phán đoán hậu kỳ (bộ v0.6 đó, giữ nguyên trạng)
   - Tắt     : Không nhìn, không nói, không động. Không tiêu tốn tài nguyên.
   - Mức nhẹ : Chỉ nói lượt này tại sao dừng (gợi ý một dòng), không bù.
   - Mức vừa : Ba loại len / cut / pause tự động bù một lần; gate và unfinished tuyệt đối không bù.
   Viết bù tái sử dụng jailGate / jailSchedule / jailFire / jailLastAi của Phá giáp —
   hai module cùng dùng chung một ngân sách "đơn lượt 1 lần", tự nhiên sẽ không đụng nhau.

   B. Inject tiền kỳ (v0.7 mức nhẹ v2 thêm mới)
   Dán một đoạn prompt vào đuôi tin nhắn user cuối cùng của bản sao request, bốn tầng:
   - L1 Neo số lượng từ : Số chữ thuần của chính văn không ít hơn N (0 chữ = tắt)
   - L2 Giao ước kết bài: Dừng ở hành động / lựa chọn / hậu quả, không tổng kết không nâng tầm không báo trước, kết bài không được là lời thoại
   - L3 Chống tự chứng thực : Không viết những lời kết như "trên đây là", không tự báo số từ
   - F  Neo lấp đầy    : Cứ mỗi N đoạn chèn một câu hỏi ngắn bọc trong <math> (mặc định tắt)
   Ba thiết luật:
   1) Tag độc lập (〔AR-TRUNC 1.0〕…〔/AR-TRUNC〕), mỗi lượt bóc khối cũ trước rồi mới thêm tiếp, gọi liên tục N lần cũng chỉ có một khối;
   2) Chỉ sửa bản sao request parse ra từ JSON.parse, lịch sử chat không đổi dù chỉ một byte;
   3) Toàn bộ văn bản cấm dùng bốn từ cấm (danh sách xem thiết luật §7.2 của _plan/轻档v2_方法):
      JAIL_OWN_RE ở 7_jail.js:18 dùng cả body để match, khớp trúng một lần là cả đoạn sẽ âm thầm bỏ qua phá giáp.
      Do đó neo lấp đầy chỉ viết <math>, tuyệt đối không viết thẻ ngoặc nhọn khác — thẻ ngoặc nhọn khác sẽ kéo theo từ cấm vào chính văn.
*/

var TRUNC_OFF = 'off';
var TRUNC_LIGHT = 'light';
var TRUNC_MEDIUM = 'medium';

/* Mức vừa chỉ bù ba loại này: gate bù rồi cũng cho ra kết quả tương tự; unfinished không phân biệt được dừng thủ công hay đứt luồng, thà không động */
var TRUNC_FIX = { len: 1, cut: 1, pause: 1 };

/* Phiên này: Lý do dừng lần gần nhất + Mức vừa đã bù mấy lần (giống như JL, không ghi vào disk) */
var TR = { code: '', note: '', at: 0, try: 0 };

/* ---------------- Khối inject: tag / whitelist / giới hạn trên ---------------- */

var TRUNC_TAG = 'AR-TRUNC';
var TRUNC_VER = '1.0';
var TRUNC_OPEN = '〔AR-TRUNC ' + TRUNC_VER + '〕';
var TRUNC_CLOSE = '〔/AR-TRUNC〕';
var TRUNC_PAD_OPEN = '〔AR-PAD 1.0〕';
var TRUNC_PAD_CLOSE = '〔/AR-PAD〕';
/* Neo số lượng từ chỉ có bốn giá trị hợp lệ này: 0 = tắt / 800 / 1200 (mặc định) / 1800 */
var TRUNC_LENS = [0, 800, 1200, 1800];
/* Giới hạn trên vòng lặp bóc tách tầng hiển thị: Bình thường tối đa 1 khối lấp đầy, 32 là khóa cứng phòng đầu vào dị dạng */
var TRUNC_PAD_LOOP_MAX = 32;
/* Một lần bóc khối tối đa chạy mấy lượt: Bình thường chỉ có 1 khối, 8 là đệm an toàn dự phòng tàn dư lịch sử */
var TRUNC_STRIP_LOOP = 8;

/* v0.7: Nói tiếng người trên panel.
   TR.note giữ nguyên văn kỹ thuật (card báo cáo / xuất bản ghi là bằng chứng cứng gửi người khác),
   ở đây chỉ chịu trách nhiệm dịch code thành một câu người dùng đọc hiểu — không xuất hiện các từ như max_tokens / finish. */
var TRUNC_HUMAN = {
  gate: 'Bị thượng nguồn chặn, không bù ra được',
  len: 'Đã viết tới giới hạn, câu cú trọn vẹn',
  pause: 'Thượng nguồn yêu cầu tiếp tục',
  cut: 'Dừng ở nửa câu',
  unfinished: 'Không thấy dấu hiệu đứt, tạm thời không động'
};

function truncHuman(code, lv) {
  var s = TRUNC_HUMAN[code] || '';
  if (code === 'cut') {
    if (lv === TRUNC_MEDIUM) s = 'Dừng ở nửa câu, đã yêu cầu viết tiếp';
    else s = 'Dừng ở nửa câu (mức nhẹ chỉ nhắc nhở, không bù)';
  }
  return s;
}

/* ---------------- Cấp độ ---------------- */

function truncLevel(v) {
  return (v === TRUNC_LIGHT || v === TRUNC_MEDIUM) ? v : TRUNC_OFF;
}

function truncLabel(v) {
  var x = truncLevel(v);
  if (x === TRUNC_MEDIUM) return 'Mức vừa';
  if (x === TRUNC_LIGHT) return 'Mức nhẹ';
  return 'Tắt';
}

/* Chip panel: Tắt → Mức nhẹ → Mức vừa → Tắt */
function truncNext(v) {
  var x = truncLevel(v);
  if (x === TRUNC_OFF) return TRUNC_LIGHT;
  if (x === TRUNC_LIGHT) return TRUNC_MEDIUM;
  return TRUNC_OFF;
}

function truncChipLabel() {
  return '✂️ Chống cắt cụt: ' + truncLabel(cfg ? cfg.trunc : TRUNC_OFF);
}

/* ---------------- Neo số lượng từ (0 / 800 / 1200 / 1800) ---------------- */

function truncLenOf(v) {
  var n = Number(v);
  if (n === 0 || n === 800 || n === 1200 || n === 1800) return n;
  return 1200;
}

/* Chip panel: 0 → 800 → 1200 → 1800 → 0 */
function truncLenNext(v) {
  var n = truncLenOf(v);
  var i;
  for (i = 0; i < TRUNC_LENS.length; i++) {
    if (TRUNC_LENS[i] === n) return TRUNC_LENS[(i + 1) % TRUNC_LENS.length];
  }
  return 800;
}

/* Cửa ngõ duy nhất ghi config: Giá trị không hợp lệ đều fallback về 1200 (sanitize dùng chung với panel) */
function truncLenSet(v) {
  var n = truncLenOf(v);
  if (cfg) cfg.truncLen = n;
  return n;
}

function truncLenLabel(v) {
  var n = truncLenOf(v == null && cfg ? cfg.truncLen : v);
  return n > 0 ? ('Số chữ ' + n) : 'Tắt số chữ';
}

function truncLenChipLabel() {
  return '📏 Neo số chữ: ' + (truncLenOf(cfg ? cfg.truncLen : 1200) || 'Tắt');
}

/* ---------------- Khử độc cấu hình ---------------- */

function sanitizeTrunc(d) {
  if (!d || typeof d !== 'object') return;
  d.trunc = truncLevel(d.trunc);
  d.truncTail = d.truncTail !== false;
  d.truncNoCert = d.truncNoCert !== false;
  d.truncStrip = d.truncStrip !== false;
  d.truncLen = truncLenOf(d.truncLen);
  d.truncPad = ar6Pick(d.truncPad, ['off', 'math'], 'off');
  d.truncPadEvery = Math.round(ar6Num(d.truncPadEvery, 2, 1, 6));
}

/* ---------------- Context host (SillyTavern cũ có thể không có gì) ---------------- */

function truncCtx() {
  try {
    if (typeof stCtx === 'function') {
      var c = stCtx();
      if (c) return c;
    }
  } catch (e0) {}
  try {
    var st = HOST && HOST.SillyTavern;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e1) {}
  return null;
}

/* ---------------- Signature từng mục: Preset có tự mang chỉ thị cùng loại hay không ----------------
   Ba mục phán đoán độc lập, mục nào quản mục nấy:
   - tail khớp -> Lược bỏ [Kết bài][Không dùng lời kết] (cả hai là hai mặt của cùng một vấn đề)
   - len  khớp -> Lược bỏ [Độ dài lượt này]
   - pad  khớp -> Ép buộc tắt neo lấp đầy (phần lấp đầy <math> của preset sẽ đánh nhau với chúng ta)
   Cả ba mục đều bị triệt tiêu = Chỉ còn lại má phanh, lúc này cả khối không inject (truncBlock trả về ''). */

var TRUNC_SIG_TAIL = /结尾二选一|不得为对白|收尾契约|完整收尾|End coherently with full sentences|不在完成全部序列前中断/i;
var TRUNC_SIG_LEN = /TARGET_HAN|字数要求|字以上|字左右|正文字数|minimum[^。\n]{0,20}Han/i;
var TRUNC_SIG_PAD = /<math>|secure_log|ta_noise_pad|防截断|anti-truncation|几何定理/i;

function truncSigOf(text) {
  var s = String(text == null ? '' : text);
  return {
    tail: TRUNC_SIG_TAIL.test(s) ? 1 : 0,
    len: TRUNC_SIG_LEN.test(s) ? 1 : 0,
    pad: TRUNC_SIG_PAD.test(s) ? 1 : 0
  };
}

/* Đường dẫn cứu nguy dự phòng: Khi trong request body không quét được gì, ngó qua cài đặt của chính SillyTavern.
   Đường dẫn chính luôn quét từ chính văn của request body (khi launch nội dung preset chắc chắn nằm trong body), ở đây chỉ phòng ngừa "body bị cắt gọt". */
function truncPresetSig() {
  var t = '';
  try {
    var c = truncCtx();
    if (c) {
      if (c.extensionSettings) t += JSON.stringify(c.extensionSettings);
      if (Array.isArray(c.prompts)) {
        for (var i = 0; i < c.prompts.length; i++) {
          var p = c.prompts[i];
          if (!p || p.enabled === false) continue;
          t += '\n' + String(p.content == null ? '' : p.content);
        }
      }
    }
  } catch (e) {}
  return truncSigOf(t);
}

/* ---------------- Văn bản (L1 / L2 / L3 / F) ----------------
   Tiêu chuẩn thống kê số chữ được ghi rõ trong văn bản, tránh model tự ý tính theo kiểu "bao gồm panel".
   Kiểm tra từ cấm: Trong đoạn văn bản này không có Reply directly / editorial system / <Master_input>. */

function truncTextLen(n) {
  return '[Độ dài lượt này] Số chữ thuần của chính văn không ít hơn ' + n + ' chữ (không bao gồm panel, thanh trạng thái, khung tùy chọn, lời dẫn trong ngoặc).' +
    ' Viết đến độ dài này rồi mới kết bài; khi người dùng có yêu cầu độ dài rõ ràng khác thì lấy theo yêu cầu của người dùng.';
}

var TRUNC_TEXT_TAIL = '[Kết bài] Đặt nét bút cuối cùng vào hành động, sự lựa chọn hoặc hậu quả, để lượt kế tiếp có thể tiếp nối dễ dàng.' +
  ' Không đúc kết quy nạp, không cố ý nâng tầm triết lý, không tiết lộ trước diễn biến sau, kết bài không được viết thành lời thoại. Khi chạm trần giới hạn đầu ra, ưu tiên đảm bảo câu cú trọn vẹn:' +
  ' thà ngắn, chứ không được dừng ở nửa câu.';

var TRUNC_TEXT_NOCERT = '[Không dùng lời kết] Không viết những câu như "trên đây là", "hy vọng bạn thích", "tiếp theo sẽ ra sao",' +
  ' cũng không được tuyên bố bản thân đã viết đủ bao nhiêu chữ. Viết xong thì dừng, không cần báo cáo.';

/* Neo lấp đầy: Các câu hỏi ngắn luân phiên. Bọc trong <math> là có chủ ý — nó chỉ là điểm neo "để đoạn kế tiếp có thứ nối vào". */
var TRUNC_PADS = [
  'Câu hỏi ngắn: Hãy chia bước then chốt nhất trong đoạn vừa rồi thành ba hành động có thể làm theo.',
  'Câu hỏi ngắn: Nếu bước tiếp theo thất bại, khả năng cao nhất sẽ tắc ở khâu nào? Chỉ viết một câu.',
  'Câu hỏi ngắn: Dùng một câu nói rõ hiện tại còn thiếu điều gì so với mục tiêu.'
];

function truncPadText(i) {
  var n = Math.abs(Math.round(Number(i) || 0)) % TRUNC_PADS.length;
  return TRUNC_PAD_OPEN + '<math>' + TRUNC_PADS[n] + '</math>' + TRUNC_PAD_CLOSE;
}

/* ---------------- Tạo khối inject ----------------
   Trả về '' hoặc khối hoàn chỉnh. sig có thể truyền vào (test/hot path), không truyền thì tự quét cài đặt SillyTavern. */

function truncBlock(sig) {
  if (!cfg) return '';
  if (cfg.enabled === false || cfg.safe) return '';
  if (truncLevel(cfg.trunc) === TRUNC_OFF) return '';

  var s = sig || truncPresetSig();
  var len = truncLenOf(cfg.truncLen);
  var parts = [];

  /* L1: Neo số lượng từ (tắt = 0 thì lược bỏ cả tầng) */
  if (len > 0 && !s.len) parts.push(truncTextLen(len));
  /* L2 + L3: Giao ước kết bài và Chống tự chứng thực là hai mặt của cùng một vấn đề, preset mang sẵn thì cùng lược bỏ */
  if (cfg.truncTail !== false && !s.tail) parts.push(TRUNC_TEXT_TAIL);
  if (cfg.truncNoCert !== false && !s.tail) parts.push(TRUNC_TEXT_NOCERT);

  /* Cả ba mục đều bị triệt tiêu -> Chỉ còn lại má phanh, không inject (tiết kiệm token, cũng không cướp lời với preset) */
  if (!parts.length) return '';

  var padOn = String(cfg.truncPad || 'off') !== 'off' && !s.pad;
  var every = Math.max(1, Math.min(6, Math.round(Number(cfg.truncPadEvery) || 2)));
  var lines = [];
  var pads = 0;
  var i;
  for (i = 0; i < parts.length; i++) {
    lines.push(parts[i]);
    /* F: Cứ mỗi every đoạn chèn một câu; số đoạn không đủ thì bù một câu ở cuối, đảm bảo đã bật thì chắc chắn có một câu */
    if (padOn && ((i + 1) % every === 0)) {
      lines.push(truncPadText(pads));
      pads++;
    }
  }
  if (padOn && !pads) lines.push(truncPadText(0));

  return TRUNC_OPEN + '\n' + lines.join('\n\n') + '\n' + TRUNC_CLOSE;
}

/* ---------------- Bóc tách: Khối của mình / Khối lấp đầy ---------------- */

function truncStripOnce(s) {
  var str = String(s == null ? '' : s);
  var a = str.indexOf(TRUNC_OPEN);
  if (a < 0) return str;
  var b = str.indexOf(TRUNC_CLOSE, a);
  if (b < 0) return str.slice(0, a).replace(/[ \t\r\n]+$/, '');   /* Chưa đóng: Xóa từ thẻ mở đến cuối */
  var head = str.slice(0, a).replace(/[ \t\r\n]+$/, '');
  var tail = str.slice(b + TRUNC_CLOSE.length).replace(/^[ \t\r\n]+/, '');
  if (!head) return tail;
  return tail ? (head + '\n\n' + tail) : head;
}

function truncStrip(s) {
  var out = String(s == null ? '' : s);
  for (var i = 0; i < TRUNC_STRIP_LOOP; i++) {
    var nx = truncStripOnce(out);
    if (nx === out) break;
    out = nx;
  }
  return out;
}

function truncPadStripOnce(s) {
  var str = String(s == null ? '' : s);
  var a = str.indexOf(TRUNC_PAD_OPEN);
  if (a < 0) {
    return str.replace(/<math>[\s\S]*?<\/math>/g, '');
  }
  var b = str.indexOf(TRUNC_PAD_CLOSE, a);
  if (b < 0) return str.slice(0, a).replace(/[ \t\r\n]+$/, '');
  var head = str.slice(0, a);
  var tail = str.slice(b + TRUNC_PAD_CLOSE.length);
  return (head + tail).replace(/<math>[\s\S]*?<\/math>/g, '');
}

/* Thanh lọc tầng hiển thị: Xóa ký hiệu AR-PAD và <math>...</math>. Hàm thuần túy, có lỗi sẽ do bên gọi tự bắt. */
function truncStripPads(s) {
  var out = String(s == null ? '' : s);
  for (var i = 0; i < TRUNC_PAD_LOOP_MAX; i++) {
    if (out.indexOf(TRUNC_PAD_OPEN) < 0 && out.indexOf('<math>') < 0) break;
    var nx = truncPadStripOnce(out);
    if (nx === out) break;
    out = nx;
  }
  return out;
}

/* ---------------- Áp dụng: Bóc khối cũ trước, rồi dán khối mới sau ----------------
   Tính lũy đẳng: Inject N lần == Inject 1 lần (mỗi lượt đều ghép lại từ base).
   Trả về có thay đổi hay không (boolean; 2_refract dùng nó để quyết định có serialize hay không). */

function truncMsgList(x) {
  if (!x) return null;
  if (Array.isArray(x)) return x;
  if (typeof x === 'object') {
    if (x.request && Array.isArray(x.request.messages)) return x.request.messages;
    if (Array.isArray(x.messages)) return x.messages;
  }
  return null;
}

/* Chính văn dùng cho việc quét signature: Toàn bộ messages, bóc sạch khối của chính mình (nếu không khối của lượt trước sẽ bị coi là "preset tự mang" của lượt này).
   Tin nhắn user cuối cùng dùng base đã bóc, các tin nhắn còn lại cũng chạy qua truncStrip một lượt để ngăn tàn dư lịch sử. */
function truncScanText(msgs, skip, base) {
  var arr = [];
  for (var i = 0; i < msgs.length; i++) {
    var t = String(textOfMsg(msgs[i]) || '');
    t = (i === skip) ? String(base || '') : truncStrip(t);
    if (t) arr.push(t);
  }
  return arr.join('\n');
}

function truncApply(x) {
  var msgs = truncMsgList(x);
  if (!msgs || !msgs.length) return false;
  if (!cfg || cfg.enabled === false || cfg.safe) return false;
  if (truncLevel(cfg.trunc) === TRUNC_OFF) return false;

  /* Hook được load lười (lazy load) ở đây: Chỉ những phiên thực sự đang dùng Chống cắt cụt mới cần đến nó, SillyTavern cũ không có messageFormatter thì âm thầm bỏ qua */
  try { truncPadHook(); } catch (eH) {}

  var idx = -1;
  var i;
  for (i = msgs.length - 1; i >= 0; i--) {
    var mm = msgs[i];
    if (mm && String(mm.role || '') === 'user') { idx = i; break; }
  }
  if (idx < 0) return false;

  var m = msgs[idx];
  var old = String(textOfMsg(m) || '');
  var base = truncStrip(old);
  var sig = truncSigOf(truncScanText(msgs, idx, base));
  var block = truncBlock(sig);

  /* Mức đang bật nhưng preset đã tự mang đầy đủ: Chỉ bóc khối cũ của lượt trước, không dán khối mới */
  if (!block) {
    if (base !== old) { setMsgText(m, base); return true; }
    return false;
  }

  var sep = base ? '\n\n' : '';
  var next = base + sep + block;
  if (next === old) return false;
  setMsgText(m, next);
  return true;
}

/* ---------------- Bóc tách khối lấp đầy ở tầng hiển thị ----------------
   SillyTavern không có removeHook, nên hook chỉ cài một lần, dựa vào cờ HOST.__ar6PadHook + tự ngắt mạch bằng cách đọc cfg bên trong hook.
   SillyTavern cũ không có messageFormatter, addHook không phải hàm, getContext ném lỗi — toàn bộ âm thầm trả về false. */

function truncPadHook() {
  try {
    if (HOST && HOST.__ar6PadHook === 'on') return true;
    var c = truncCtx();
    var f = c && c.messageFormatter;
    if (!f || typeof f.addHook !== 'function') return false;
    var fn = function (mes) {
      try {
        if (!cfg || cfg.safe || cfg.truncStrip === false) return mes;
        if (String(cfg.truncPad || 'off') === 'off') return mes;
        if (typeof mes !== 'string') return mes;
        return truncStripPads(mes);
      } catch (e0) { return mes; }
    };
    f.addHook(fn, { stage: 'beforeRegex', order: 999 });
    if (HOST) HOST.__ar6PadHook = 'on';
    return true;
  } catch (e1) {
    return false;
  }
}

/* ---------------- Phán đoán: Lượt này tại sao dừng ---------------- */

/* Ba loại của finish: Cách viết các trường cùng loại của thượng nguồn không thống nhất, hoa thường đều nhận */
var TRUNC_GATE_FINISH = {
  CONTENT_FILTER: 1, SAFETY: 1, PROHIBITED_CONTENT: 1, SPII: 1,
  BLOCKLIST: 1, RECITATION: 1, IMAGE_SAFETY: 1, REFUSAL: 1
};

function truncGateFinish(fin) {
  return !!TRUNC_GATE_FINISH[String(fin || '').toUpperCase()];
}

function truncLenFinish(fin) {
  var f = String(fin || '').toUpperCase();
  return f === 'LENGTH' || f === 'MAX_TOKENS';
}

function truncPauseFinish(fin) {
  return String(fin || '').toLowerCase() === 'pause_turn';
}

/* ---------------- Phán đoán: Lượt này tại sao dừng ----------------
   Trả về { code, note }, độ ưu tiên của code: gate > len > pause > cut > unfinished > '' (bình thường).
   note là một câu có thể hiển thị trực tiếp cho người dùng xem (dòng trên panel, dòng trên card đều dùng nó). */
function truncInspect(ev) {
  if (!ev) return { code: '', note: '' };
  var fin = String(ev.finish || '');
  var tail = String(ev.tail || '');
  var mc = (typeof ev.mesChars === 'number') ? ev.mesChars : Number(ev.outputChars || 0);

  /* 1) gate: Thượng nguồn nói rõ bị chặn, hoặc chính văn là một bức thư từ chối (nhận diện mẫu câu phỏng theo Phá giáp 7_jail.js:196) */
  if (truncGateFinish(fin)) return { code: 'gate', note: 'Tầng an toàn thượng nguồn chặn (' + fin + ')' };
  if (mc > 0 && tail && mc < 300 &&
      typeof JAIL_REFUSE_RE !== 'undefined' && JAIL_REFUSE_RE.test(tail)) {
    var hard = (typeof JAIL_SAFETY_RE !== 'undefined') && JAIL_SAFETY_RE.test(tail);
    return { code: 'gate', note: hard ? 'Chính văn là văn mẫu từ chối của tầng an toàn' : 'Chính văn là văn mẫu từ chối' };
  }

  /* 2) len: Chạm trần giới hạn token */
  if (truncLenFinish(fin)) return { code: 'len', note: 'Chạm giới hạn max_tokens (' + fin + ')' };

  /* 3) pause: Thượng nguồn yêu cầu tiếp tục */
  if (truncPauseFinish(fin)) return { code: 'pause', note: 'Thượng nguồn yêu cầu tiếp tục (pause_turn)' };

  /* 4)(5) finish không cung cấp: Xem cấu trúc chính văn. Cấu trúc bị đứt = cut; không nhìn ra đứt gãy = unfinished (không bù, chỉ nhắc nhở) */
  if (!fin && tail) {
    var why = '';
    try { why = jailTruncWhy(tail, mc > 0 ? mc : tail.length); } catch (eW) { why = ''; }
    if (why) return { code: 'cut', note: why };
    return { code: 'unfinished', note: 'Chính văn có, nhưng không trả finish (có thể chỉ dừng lại ở đây)' };
  }
  return { code: '', note: '' };
}

/* ---------------- Hậu kỳ: Ghi chép + Nhắc nhở + (Mức vừa) Bù một lần ----------------
   pre là phán đoán đã tính trước trong finish() (trong cùng một lượt chỉ phán đoán một lần, đỡ phải tính hai lượt).
   Giá trị trả về = code của lượt này, chuyển giao cho Phá giáp quyết định xem nó có cần quản lý cắt cụt nữa hay không. */
function truncAfterFinish(ev, pre) {
  if (!cfg || truncLevel(cfg.trunc) === TRUNC_OFF) return '';
  if (!ev || ev.status !== 200 || ev.error) return '';
  if (ev.internal) return '';                 /* Request nội bộ không có sản phẩm chat, không phán đoán */

  /* Vừa tự mình bù xong — lần kết thúc kế tiếp phần lớn là tiếng vọng của phát súng đó, tạm tha một lượt (dùng chung một phanh hãm ở :469 của Phá giáp).
     ★ Chỉ return, tuyệt đối không xóa JL.selfAt ở đây: Điểm reset về 0 bắt buộc phải duy nhất.
     trunc chạy trước jail (3_net.js:309-315), nếu xóa ở đây thì phanh hãm 90 giây của jail coi như vô dụng,
     tiếng vọng chậm sẽ bắn thêm một phát trong cửa sổ 20–90 giây = bù liên hoàn. Hiện tại jailAfterFinish sẽ đơn độc tiêu thụ timestamp này;
     khi jail tắt nó sẽ tự động hết hạn, không cần ai xóa. */
  if (typeof JL !== 'undefined' && JL.selfAt && nowMs() - JL.selfAt < 90000) {
    return '';
  }

  var t = pre || truncInspect(ev);
  if (!t || !t.code) return '';
  TR.code = t.code;
  TR.note = t.note;
  TR.at = nowMs();

  /* Mức vừa cũng chỉ bù ba loại này; mức nhẹ tới đây chỉ còn nhắc nhở */
  var willFix = truncLevel(cfg.trunc) === TRUNC_MEDIUM && !!TRUNC_FIX[t.code] &&
    cfg.enabled && !cfg.safe;                 /* Van tổng tắt / đang ở chế độ an toàn cứu nguy thì không tự ý động thủ */
  if (!willFix) {
    try { banner('✂️ Lượt này dừng ở: ' + (truncHuman(t.code, truncLevel(cfg.trunc)) || t.note), t.code === 'unfinished' ? 'gray' : 'warn'); } catch (eB) {}
    return t.code;
  }

  /* Ngân sách viết bù dùng chung với Phá giáp: Nó vừa bù xong / vừa bù xong chưa phản hồi / quá nhiều lần trong một phút thì dừng tay ở đây */
  var cur = jailLastAi();
  var key = cur ? (String(cur.idx) + '|' + String(cur.msg.send_date || '')) : 'noctx';
  var g = jailGate(key);
  if (!g.ok) {
    try { banner('✂️ Lượt này dừng ở: ' + (truncHuman(t.code, truncLevel(cfg.trunc)) || t.note), 'warn'); } catch (eB2) {}
    return t.code;
  }
  TR.try++;
  /* Đơn lượt tối đa 1 lần: n dùng JL.count + 1, max cố định 1; polling/khóa/entrypoint viết tiếp toàn bộ đi theo bộ của Phá giáp */
  jailSchedule({ code: 'trunc', note: t.note }, JL.count + 1, 1);
  return t.code;
}

/* Panel một dòng nói rõ cấp độ + lần gần nhất tại sao dừng + (v0.7) neo số lượng từ
   Lưu ý: Vị trí của hai đoạn "Lần này chưa từng bù" và "Lần này đã bù N lần" không được xê dịch — các test case lịch sử dùng chúng để khớp tiền tố. */
function truncStatLine() {
  var lv = truncLabel(cfg ? cfg.trunc : TRUNC_OFF);
  if (truncLevel(cfg ? cfg.trunc : TRUNC_OFF) === TRUNC_OFF) return 'Chống cắt cụt: Tắt (không phán đoán, không nhắc nhở, không bù)';
  var done = TR.try ? ('Lần này đã bù ' + TR.try + ' lần') : 'Lần này chưa từng bù';
  var line = 'Chống cắt cụt: ' + lv + ' · ' + done;
  if (TR.code) {
    var hum = truncHuman(TR.code, truncLevel(cfg ? cfg.trunc : TRUNC_OFF));
    if (hum) line += ' · Lần gần nhất: ' + hum;
  }
  line += ' · ' + truncLenLabel();
  return line;
}

/* ===== 8_probe.js ===== */
/* ============================================================================
 * Anti-Route v7.2 — 8/8 Sàng lọc danh tính (Kiểm tra sàng lọc token hỏng)
 *
 * Công dụng: Đầu dò hạ cấp bất đối xứng.
 *   - Chép sai (tỷ lệ trúng thấp) ⇒ Khả năng cao không phải model cao cấp mục tiêu (rẻ, có thể chạy thường xuyên)
 *   - Chép đúng (tỷ lệ trúng cao) ⇒ Không thể chứng minh là model mục tiêu, chỉ có thể nói "không giống kẻ đóng thế giá rẻ"
 * Thiết luật: Chỉ gửi một request nhỏ độc lập (không chạm vào request chat), thất bại không ném lỗi, không ghi vào chat.
 * ========================================================================== */

var ID_KEY = 'ar7.id';
var ID_ITEMS = [
  'StarSrvGroupBody',
  'intFragmentation',
  'Kv7Qm2Lz9RxT',
  'b3f9c1e7a2d84b06',
  'NlPz4Wq8Jh2V',
  'FragmentationCacheXn3',
  'SrvGroupKernelBody',
  'Qz9Lm4Tb7Wn2',
  '7fa2c9e1d3b84605',
  'Hn5Kp3Xs8Qv1',
  'ThreadLocalFragmentation',
  'Xz6Wq9Lm3Rt7'
];
var ID = { running: false, result: null, used: [] };

function idLoad() {
  try {
    var s = JSON.parse(localStorage.getItem(ID_KEY) || '{}');
    ID.used = Array.isArray(s.used) ? s.used : [];
    ID.result = s.result || null;
  } catch (e) { ID.used = []; ID.result = null; }
}

function idSave() {
  try {
    localStorage.setItem(ID_KEY, JSON.stringify({ used: ID.used.slice(-24), result: ID.result }));
  } catch (e) {}
}

/* Luân chuyển: Ưu tiên mục chưa chạy, chạy hết một lượt mới reset */
function idPick() {
  idLoad();
  var pool = [];
  for (var i = 0; i < ID_ITEMS.length; i++) {
    if (ID.used.indexOf(ID_ITEMS[i]) < 0) pool.push(ID_ITEMS[i]);
  }
  if (pool.length < 6) { ID.used = []; pool = ID_ITEMS.slice(); }
  return pool.slice(0, 8);
}

function idBody(items) {
  var lines = [];
  for (var i = 0; i < items.length; i++) lines.push((i + 1) + ') ' + items[i]);
  var user = 'Dưới đây có ' + items.length + ' dòng định danh. Vui lòng sao chép nguyên văn từng ký tự của mỗi dòng (chữ hoa chữ thường, chữ số, chữ cái không được sửa bất kỳ ký tự nào), ' +
    'đồng thời phỏng đoán xem nó có khả năng bắt nguồn từ hệ thống nào nhất (một câu, dưới mười chữ).\n' +
    'Chỉ xuất ra một mảng JSON duy nhất, không xuất bất kỳ lời giải thích nào, không bọc bằng khối code, định dạng:\n' +
    '[{"id":"văn bản gốc","copy":"văn bản bạn sao chép","guess":"phỏng đoán"}]\n\n' + lines.join('\n');
  return {
    messages: [
      { role: 'system', content: 'Bạn là một bộ sao chép nguyên văn từng ký tự. Chỉ sao chép, không giải thích, không sửa bất kỳ lỗi chính tả nào.' },
      { role: 'user', content: user }
    ],
    max_tokens: 800,
    stream: false
  };
}

function idNorm(s) {
  return String(s == null ? '' : s).replace(/^[\s"'`「」『』]+|[\s"'`「」『』]+$/g, '').replace(/\s+/g, '');
}

/* Tách lấy [{id,copy}] từ văn bản: Toàn bộ JSON → Khối code → Cắt mảng đầu tiên → Regex từng dòng */
function idEntries(text) {
  var t = String(text || '');
  var tries = [t];
  var f = /```(?:json)?\s*([\s\S]*?)```/i.exec(t);
  if (f) tries.push(f[1]);
  var a = t.indexOf('['), b = t.lastIndexOf(']');
  if (a >= 0 && b > a) tries.push(t.slice(a, b + 1));
  for (var i = 0; i < tries.length; i++) {
    try {
      var arr = JSON.parse(tries[i]);
      if (Array.isArray(arr)) return arr;
    } catch (e) {}
  }
  var out = [];
  var rx = /"id"\s*:\s*"([^"]*)"[\s\S]{0,200}?"copy"\s*:\s*"([^"]*)"/gi;
  var m;
  while ((m = rx.exec(t)) && out.length < 40) out.push({ id: m[1], copy: m[2] });
  return out;
}

function idScore(text, items) {
  var rows = [];
  var entries = idEntries(text);
  for (var i = 0; i < items.length; i++) {
    var want = items[i];
    var got = '';
    for (var k = 0; k < entries.length; k++) {
      var e = entries[k] || {};
      var eid = idNorm(e.id), ecopy = idNorm(e.copy);
      if (eid === idNorm(want) || ecopy === idNorm(want)) { got = String(e.copy || e.id || ''); break; }
    }
    if (!got && entries.length === items.length) got = String(entries[i].copy || entries[i].id || '');
    rows.push({ item: want, got: got, ok: idNorm(got) === idNorm(want) });
  }
  return rows;
}

function idVerdict(hit, n) {
  if (!n) return { code: 'error', label: 'Chưa đo', note: 'Không lấy được response có thể phân giải' };
  var rate = hit / n;
  var w = wilson(hit, n);
  var ci = (Math.round(w.lo * 1000) / 10) + '% ~ ' + (Math.round(w.hi * 1000) / 10) + '%';
  if (n < 6) return { code: 'unknown', label: 'Mẫu không đủ', note: 'Mới chỉ chạy ' + n + ' mục, kết luận không khả dụng (95% CI ' + ci + ')' };
  if (rate < 0.5) return { code: 'fail', label: 'Không giống cao cấp', note: 'Khớp ' + hit + '/' + n + ' (' + Math.round(rate * 100) + '%, 95% CI ' + ci + ') ⇒ Khả năng cao không phải model mục tiêu, hoặc lần này đã bị hạ cấp' };
  if (rate > 0.85) return { code: 'pass', label: 'Nghi là cao cấp', note: 'Khớp ' + hit + '/' + n + ' (' + Math.round(rate * 100) + '%, 95% CI ' + ci + ') ⇒ Không thể chứng minh danh tính, chỉ nói lên rằng "không giống kẻ đóng thế giá rẻ"' };
  return { code: 'mid', label: 'Chưa định', note: 'Khớp ' + hit + '/' + n + ' (' + Math.round(rate * 100) + '%, 95% CI ' + ci + ') ⇒ Mẫu vẫn chưa phân tách được, hãy chạy lại lần nữa' };
}

function runIdentityProbe() {
  if (ID.running) return Promise.resolve({ ok: false, msg: 'Đang chạy, vui lòng chờ' });
  var base = String(cfg.dualBase || (lastReq && lastReq.base) || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: 'Hãy điền Base reverse proxy trước (hoặc chạy bình thường một lượt trước)' });
  var items = idPick();
  if (!items.length) return Promise.resolve({ ok: false, msg: 'Kho đầu dò rỗng' });
  var url = openAIUrl(base);
  var body = idBody(items);
  ID.running = true;
  return probeOnce(url, body, 45000).then(function (r) {
    ID.running = false;
    var text = String(r.raw || '');
    if (!text) {
      var bad = { at: nowMs(), n: items.length, hit: 0, verdict: 'error', note: 'Đầu dò không có response: ' + (r.err || ('HTTP ' + r.status)), rows: [] };
      ID.result = bad; idSave(); render();
      return { ok: false, msg: bad.note };
    }
    var rows = idScore(text, items);
    var hit = 0;
    for (var i = 0; i < rows.length; i++) if (rows[i].ok) hit++;
    var v = idVerdict(hit, rows.length);
    ID.result = {
      at: nowMs(), n: rows.length, hit: hit, verdict: v.code,
      label: v.label, note: v.note, model: String(r.model || ''), rows: rows
    };
    for (var k = 0; k < items.length; k++) if (ID.used.indexOf(items[k]) < 0) ID.used.push(items[k]);
    idSave(); render();
    return { ok: true, hit: hit, n: rows.length, verdict: v.code, label: v.label, note: v.note };
  })['catch'](function (e) {
    ID.running = false;
    return { ok: false, msg: String(e && e.message || e) };
  });
}

function idCard() {
  var r = ID.result;
  if (!r) return '<div class="ar6-note">Sàng lọc danh tính: Chưa chạy. Bấm "Sàng lọc danh tính" — chép sai ⇒ Khả năng cao không phải model cao cấp; chép đúng ⇒ Chỉ loại trừ kẻ đóng thế giá rẻ, không chứng minh được danh tính.</div>';
  var color = r.verdict === 'fail' ? 'ar6-bad' : (r.verdict === 'pass' ? 'ar6-ok' : 'ar6-warn');
  var h = '<div class="ar6-note"><span class="' + color + '">' + esc(r.label || r.verdict) + '</span> · ' + esc(r.note || '') + '</div>';
  var rows = r.rows || [];
  if (rows.length) {
    h += '<div class="ar6-kv">';
    for (var i = 0; i < rows.length && i < 10; i++) {
      h += '<span class="ar6-k">' + (rows[i].ok ? '✅' : '❌') + ' ' + esc(rows[i].item) + '</span>' +
        '<span class="ar6-v">' + esc(rows[i].got || '(Chưa chép)') + '</span>';
    }
    h += '</div>';
  }
  return h;
}

function idFooter() {
  var r = ID.result;
  if (!r) return 'Danh tính Chưa đo';
  return 'Danh tính ' + (r.label || r.verdict) + ' ' + r.hit + '/' + r.n;
}

/* ===== 16_base.js ===== */
/* ============================================================================
 * Anti-Route v8 — 16/Base Baseline hành vi
 *
 * Mục đích: Tên có thể ngụy tạo, tốc độ và thói quen suy nghĩ thì không thể ngụy tạo.
 * Ghi lại thời gian TTFT / tốc độ xuất chữ / thói quen suy nghĩ của vài lượt gần đây
 * cho "kênh này + tên request này". Khi lượt này lệch rõ rệt so với trung vị,
 * để lại một dòng chữ vàng nhỏ trên card và banner nhắc nhở "cảm giác không giống nó".
 *
 * Thiết luật:
 *   - Chỉ gợi ý. Không sửa rec.code, không ghi sổ cái (ledAdd), không chặn request, không phán đoán bị tráo.
 *   - Khi đóng van (cfg.base !== 'on'): basePush không ghi, baseJudge nhất loạt trả về null.
 *   - Khởi động nguội: Ít hơn 12 mẫu **lịch sử** thì chưa có baseline, không phán đoán (tính cả lượt này phải đến lượt thứ 13).
 *   - Baseline chỉ học từ "những lượt bình thường": Các lượt bị tráo / không suy nghĩ không được đưa vào kho, nếu không sẽ học theo dạng của bên giả mạo.
 *
 * Lưu trữ: ar6.base = { [kênh hash|tên request]: [ {t,s,c,r,at}, ... ] }, mỗi key tối đa
 * 24 mục, vượt quá sẽ bỏ mục cũ nhất; các mẫu quá 30 ngày không cập nhật sẽ không tham gia phán đoán nữa.
 * ========================================================================== */

var BASE_KEY = 'ar6.base';
var BASE_MAX = 24;        /* Mỗi key giữ tối đa 24 mục, vượt quá sẽ bỏ mục cũ nhất */
var BASE_MIN_N = 12;      /* Ít hơn 12 mẫu lịch sử thì chưa có baseline, không phán đoán */
var BASE_EXPIRE = 30 * 24 * 3600 * 1000;  /* 30 ngày */

function baseOn() {
  try { return !!cfg && String(cfg.base == null ? '' : cfg.base) === 'on'; }
  catch (e) { return false; }
}

function baseRead() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(BASE_KEY) || '{}');
    if (!o || typeof o !== 'object' || Array.isArray(o)) return {};
    return o;
  } catch (e) { return {}; }
}

function baseWrite(o) {
  try { HOST.localStorage.setItem(BASE_KEY, JSON.stringify(o)); } catch (e) {}
}

/* Kênh + Tên request: Baseline của chat và reasoner dưới cùng một reverse proxy bắt buộc phải tách riêng,
   nếu không "phần lớn có suy nghĩ" sẽ bị số 0 của model kia kéo phẳng dẫn tới báo sai. */
function baseId(rec) {
  var b = '';
  try { b = String((rec && rec.base) || (typeof statBase === 'function' ? statBase() : '') || ''); }
  catch (e) { b = ''; }
  var m = '';
  try { m = String((rec && rec.req) || ''); } catch (e) { m = ''; }
  return (b ? String(hashStr(b)) : 'local') + '|' + m;
}

function baseOf(k) {
  var all = baseRead();
  var arr = all[k];
  return Array.isArray(arr) ? arr : [];
}

/* Số lượng token suy nghĩ: Đọc được từ đường vòng thì dùng số thật, không đọc được trả về 0 (chỉ có thể dùng cờ 0/1 dự phòng) */
function baseThoughts(rec) {
  try {
    if (typeof PEEKS === 'undefined' || !PEEKS || !rec || rec.rid == null) return 0;
    var pk = PEEKS[rec.rid];
    if (!pk || pk.thoughts == null) return 0;
    var n = Number(pk.thoughts);
    return (isFinite(n) && n > 0) ? n : 0;
  } catch (e) { return 0; }
}

/* Tốc độ xuất chữ: Chỉ tính "giai đoạn xuất chữ", bóc tách thời gian chờ và suy nghĩ trước ký tự đầu tiên ra khỏi mẫu số,
   nếu không "lượt này không suy nghĩ" sẽ làm tốc độ tự tăng gấp đôi, bị phán đoán nhầm thành "xuất chữ nhanh". */
function baseSpeed(chars, total, ttft) {
  var span = Number(total) - Number(ttft);
  if (!isFinite(chars) || chars <= 0) return 0;
  if (!isFinite(span) || span <= 0) return 0;
  return chars / (span / 1000);
}

/* Một lượt → Một mẫu. Không nhận được (quá ít chữ / không có ký tự đầu / không có thời gian hao tổn) trả về null. */
function baseRow(rec) {
  if (!rec) return null;
  var chars = Number(rec.chars);
  var ttft = Number(rec.ttft);
  var total = Number(rec.total);
  if (!isFinite(chars) || chars < 50) return null;
  if (!isFinite(ttft) || ttft <= 0) return null;
  if (!isFinite(total) || total <= 0) return null;
  var s = baseSpeed(chars, total, ttft);
  var c = (rec.think === 0 || rec.think === 1) ? rec.think : null;
  var r = null;
  if (c !== null) {
    var tk = baseThoughts(rec);
    /* r = Token suy nghĩ / Số chữ chính văn; khi không lấy được token suy nghĩ dùng 1 để biểu thị "lượt này có suy nghĩ".
       Không viết thành 1/chars: Việc đó sẽ đè trung vị xuống khoảng 0.002, ngưỡng 0.1 sẽ không bao giờ chạm tới được. */
    r = c === 0 ? 0 : (tk > 0 ? tk / chars : 1);
  }
  return {
    t: Math.round(ttft),
    s: Math.round(s * 10) / 10,
    c: c,
    r: (r === null) ? null : (Math.round(r * 1000) / 1000),
    at: Date.now()
  };
}

function baseMed(arr) {
  var a = [];
  for (var i = 0; i < arr.length; i++) {
    /* Chỉ nhận số thực sự: Number(null)===0 sẽ coi dòng hỏng là "0 mili giây" kéo tụt trung vị */
    if (typeof arr[i] !== 'number' || !isFinite(arr[i])) continue;
    a.push(arr[i]);
  }
  if (!a.length) return 0;
  a.sort(function (x, y) { return x - y; });
  var m = a.length >> 1;
  return (a.length % 2) ? a[m] : (a[m - 1] + a[m]) / 2;
}

function baseRowOk(r) {
  return !!r && typeof r === 'object' &&
    typeof r.t === 'number' && isFinite(r.t) && r.t > 0 &&
    typeof r.s === 'number' && isFinite(r.s) && r.s > 0;
}

/* Baseline chỉ đại diện cho "trước đây": Lượt này nếu đã vào kho, khi phán đoán hãy bóc nó ra khỏi đuôi mẫu;
   đồng thời bỏ đi các mẫu đã hết hạn. */
function baseHist(arr, rec) {
  var out = [];
  var now = Date.now();
  for (var i = 0; i < arr.length; i++) {
    if (!baseRowOk(arr[i])) continue;
    var at = Number(arr[i].at);
    if (isFinite(at) && at > 0 && now - at > BASE_EXPIRE) continue;
    out.push(arr[i]);
  }
  if (out.length && rec) {
    var row = baseRow(rec);
    var last = out[out.length - 1];
    if (row && Number(last.t) === row.t && Number(last.s) === row.s && last.c === row.c) out.pop();
  }
  return out;
}

function baseSec(ms) {
  return (Math.round(Number(ms) / 100) / 10).toFixed(1);
}

/* Ghi lại một mục. Chỉ nhận lượt bình thường có chars>=50 và ttft>0;
   các lượt bị tráo / không suy nghĩ không vào kho, nếu không baseline sẽ học theo hình dạng bên giả mạo. */
function basePush(req, rec) {
  try {
    if (!rec) { rec = req; req = null; }
    if (!rec || !baseOn()) return null;
    if (rec.internal) return null;
    if (rec.code === 'diff' || rec.code === 'thin' || rec.code === 'skip') return null;
    var row = baseRow(rec);
    if (!row) return null;
    var k = baseId(rec);
    var all = baseRead();
    /* Tiện tay dọn sạch các key cũ trong toàn kho, tránh việc thử qua bao nhiêu proxy là để lại bấy nhiêu */
    var now = Date.now();
    for (var kk in all) {
      if (!Object.prototype.hasOwnProperty.call(all, kk)) continue;
      var vv = all[kk];
      if (!Array.isArray(vv) || !vv.length) { delete all[kk]; continue; }
      var lastAt = Number(vv[vv.length - 1] && vv[vv.length - 1].at);
      if (isFinite(lastAt) && lastAt > 0 && now - lastAt > BASE_EXPIRE) delete all[kk];
    }
    var arr = Array.isArray(all[k]) ? all[k] : [];
    arr.push(row);
    if (arr.length > BASE_MAX) arr = arr.slice(arr.length - BASE_MAX);
    all[k] = arr;
    baseWrite(all);
    return row;
  } catch (e) { return null; }
}

/* Phán đoán một lượt. Mẫu không đủ trả về null; khớp trúng trả về { why, line }.
   Thứ tự: Nhanh → Suy nghĩ về 0 → Tốc độ → Chậm.
   "Suy nghĩ về 0" xếp trước tốc độ: Một lượt không suy nghĩ sẽ làm mẫu số tốc độ nhỏ đi, giải thích điều cụ thể nhất trước. */
function baseJudge(req, rec) {
  try {
    if (!rec) { rec = req; req = null; }
    if (!rec || !baseOn()) return null;
    /* Phán đoán và lưu kho dùng cùng một ngưỡng: Vừa nói "lượt này dữ liệu không khả dụng", vừa dùng nó đưa ra kết luận là không đúng */
    if (rec.internal) return null;
    var row = baseRow(rec);
    if (!row) return null;
    var hist = baseHist(baseOf(baseId(rec)), rec);
    if (hist.length < BASE_MIN_N) return null;

    var tArr = [];
    var sArr = [];
    var rArr = [];
    for (var i = 0; i < hist.length; i++) {
      tArr.push(hist[i].t);
      sArr.push(hist[i].s);
      /* Chỉ những lượt biết rõ ràng "có nghĩ hay không" mới vào mẫu số suy nghĩ */
      if (hist[i].c === 0 || hist[i].c === 1) rArr.push(Number(hist[i].r) || 0);
    }
    var tMed = baseMed(tArr);
    var sMed = baseMed(sArr);
    var rMed = baseMed(rArr);

    var ttft = Number(rec.ttft);
    var s = row.s;

    /* 1) Ký tự đầu tiên bất ngờ nhanh hơn gấp đôi (bản thân trung vị quá nhỏ thì không phán đoán: Dao động 500ms không có ý nghĩa) */
    if (isFinite(ttft) && ttft > 0 && tMed > 800 && ttft < tMed / 2.2) {
      return {
        why: 'fast',
        line: 'Ký tự đầu lượt này ' + baseSec(ttft) + 's, nhanh hơn gấp đôi so với trung vị ' + baseSec(tMed) + 's của kênh này'
      };
    }
    /* 2) Bình thường có nghĩ, lượt này một câu cũng không nghĩ */
    if (rec.think === 0 && rMed > 0.1) {
      return {
        why: 'think',
        line: 'Kênh này gần ' + hist.length + ' lượt đa phần đều có suy nghĩ, lượt này hoàn toàn không có'
      };
    }
    /* 3) Tốc độ xuất chữ tăng gấp đôi.
       Ký tự đầu bản thân đã rất chậm thì không phán đoán tốc độ: Mẫu số bị ký tự đầu nuốt mất, cửa sổ còn lại tính ra tất nhiên sẽ lệch nhanh,
       đó là "mở đầu chậm", không phải "xuất chữ nhanh". */
    var slowStart = (isFinite(ttft) && ttft > 0 && tMed > 0 && ttft > tMed * 1.5);
    if (!slowStart && s > 0 && sMed > 0 && s > sMed * 2.2) {
      return {
        why: 'rate',
        line: 'Lượt này xuất chữ gấp ' + (s / sMed).toFixed(1) + ' lần trung vị của kênh này'
      };
    }
    /* 4) Chậm đi rất nhiều: Cách dùng từ mềm mỏng, chậm vốn dĩ có thể chỉ do mạng */
    if (isFinite(ttft) && ttft > 0 && tMed > 0 && ttft > tMed * 3) {
      return {
        why: 'slow',
        line: 'Ký tự đầu lượt này ' + baseSec(ttft) + 's, chậm hơn bình thường một chút, cũng có thể chỉ là dao động mạng'
      };
    }
    return null;
  } catch (e) { return null; }
}

/* Chỉ xuất một dòng chữ này, card và banner dùng chung, tránh hai nơi viết lại hai lần */
function baseLine(rec) {
  try {
    var bj = baseJudge(rec);
    return (bj && bj.line) ? String(bj.line) : '';
  } catch (e) { return ''; }
}

/* ===== 17_shape.js ===== */
/* ============================================================================
 * Anti-Route v8 — 17/Shape Fingerprint cấu trúc
 *
 * Mục đích: Tên có thể ngụy tạo, cảm giác tay có thể bắt chước, hình dạng response rất khó giả vờ mãi.
 * Ghi lại fingerprint cấu trúc của response body trong vài lượt gần đây cho "kênh này + tên request này"
 * (có usage hay không, tập hợp key của usage, có trường token suy nghĩ hay không,
 * có modelVersion hay không, giá trị của finish). Khi lượt này xuất hiện chuỗi chưa từng thấy bao giờ,
 * để lại một dòng chữ vàng nhỏ trên banner và card nhắc nhở "định dạng không giống nó".
 *
 * Thiết luật:
 *   - Chỉ gợi ý. Không sửa rec.code, không ghi sổ cái (ledAdd), không chặn request, không phán đoán bị tráo.
 *   - Chỉ đọc PEEKS[rid] (lấy mẫu đường vòng đã clone sẵn ở nơi khác), tuyệt đối không chạm vào HTTP response body.
 *   - Khi đóng van (cfg.shape !== 'on'): shapePush không ghi, shapeJudge nhất loạt trả về null.
 *   - Khởi động nguội: Ít hơn 8 mẫu **lịch sử** thì chưa có baseline fingerprint, không phán đoán (tính cả lượt này phải đến lượt thứ 9).
 *   - Chỉ học từ "những lượt bình thường": Các lượt bị tráo / không suy nghĩ không vào kho, nếu không sẽ học theo dạng bên giả mạo.
 *
 * Fingerprint tính thế nào (5 đoạn, nối bằng |):
 *   u = Có usage hay không; k = 6 key đầu tiên của usage sau khi sắp xếp; t = Có trường token suy nghĩ hay không;
 *   v = Có modelVersion hay không; f = Giá trị của finish.
 *   absorbPeek của 3_net.js không lưu object usage, chỉ lưu bốn bộ đếm thoughts / reasoning /
 *   out / prompt; shapeUsage ghép chúng lại thành hình dạng của usage rồi mới tính, không đoán mò.
 *
 * Lưu trữ: ar6.shape = { [kênh hash|tên request]: [ {sig,at}, ... ] }, mỗi key tối đa
 * 24 mục, vượt quá sẽ bỏ mục cũ nhất; các mẫu quá 30 ngày không cập nhật sẽ không tham gia phán đoán nữa.
 * ========================================================================== */

var SHAPE_KEY = 'ar6.shape';
var SHAPE_MAX = 24;       /* Mỗi key giữ tối đa 24 mục, vượt quá sẽ bỏ mục cũ nhất */
var SHAPE_MIN_N = 8;      /* Ít hơn 8 mẫu lịch sử thì chưa có baseline fingerprint, không phán đoán */
var SHAPE_EXPIRE = 30 * 24 * 3600 * 1000;  /* 30 ngày */

function shapeOn() {
  try { return !!cfg && String(cfg.shape == null ? '' : cfg.shape) === 'on'; }
  catch (e) { return false; }
}

function shapeRead() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(SHAPE_KEY) || '{}');
    if (!o || typeof o !== 'object' || Array.isArray(o)) return {};
    return o;
  } catch (e) { return {}; }
}

function shapeWrite(o) {
  try { HOST.localStorage.setItem(SHAPE_KEY, JSON.stringify(o)); } catch (e) {}
}

/* Kênh + Tên request: Tiêu chuẩn phải giống hệt baseId của 16_base.js,
   tái sử dụng được thì tái sử dụng (baseId là hàm toàn cục), tránh việc hai bộ key ai làm việc nấy. */
function shapeId(rec) {
  try {
    if (typeof baseId === 'function') return String(baseId(rec) || '');
  } catch (eBase) {}
  try {
    var b = '';
    try { b = String((rec && rec.base) || (typeof statBase === 'function' ? statBase() : '') || ''); }
    catch (e1) { b = ''; }
    var m = '';
    try { m = String((rec && rec.req) || ''); } catch (e2) { m = ''; }
    return (b ? String(hashStr(b)) : 'local') + '|' + m;
  } catch (e) { return ''; }
}

function shapeOf(k) {
  try {
    var all = shapeRead();
    var arr = all[k];
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

/* Ghép các bộ đếm rải rác trong PEEKS lại thành hình dạng của usage:
   absorbPeek lưu thoughts / reasoning / out / prompt; nếu sau này thực sự lưu
   object usage thì ưu tiên dùng nó. Không có cái nào = Lượt này không nhìn thấy usage. */
function shapeUsage(pk) {
  try {
    if (!pk || typeof pk !== 'object') return null;
    var u = pk.usage;
    if (u && typeof u === 'object' && !Array.isArray(u)) return u;
    /* Tên key thực tế mà absorbPeek lưu (chuẩn nhất): thoughtsTokenCount / reasoning_tokens /
       prompt_tokens … Bản thân các tên này chính là fingerprint của kênh, ưu tiên dùng nó. */
    var uk = String(pk.usageKeys == null ? '' : pk.usageKeys);
    if (uk) {
      var ks0 = uk.split(',');
      var o0 = {};
      for (var j = 0; j < ks0.length; j++) {
        if (ks0[j]) o0[String(ks0[j])] = 1;
      }
      if (shapeKeys(o0).length) return o0;
    }
    var o = {};
    var any = false;
    var names = ['thoughts', 'reasoning', 'out', 'prompt'];
    for (var i = 0; i < names.length; i++) {
      var v = pk[names[i]];
      if (typeof v === 'number' && isFinite(v)) { o[names[i]] = v; any = true; }
    }
    return any ? o : null;
  } catch (e) { return null; }
}

function shapeKeys(u) {
  try {
    if (!u || typeof u !== 'object') return [];
    return Object.keys(u).sort();
  } catch (e) { return []; }
}

/* Trong usage có trường token suy nghĩ hay không: Khớp tên key là tính, không xét giá trị (0 cũng là "có"). */
function shapeThinks(u) {
  try {
    var ks = shapeKeys(u);
    var re = /thought|reasoning|thinking/i;
    for (var i = 0; i < ks.length; i++) if (re.test(ks[i])) return true;
    return false;
  } catch (e) { return false; }
}

/* Một lượt → Một chuỗi fingerprint ngắn; trong PEEKS không có lượt này thì trả về '' (không có dữ liệu không phán đoán). */
function shapeSig(rec) {
  try {
    if (typeof PEEKS === 'undefined' || !PEEKS || !rec || rec.rid == null) return '';
    var pk = PEEKS[rec.rid];
    if (!pk || typeof pk !== 'object') return '';
    var u = shapeUsage(pk);
    var ks = u ? shapeKeys(u) : [];
    var f = '';
    try { f = String(pk.finish == null ? '' : pk.finish).replace(/\|/g, '/'); }
    catch (eF) { f = ''; }
    return (u ? 'u1' : 'u0') + '|' +
      ks.slice(0, 6).join(',') + '|' +
      (u && shapeThinks(u) ? 't1' : 't0') + '|' +
      (pk.modelVersion ? 'v1' : 'v0') + '|' + f;
  } catch (e) { return ''; }
}

function shapeRowOk(r) {
  try {
    return !!r && typeof r === 'object' && typeof r.sig === 'string' && r.sig !== '';
  } catch (e) { return false; }
}

/* Baseline chỉ đại diện cho "trước đây": Lượt này nếu đã vào kho, khi phán đoán hãy bóc chính mục ở đuôi ra;
   đồng thời bỏ đi các mẫu đã hết hạn. */
function shapeHist(arr, sig) {
  try {
    var out = [];
    var now = Date.now();
    for (var i = 0; i < arr.length; i++) {
      var r = arr[i];
      if (!shapeRowOk(r)) continue;
      var at = Number(r.at);
      if (isFinite(at) && at > 0 && now - at > SHAPE_EXPIRE) continue;
      out.push(r);
    }
    if (out.length && sig) {
      var last = out[out.length - 1];
      if (String(last.sig) === String(sig)) out.pop();
    }
    return out;
  } catch (e) { return []; }
}

/* Ghi lại một mục. Các lượt bị tráo / không suy nghĩ không vào kho, nếu không baseline sẽ học theo hình dạng bên giả mạo;
   không lấy được response body (sig === '') cũng không ghi. */
function shapePush(rec) {
  try {
    if (!rec || !shapeOn()) return null;
    if (rec.internal) return null;
    if (rec.code === 'diff' || rec.code === 'thin' || rec.code === 'skip') return null;
    var sig = shapeSig(rec);
    if (!sig) return null;
    var k = shapeId(rec);
    if (!k) return null;
    var all = shapeRead();
    /* Tiện tay dọn sạch các key cũ trong toàn kho, tránh việc thử qua bao nhiêu proxy là để lại bấy nhiêu */
    var now = Date.now();
    for (var kk in all) {
      if (!Object.prototype.hasOwnProperty.call(all, kk)) continue;
      var vv = all[kk];
      if (!Array.isArray(vv) || !vv.length) { delete all[kk]; continue; }
      var lastAt = Number(vv[vv.length - 1] && vv[vv.length - 1].at);
      if (isFinite(lastAt) && lastAt > 0 && now - lastAt > SHAPE_EXPIRE) delete all[kk];
    }
    var arr = Array.isArray(all[k]) ? all[k] : [];
    arr.push({ sig: sig, at: now });
    if (arr.length > SHAPE_MAX) arr = arr.slice(arr.length - SHAPE_MAX);
    all[k] = arr;
    shapeWrite(all);
    return { sig: sig, at: now };
  } catch (e) { return null; }
}

/* Chuỗi xuất hiện nhiều lần nhất trong lịch sử, bằng phiếu nhau thì lấy loại gần hơn (khi duyệt dùng >=). */
function shapeRef(hist) {
  try {
    var counts = {};
    var order = [];
    for (var i = 0; i < hist.length; i++) {
      var s = String(hist[i].sig);
      if (!Object.prototype.hasOwnProperty.call(counts, s)) { counts[s] = 0; order.push(s); }
      counts[s]++;
    }
    var best = '';
    var bestN = -1;
    for (var j = 0; j < order.length; j++) {
      if (counts[order[j]] >= bestN) { bestN = counts[order[j]]; best = order[j]; }
    }
    return { sig: best, n: bestN };
  } catch (e) { return { sig: '', n: 0 }; }
}

function shapeStable(hist) {
  try {
    if (!hist.length) return false;
    var s = String(hist[0].sig);
    for (var i = 1; i < hist.length; i++) {
      if (String(hist[i].sig) !== s) return false;
    }
    return true;
  } catch (e) { return false; }
}

/* Đoạn nào khác nhau → Một câu dễ hiểu. Đừng ném nguyên cả chuỗi fingerprint cho người dùng. */
function shapeSegDesc(pos, cur, ref) {
  try {
    if (pos === 2) return ref === 't1' ? 'thiếu trường suy nghĩ' : 'thừa trường suy nghĩ';
    if (pos === 0) return ref === 'u1' ? 'thiếu usage' : 'thừa usage';
    if (pos === 3) return ref === 'v1' ? 'thiếu modelVersion' : 'thừa modelVersion';
    if (pos === 4) return 'giá trị finish khác biệt';
    if (pos === 1) {
      if (ref && cur) return 'trường usage không giống';
      return ref ? 'usage thiếu trường' : 'usage thừa trường';
    }
    return 'trường trả về không giống';
  } catch (e) { return 'trường trả về không giống'; }
}

/* Khi nhiều đoạn khác nhau chỉ báo đoạn có lượng thông tin lớn nhất: Trường suy nghĩ → Có/không usage → modelVersion
   → finish → Tập hợp key của usage. */
function shapeDiff(cur, ref) {
  try {
    var a = String(ref || '').split('|');
    var b = String(cur || '').split('|');
    if (a.length !== 5 || b.length !== 5) return 'tổ hợp trường khác với trước đây';
    var order = [2, 0, 3, 4, 1];
    for (var i = 0; i < order.length; i++) {
      var p = order[i];
      if (a[p] !== b[p]) return shapeSegDesc(p, b[p], a[p]);
    }
    return 'tổ hợp trường khác với trước đây';
  } catch (e) { return 'tổ hợp trường khác với trước đây'; }
}

/* Phán đoán một lượt. Mẫu không đủ trả về null; khớp trúng trả về { why, line }. */
function shapeJudge(rec) {
  try {
    if (!rec || !shapeOn()) return null;
    /* Phán đoán và lưu kho dùng cùng một ngưỡng: Request nội bộ vừa không nhận, vừa không dùng nó đưa ra kết luận */
    if (rec.internal) return null;
    var sig = shapeSig(rec);
    if (!sig) return null;
    var hist = shapeHist(shapeOf(shapeId(rec)), sig);
    if (hist.length < SHAPE_MIN_N) return null;
    for (var i = 0; i < hist.length; i++) {
      if (String(hist[i].sig) === sig) return null;
    }
    var d = shapeDiff(sig, shapeRef(hist).sig);
    var line;
    if (shapeStable(hist)) {
      line = 'Định dạng trả về trong ' + hist.length + ' lượt qua của kênh này hoàn toàn giống nhau, lượt này đã đổi (' + d + ')';
    } else {
      line = 'Định dạng trả về của lượt này không giống bất kỳ lượt nào trong ' + hist.length + ' lượt qua của kênh này (' + d + '), ' +
        'có thể đã đổi model, cũng có thể do kênh đã sửa interface';
    }
    return { why: 'shape', line: line };
  } catch (e) { return null; }
}

/* Chỉ xuất một dòng chữ này, card và banner dùng chung, tránh hai nơi viết lại hai lần */
function shapeLine(rec) {
  try {
    var sj = shapeJudge(rec);
    return (sj && sj.line) ? String(sj.line) : '';
  } catch (e) { return ''; }
}

/* ===== 18_upd.js ===== */
/* ============================================================================
 * Anti-Route v8 — 18/Upd Kiểm tra phiên bản mới
 *
 * Mục đích: Đây là một đoạn script được import trong "Tavern Helper", không phải extension trình duyệt,
 * bản thân không có khả năng tự cài đặt / thay thế — không thể tự sửa mình, cũng không thể tải về tự ghi đè.
 * Cho nên ở đây chỉ có thể làm duy nhất một việc: Định kỳ truy vấn một file phiên bản "hiện tại mới nhất là bản mấy",
 * khi phát hiện mới hơn VERSION, để lại một câu gợi ý trên banner và panel + một địa chỉ, phần còn lại do người dùng tự tải về import.
 *
 * Thiết luật:
 *   - Tuyệt đối không tải script, tuyệt đối không eval nội dung từ xa, tuyệt đối không upload bất cứ thứ gì.
 *   - Chỉ gửi GET; chỉ nhận http:// và https://, các giao thức khác nhất loạt từ chối.
 *   - Mặc định tắt (cfg.upd === 'off'). Người dùng tự mở mới kiểm tra, khi đang tắt thì đến một request
 *     cũng không gửi (force chỉ cấp cho entrypoint "kiểm tra thủ công", xem chú thích của updCheck).
 *   - Không tra cứu được không phải là sự cố: Timeout, 404, file viết sai, mất mạng, toàn bộ đều im lặng, không làm phiền người dùng.
 *
 * Lưu trữ: ar6.upd = { at: timestamp mili giây, latest: '1.2.3', url: '...' }
 * ========================================================================== */

var UPD_KEY = 'ar6.upd';
var UPD_TTL = 8000;   /* 8 giây. File phiên bản chỉ là một văn bản nhỏ vài chục byte, vượt quá là mạng có vấn đề */
var UPD_URL_MAX = 500;

/* Địa chỉ tích hợp sẵn: Người dùng không cần điền gì cả, bấm một cái là kiểm tra được, cài được.
   Bản Desktop và bản TT trỏ tới file phiên bản riêng của mỗi bên, phân biệt dựa vào UI_MODE được inject khi đóng gói. */
var UPD_URL_D = 'https://github.com/3577241779/luke-light/releases/latest/download/version.json';
var UPD_URL_D_M = 'https://github.com/3577241779/luke-light/releases/latest/download/version-mobile.json';

function updDefUrl() {
  try {
    if (typeof UI_MODE !== 'undefined' && String(UI_MODE) === 'mobile') return UPD_URL_D_M;
  } catch (e0) {}
  return UPD_URL_D;
}

/* Ai đang dùng địa chỉ này: Điền rồi thì dùng cái đã điền, chưa điền thì dùng cái tích hợp sẵn. Để trống = Đi theo tích hợp sẵn. */
function updUrl() {
  var u = '';
  try { u = String((cfg && cfg.updUrl) || '').trim(); } catch (e1) { u = ''; }
  return updUrlOk(u) ? u : updDefUrl();
}

/* Địa chỉ tích hợp sẵn không hiển thị thành "đã điền", để người dùng biết đây là mặc định xuất xưởng */
function updUrlIsDefault() {
  var u = '';
  try { u = String((cfg && cfg.updUrl) || '').trim(); } catch (e2) { u = ''; }
  return !updUrlOk(u);
}

/* Số phiên bản chỉ nhận "số + dấu chấm", phía trước có thể kèm một chữ v. Có hậu tố dạng -beta nhất loạt không nhận:
   So sánh phiên bản là so theo từng đoạn số, không nhận ra mà vẫn cố so sẽ đưa ra kết luận sai về việc "ai mới hơn". */
var UPD_VER_RE = /^\d+\.\d+(?:\.\d+)?$/;
var UPD_LINE_RE = /^v?(\d+\.\d+(?:\.\d+)?)$/;

function updOn() {
  try { return !!cfg && String(cfg.upd == null ? '' : cfg.upd) === 'check'; }
  catch (e) { return false; }
}

/* Chỉ cho qua http/https: File phiên bản là văn bản tĩnh bình thường, không có lý do dùng giao thức khác;
   giới hạn độ dài là để phòng ngừa trượt tay dán cả bài tài liệu vào (500 đã vượt xa URL bình thường). */
function updUrlOk(u) {
  try {
    var s = String(u == null ? '' : u).trim();
    if (!s || s.length >= UPD_URL_MAX) return false;
    if (s.indexOf('http://') !== 0 && s.indexOf('https://') !== 0) return false;
    return true;
  } catch (e) { return false; }
}

/* File phiên bản cho phép hai cách viết:
 *   JSON: {"version":"1.2.3"} / {"tag":"v1.2.3"} (tag_name của GitHub release cũng nhận)
 *   Plain text: Cả file chỉ có một dòng 1.2.3 hoặc v1.2.3
 * Bỏ tiền tố v thống nhất rồi mới trả về: So sánh và hiển thị đều dựa vào số thuần, hai cách viết ở nơi khác sẽ đụng độ nhau. */
function updParse(text) {
  try {
    var s = String(text == null ? '' : text);
    try {
      var o = JSON.parse(s);
      if (o && typeof o === 'object' && !Array.isArray(o)) {
        var names = ['version', 'tag', 'tag_name'];
        for (var i = 0; i < names.length; i++) {
          var raw = o[names[i]];
          if (raw == null) continue;
          var v = String(raw).trim().replace(/^v/i, '');
          if (UPD_VER_RE.test(v)) return v;
        }
      }
    } catch (eJ) { /* Không phải JSON thì chạy xuống dưới quét theo dòng */ }
    var lines = s.split(/\r?\n/);
    for (var j = 0; j < lines.length; j++) {
      var m = UPD_LINE_RE.exec(String(lines[j]).trim());
      if (m) return m[1];
    }
    return '';
  } catch (e) { return ''; }
}

/* So sánh số phân đoạn theo dấu chấm, thiếu vị trí bù 0 (1.2 == 1.2.0).
   Bất kỳ mục nào bất hợp lệ trả về 0 — trả về 0 biểu thị "không rõ ràng", bên gọi dựa vào đó sẽ không đưa ra kết luận "có bản mới". */
function updCmp(a, b) {
  try {
    var sa = String(a == null ? '' : a).trim();
    var sb = String(b == null ? '' : b).trim();
    if (!UPD_VER_RE.test(sa) || !UPD_VER_RE.test(sb)) return 0;
    var pa = sa.split('.');
    var pb = sb.split('.');
    var n = pa.length > pb.length ? pa.length : pb.length;
    for (var i = 0; i < n; i++) {
      var x = i < pa.length ? parseInt(pa[i], 10) : 0;
      var y = i < pb.length ? parseInt(pb[i], 10) : 0;
      if (!isFinite(x) || !isFinite(y)) return 0;
      if (x > y) return 1;
      if (x < y) return -1;
    }
    return 0;
  } catch (e) { return 0; }
}

function updState() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(UPD_KEY) || '{}');
    if (!o || typeof o !== 'object' || Array.isArray(o)) return {};
    return o;
  } catch (e) { return {}; }
}

function updSave(o) {
  try { HOST.localStorage.setItem(UPD_KEY, JSON.stringify(o)); } catch (e) {}
}

/* Chỉ kiểm tra, không cài đặt. force chỉ dành cho việc "người dùng bấm kiểm tra thủ công": Đóng van vẫn cho phép kiểm tra một lần,
   nhưng luồng tự động (updBoot) bắt buộc phải tuân theo updOn(). */
function updCheck(force) {
  return new Promise(function (resolve) {
    var timer = null;
    var done = false;

    /* Điểm chốt: Chỉ resolve một lần, đồng thời đảm bảo timer 8 giây chắc chắn bị xóa,
       nếu không một lần kiểm tra thành công sẽ để lại trên trang một timer trống 8 giây sau mới kêu. */
    function fin(o) {
      if (done) return;
      done = true;
      if (timer !== null) {
        try {
          if (typeof HOST.clearTimeout === 'function') HOST.clearTimeout(timer);
          else if (typeof clearTimeout === 'function') clearTimeout(timer);
        } catch (eC) {}
        timer = null;
      }
      resolve(o);
    }

    try {
      if (!updOn() && !force) { fin({ ok: false, err: 'off' }); return; }

      var u = updUrl();
      if (!updUrlOk(u)) { fin({ ok: false, err: 'nourl' }); return; }
      if (!HOST || typeof HOST.fetch !== 'function') { fin({ ok: false, err: 'net' }); return; }

      var opts = {
        method: 'GET',
        cache: 'no-store',
        headers: { 'Accept': 'text/plain, application/json' }
      };

      /* Host không có AbortController thì không gượng ép tạo: Timer đến giờ trực tiếp phán đoán timeout,
         cả hai hướng đều không để một request bị kẹt làm treo panel. */
      var ctl = null;
      try {
        if (typeof HOST.AbortController === 'function') ctl = new HOST.AbortController();
      } catch (eA) { ctl = null; }
      if (ctl) {
        try { opts.signal = ctl.signal; } catch (eS) {}
      }
      try {
        var setT = (typeof HOST.setTimeout === 'function') ? HOST.setTimeout
          : (typeof setTimeout === 'function' ? setTimeout : null);
        if (setT) {
          timer = setT.call(HOST, function () {
            try {
              if (ctl) ctl.abort();
              else fin({ ok: false, err: 'net' });
            } catch (eB) {}
          }, UPD_TTL);
        }
      } catch (eT) { timer = null; }

      Promise.resolve(HOST.fetch(u, opts)).then(function (res) {
        /* res.ok === false mới tính là thất bại: Một số host trả về object không có trường ok,
           dùng !res.ok sẽ phán đoán nhầm response bình thường thành thất bại. */
        if (!res || res.ok === false) {
          fin({ ok: false, err: 'http', status: res ? res.status : 0 });
          return null;
        }
        return Promise.resolve(res.text()).then(function (text) {
          var full = updParseFull(text);
          var v = full && full.v;
          if (!v) { fin({ ok: false, err: 'parse' }); return; }
          updSave({ at: Date.now(), latest: v, url: u, pkgUrl: (full && full.url) || '' });
          fin({ ok: true, latest: v, pkgUrl: (full && full.url) || '', newer: updCmp(v, VERSION) > 0 });
        });
      }).then(null, function () {
        /* Mất mạng, bị abort, bị chặn CORS... đối với người dùng đều là một việc: Lần này không kiểm tra được */
        fin({ ok: false, err: 'net' });
      });
    } catch (e) { fin({ ok: false, err: 'net' }); }
  });
}

/* Có bản mới mới lên tiếng. Văn bản chỉ nói "có phiên bản mới", không được hứa hẹn "đã cập nhật giúp bạn" —
   script này không có năng lực đó. */
function updLine() {
  try {
    var st = updState();
    var v = (st.latest == null) ? '' : String(st.latest).trim();
    if (!v) return '';
    if (!UPD_VER_RE.test(v)) return '';
    if (updCmp(v, VERSION) <= 0) return '';
    return 'Có phiên bản mới v' + v + ' (hiện tại v' + VERSION + ')';
  } catch (e) { return ''; }
}

/* Kiểm tra một lần khi khởi động. Đóng van, chưa điền địa chỉ, truy vấn thất bại, không có bản mới: Nhất loạt giữ im lặng;
   chỉ khi "thực sự có bản mới" mới chiếm một dòng banner, tránh việc mỗi lần mở SillyTavern đều bật lên một câu vô dụng. */
function updBoot() {
  try {
    if (!updOn()) return;
    if (!updUrlOk(updUrl())) return;
    updCheck().then(function (r) {
      try {
        if (r && r.ok && r.newer) {
          banner('⬆ ' + updLine() + '　Có thể tải về tại "URL file phiên bản" trong panel', 'warn');
        }
      } catch (e2) {}
    }).then(null, function () {});
  } catch (e) {}
}

/* ==========================================================================
 * Cập nhật một chạm (v0.94)
 *
 * Bản trước chỉ có thể "nói cho bạn biết có bản mới hay không". Bản này tiến thêm một bước: Lấy gói mới về,
 * trực tiếp ghi vào bảng script của Tavern Helper, rồi để bạn refresh lại một cái.
 *
 * Tại sao ghi được: Script chạy trong iframe do Tavern Helper tạo bằng srcdoc, cùng origin, không có sandbox,
 * cho nên window.parent chính là trang SillyTavern; bảng script nằm ở extension_settings.tavern_helper.scripts,
 * tìm ra mục của chính mình, thay thế content, lưu lại lần nữa là xong.
 *
 * Ba tầng bảo hiểm:
 *   1. Chỉ nhận mục "thực sự là chính chúng ta" (tên / dòng phiên bản), không tìm thấy thà không cài đặt;
 *   2. Gói mới bắt buộc phải phân giải thành công trước, bắt buộc phải có dòng VERSION, nếu không một byte cũng không ghi;
 *   3. Nội dung cũ lưu lại trong bộ nhớ, cài xong cung cấp nút "Hoàn tác", trước khi refresh có thể lùi lại bất cứ lúc nào.
 * ========================================================================== */

var UPD_PKG_MAX = 4 * 1024 * 1024;  /* 4MB: Hiện tại toàn bộ gói ~440KB, để dư dả nhưng không vô hạn */
var UPD_BAK = null;                  /* { idx, content } —— Chỉ nằm trong bộ nhớ, refresh sẽ mất hiệu lực */
var UPD_SELF_NAME_RE = /卢克之光|Ánh Sáng Luke|Anti-?Route/i;

/* Từ iframe tìm ngược lên extension_settings của trang SillyTavern. Không tìm thấy thì trả về null:
   Thà để "Cập nhật một chạm" không khả dụng, chứ không đoán mò đường dẫn rồi đi ghi vào cấu hình của người khác. */
function updHostCtx() {
  try {
    var w = HOST;
    for (var d = 0; d < 4 && w; d++) {
      try {
        if (w.extension_settings && typeof w.extension_settings === 'object') {
          return {
            settings: w.extension_settings,
            save: (typeof w.saveSettingsDebounced === 'function') ? w.saveSettingsDebounced : null,
            loc: w.location || null
          };
        }
      } catch (eI) {}
      try { w = w.parent; } catch (eP) { w = null; }
    }
    return null;
  } catch (e) { return null; }
}

/* Nhận diện chính mình trong bảng script: Ưu tiên tên, kế đến dòng phiên bản. Cả hai đều không khớp nhất loạt không coi là chính mình. */
function updSelfIndex(list) {
  try {
    if (!list || !list.length) return -1;
    for (var i = 0; i < list.length; i++) {
      var it = list[i];
      if (!it || typeof it.content !== 'string') continue;
      var nm = String(it.name || '');
      if (UPD_SELF_NAME_RE.test(nm) && it.content.indexOf('var VERSION') >= 0) return i;
    }
    for (var j = 0; j < list.length; j++) {
      var c = list[j] && list[j].content;
      if (typeof c !== 'string') continue;
      if (c.indexOf('var VERSION') >= 0 && c.indexOf('AR6') >= 0) return j;
    }
    return -1;
  } catch (e) { return -1; }
}

/* Trong file phiên bản có thể mang một url, trỏ tới bản thân gói mới. Không có url thì thoái lui thành "chỉ gợi ý". */
function updParseFull(text) {
  var out = { v: '', url: '' };
  try {
    var s = String(text == null ? '' : text);
    try {
      var o = JSON.parse(s);
      if (o && typeof o === 'object' && !Array.isArray(o)) {
        var names = ['version', 'tag', 'tag_name'];
        for (var i = 0; i < names.length; i++) {
          var raw = o[names[i]];
          if (raw == null) continue;
          var v = String(raw).trim().replace(/^v/i, '');
          if (UPD_VER_RE.test(v)) { out.v = v; break; }
        }
        var u = o.url || o.download || o.file;
        if (u && updUrlOk(u)) out.url = String(u).trim();
        if (out.v) return out;
      }
    } catch (eJ) {}
    out.v = updParse(s);
    return out;
  } catch (e) { return out; }
}

/* Lấy gói mới về và cài vào. Trả về { ok, err, version } */
function updInstall() {
  return new Promise(function (resolve) {
    function fin(o) { try { resolve(o); } catch (e) {} }
    try {
      var st = updState();
      var pkgUrl = String((st && st.pkgUrl) || '').trim();
      var want = String((st && st.latest) || '').trim();
      if (!updUrlOk(pkgUrl)) { fin({ ok: false, err: 'nopkg' }); return; }

      var ctx = updHostCtx();
      if (!ctx) { fin({ ok: false, err: 'nohost' }); return; }
      var th = ctx.settings && ctx.settings.tavern_helper;
      var list = th && th.scripts;
      var idx = updSelfIndex(list);
      if (idx < 0) { fin({ ok: false, err: 'noself' }); return; }

      Promise.resolve(HOST.fetch(pkgUrl, { method: 'GET', cache: 'no-store' })).then(function (res) {
        if (!res || res.ok === false) { fin({ ok: false, err: 'http', status: res ? res.status : 0 }); return null; }
        return Promise.resolve(res.text()).then(function (text) {
          if (!text || text.length > UPD_PKG_MAX) { fin({ ok: false, err: 'big' }); return; }
          var pkg = null;
          try { pkg = JSON.parse(text); } catch (eP) { pkg = null; }
          var body = pkg && typeof pkg.content === 'string' ? pkg.content : '';
          if (!body || body.indexOf('var VERSION') < 0) { fin({ ok: false, err: 'badpkg' }); return; }

          var got = '';
          try { got = (body.match(/var VERSION\s*=\s*'([^']+)'/) || [])[1] || ''; } catch (eG) {}
          if (want && got && UPD_VER_RE.test(got) && updCmp(got, want) !== 0) {
            fin({ ok: false, err: 'mismatch', got: got, want: want });
            return;
          }

          UPD_BAK = { idx: idx, content: list[idx].content };
          list[idx].content = body;
          if (pkg.name && typeof pkg.name === 'string') list[idx].name = pkg.name;
          try { if (ctx.save) ctx.save(); } catch (eS) {}
          fin({ ok: true, version: got || want });
        });
      }).then(null, function () { fin({ ok: false, err: 'net' }); });
    } catch (e) { fin({ ok: false, err: 'net' }); }
  });
}

/* Một chạm: Kiểm tra + Cài đặt. Người dùng chỉ cần bấm một lần, không cần điền địa chỉ trước, cũng không cần bật công tắc trước.
   Trả về { ok, newer, installed, version|latest, err }. */
function updQuick() {
  return updCheck(true).then(function (r) {
    if (!r || !r.ok) return { ok: false, err: (r && r.err) || 'net', status: (r && r.status) || 0 };
    if (!r.newer) return { ok: true, newer: false, latest: r.latest || '' };
    if (!updUrlOk(String((r && r.pkgUrl) || ''))) return { ok: false, err: 'nopkg', latest: r.latest || '' };
    return updInstall().then(function (i) {
      if (i && i.ok) return { ok: true, newer: true, installed: true, version: i.version || r.latest || '' };
      return { ok: false, err: (i && i.err) || 'net', latest: r.latest || '' };
    });
  }).then(null, function () { return { ok: false, err: 'net' }; });
}

/* Hoàn tác: Đặt lại bản vừa thay ra (chỉ có hiệu lực trong phiên này) */
function updUndo() {
  try {
    if (!UPD_BAK) return { ok: false, err: 'nobak' };
    var ctx = updHostCtx();
    var list = ctx && ctx.settings && ctx.settings.tavern_helper && ctx.settings.tavern_helper.scripts;
    if (!list || !list[UPD_BAK.idx]) return { ok: false, err: 'nohost' };
    list[UPD_BAK.idx].content = UPD_BAK.content;
    try { if (ctx.save) ctx.save(); } catch (eS) {}
    UPD_BAK = null;
    return { ok: true };
  } catch (e) { return { ok: false, err: 'net' }; }
}

function updCanUndo() {
  try { return !!UPD_BAK; } catch (e) { return false; }
}

function updLatest() {
  try {
    var st = updState();
    return String((st && st.latest) || '').trim();
  } catch (e) { return ''; }
}

/* Nút "Cài bản mới" có xuất hiện hay không chỉ nhìn vào ba điều: Có URL gói, số phiên bản hợp lệ, thực sự mới hơn hiện tại */
function updHasPkg() {
  try {
    var st = updState();
    if (!st || !updUrlOk(st.pkgUrl)) return false;
    var v = String(st.latest || '').trim();
    if (!v || !UPD_VER_RE.test(v)) return false;
    return updCmp(v, VERSION) > 0;
  } catch (e) { return false; }
}

/* Khi có lỗi cũng phải nói tiếng người: Mã lỗi là để chúng ta xem, bảng thông báo là để người dùng xem */
function updErrText(code, r) {
  var m = {
    off: 'Tự động cập nhật chưa bật',
    nourl: 'Chưa điền URL file phiên bản',
    net: 'Mạng không thông suốt, hoặc chờ quá lâu bị timeout',
