/* ===== 3_net.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 3/4 Net
 * Hook request / Bộ quan sát host zero-lock / Bộ phán đoán / Hai đầu dò
 * Mấu chốt: HTTP 200 không chạm vào res.body, không gọi tee() và clone()
 * ========================================================================== */

var origFetch = null;
var hooked = false;
var booted = false;
var lastReq = null;
var inflight = 0;

function nowMs() { return Date.now(); }

function urlOf(input) {
  try {
    if (typeof input === 'string') return input;
    if (input && typeof input.url === 'string') return input.url;
  } catch (e) {}
  return '';
}

function isGenerateUrl(u) {
  return /\/chat-completions\/generate\b/.test(String(u || ''));
}

/* ---------------- Bằng chứng và phán đoán ---------------- */

/* Dòng Gemini đã offline: Các tên loại này chỉ có thể là "nhãn request" hoặc gateway echo, không thể dùng làm bằng chứng danh tính */
/* Chỉ khớp các tên cũ "thực sự ngừng hoạt động / không khả dụng" (thời kỳ 1.0 / 1.5 + pro-vision + snapshot -001/-002 thời kỳ đầu).
   2.0 / 2.5 hiện tại là model phục vụ chính tuyến, không thể xử lý như đã ngừng — việc đó sẽ khiến việc hạ bậc "chỉ có nhãn chat" bị phán đoán thành unknown. */
var RETIRED_MODEL_RE = /gemini[\s._-]?(?:1\.0|1\.5)[\s._-]?(?:pro|flash|ultra)|gemini-pro-vision|(?:pro|flash)-00[12]/i;

var PEEK_SEQ = 0;
var PEEKS = {};

/* Request nội bộ: Request sinh nội dung do các plugin như database/điền bảng phát động bằng cờ riêng, không tạo ra sản phẩm chat */
var INTERNAL_FETCH_KEY = (typeof Symbol === 'function' && Symbol.for) ? Symbol.for('acu.internal-generation-fetch') : null;

function isInternalRequest(init, bodyObj) {
  try {
    if (init && INTERNAL_FETCH_KEY && init[INTERNAL_FETCH_KEY] === true) return true;
  } catch (e0) {}
  try {
    var msgs = bodyObj && bodyObj.messages;
    if (!Array.isArray(msgs) || !msgs.length) return false;
    /* v8.29: Request sinh văn bản bình thường của SillyTavern chắc chắn mang type (normal/swipe/quiet…); body do plugin tự ghép thì không có */
    if (bodyObj.type) return false;
    if (msgs.length > 2) return false;
    for (var i = 0; i < msgs.length; i++) {
      if (String((msgs[i] && msgs[i].role) || '') === 'assistant') return false;
    }
    /* Chỉ nhìn số lượng mục sẽ dễ phán đoán nhầm "lượt đầu system+user" thành request nội bộ, như thế sẽ vĩnh viễn không đọc được chính văn.
       Bắt buộc phải có thêm bằng chứng chứng minh nó đi qua kênh riêng: custom channel + địa chỉ reverse proxy. */
    if (String(bodyObj.chat_completion_source || '') !== 'custom') return false;
    if (!bodyObj.reverse_proxy) return false;
    return true;
  } catch (e1) { return false; }
}

function pushObs(ev, val, src) {
  try {
    var v = String(val == null ? "" : val).trim();
    if (!v || ev.observed.indexOf(v) >= 0) return;
    ev.observed.push(v);
    if (!ev.observedSrc) ev.observedSrc = [];
    ev.observedSrc.push(src || "?");
  } catch (e) { }
}

function newEvidence(model, status, transport) {
  return {
    requestedModel: model, observed: [], observedSrc: [], status: status, transport: transport,
    verifiable: 'unknown',
    sawText: false, hasThink: false, hasReasonField: false,
    outputChars: 0, thoughtTok: 0, firstMs: 0, totalMs: 0, error: ''
  };
}

/* v0.13: Phạm vi kiểm tra. 'in' trong phạm vi / 'out' ngoài phạm vi / 'anon' không đọc được tên model */
function scopeLabel() {
  var n = 0, a = String(cfg.scopeList || '').split(',');
  for (var i = 0; i < a.length; i++) { if (String(a[i] || '').trim()) n++; }
  if (cfg.scope === 'only') return 'Chỉ kiểm tra ' + n + ' mục';
  if (cfg.scope === 'skip') return 'Bỏ qua ' + n + ' mục';
  return 'Tất cả';
}

function scopeMatch(model) {
  var mode = String(cfg.scope || 'all');
  if (mode !== 'only' && mode !== 'skip') return 'in';
  var list = String(cfg.scopeList || '').split(',');
  var keys = [];
  for (var i = 0; i < list.length; i++) {
    var k = String(list[i] || '').trim().toLowerCase();
    if (k) keys.push(k);
  }
  if (!keys.length) return 'in';          /* Danh sách trống thì đừng âm thầm bỏ sót mọi thứ */
  var m = String(model || '').trim().toLowerCase();
  if (!m) return 'anon';                  /* Không đọc được tên model: Không giả định nó nằm trong phạm vi, cũng không giả định là nằm ngoài */
  var hit = false;
  for (var j = 0; j < keys.length; j++) { if (m.indexOf(keys[j]) >= 0) { hit = true; break; } }
  if (mode === 'only') return hit ? 'in' : 'out';
  return hit ? 'out' : 'in';
}

var VERDICT = {
  same:    { label: 'Khớp', color: 'ok' },
  diff:    { label: 'Bị tráo', color: 'bad' },
  thin:    { label: 'Không suy nghĩ', color: 'warn' },
  unknown: { label: 'Không rõ', color: 'gray' },
  quota:   { label: 'Hạn ngạch', color: 'warn' },
  blocked: { label: 'Chặn', color: 'bad' },
  gate:    { label: 'Gateway bất thường', color: 'bad' },
  empty:   { label: 'Không có chính văn', color: 'gray' },
  echo:    { label: 'Echo', color: 'gray' },
  error:   { label: 'Thất bại', color: 'bad' },
  skip:    { label: 'Bỏ qua', color: 'gray' }
};

/* Kênh "đọc được suy nghĩ" — chỉ xem các bản ghi gần đây, cùng gia tộc.
   Bản cũ đọc 30 mục đầu, không có cửa sổ thời gian: Bất kỳ mục lịch sử think=1 nào cũng sẽ khiến toàn bộ các lượt không suy nghĩ phía sau bị phán đoán thành thin. */
function channelSeesThinking(model) {
  try {
    var log = readLog() || [];
    var fam = model ? familyOf(model) : '';
    var now = nowMs();
    for (var i = 0; i < log.length && i < 40; i++) {
      var r = log[i];
      if (!r || !r.think) continue;
      if (!r.at || now - Number(r.at) > 600000) continue;
      if (fam && r.req && familyOf(r.req) && familyOf(r.req) !== fam) continue;
      return true;
    }
  } catch (e) {}
  return false;
}

function verdictOf(ev) {
  if (ev.error) return { code: 'error', note: ev.error, conf: 'C' };
  if (ev.status === 429) return { code: 'quota', note: 'HTTP 429', conf: 'C' };
  if (ev.status >= 500) return { code: 'gate', note: 'HTTP ' + ev.status, conf: 'C' };
  if (ev.blocked) return { code: 'blocked', note: ev.blocked, conf: 'C' };
  if (!ev.sawText && ev.status >= 400) return { code: 'error', note: 'HTTP ' + ev.status, conf: 'C' };
  /* v8.29: Request nội bộ (database/điền bảng) vốn dĩ không tạo ra sản phẩm chat ⇒ Không đọc được chính văn không đồng nghĩa với phản hồi rỗng */
  if (!ev.sawText && ev.internal) {
    return { code: 'unknown', note: 'Request nội bộ (database hoặc điền bảng): Không có sản phẩm chat, không phán đoán phản hồi rỗng', conf: 'C' };
  }
  if (!ev.sawText) {
    if (ev.emptyConfirmed) return { code: 'empty', note: 'Response body và chat đều không có chính văn (xác nhận phản hồi rỗng)', conf: 'C' };
    return { code: 'empty', note: 'Không đọc được chính văn (response body chưa lấy được, lấy mẫu đường vòng có thể đã tắt)', conf: 'C' };
  }

  /* v0.13: Đến đây mới xem xét phạm vi — Phản hồi rỗng / lỗi / chặn thuộc về "mất câu trả lời", không liên quan tới model nào, phán đoán trước;
     "Có bị tráo hay không" mới liên quan tới model, model không nằm trong phạm vi thì chỉ để lại một bản ghi màu xám */
  var sc = scopeMatch(ev.requestedModel);
  if (sc === 'out') {
    return { code: 'skip', note: 'Không nằm trong phạm vi kiểm tra (' + scopeLabel() + ')', conf: 'C' };
  }
  /* v0.94 Chỉ kiểm tra Gemini: Request ngoài phạm vi không phán đoán, chỉ để lại một dòng ghi màu xám (phản hồi rỗng/lỗi đã phán đoán ở trên) */
  try {
    if (!inScopeModel(ev.requestedModel)) {
      return { code: 'skip', note: 'Không nằm trong phạm vi kiểm tra (chỉ kiểm tra Gemini)', conf: 'C' };
    }
  } catch (eSC) {}

  var req = ev.requestedModel;
  var ver = ev.verifiable || 'unknown';          /* yes=khả kiểm no=echo unknown=chưa kiểm */
  var obs = [], srcs = [];
  for (var i0 = 0; i0 < ev.observed.length; i0++) {
    var x0 = String(ev.observed[i0] || '').trim();
    if (!x0 || /^(?:auto|router|default|unknown|any)$/i.test(x0)) continue;
    var s0 = (ev.observedSrc && ev.observedSrc[i0]) || '?';
    if (s0 === 'msg' && RETIRED_MODEL_RE.test(x0)) continue;   /* Nhãn cũ không tính là bằng chứng */
    obs.push(x0); srcs.push(s0);
  }

  /* Thứ tự ưu tiên bằng chứng: Response body > Bản ghi chat (nhãn); cùng nguồn tính theo thứ tự đến */
  var order = [], orderSrc = [];
  for (var s1 = 0; s1 < srcs.length; s1++) {
    if (srcs[s1] === 'body') { order.push(obs[s1]); orderSrc.push('body'); }
  }
  for (var s2 = 0; s2 < srcs.length; s2++) {
    if (srcs[s2] !== 'body') { order.push(obs[s2]); orderSrc.push(srcs[s2]); }
  }

  for (var i = 0; i < order.length; i++) {
    var a = normModel(req), b = normModel(order[i]);
    if (!a || !b) continue;
    var fromBody = orderSrc[i] === 'body';
    var same = (a === b);
    /* Tên khác nhau nhưng cùng danh tính: Kênh thường tự thêm đuôi dạng -ai / -vertex / -low,
       đó là alias định tuyến và mức suy nghĩ, không phải là đổi sang model khác. */
    var aliasOnly = false;
    if (!same) {
      var ia = normModelIdentity(a), ib = normModelIdentity(b);
      if (ia && ia === ib) { same = true; aliasOnly = true; }
    }
    var fa = familyOf(a), fb = familyOf(b);

    /* Kênh không đọc model: Nhãn trên bản ghi chat không đáng tin cậy; nhưng tự khai báo trong response body vẫn có hiệu lực */
    if (ver === 'no' && !fromBody) {
      if (same) continue;
      continue;
    }

    var baseConf = fromBody ? ((ver === 'yes') ? 'A' : 'B') : (ver === 'yes' ? 'B' : 'C');

    if (same) {
      if (!ev.internal && isProLike(a) && !ev.hasThink && channelSeesThinking(a)) {
        /* conf bắt buộc phải cùng cấp với same: Cùng một bằng chứng "tên model khớp", không thể khi phán đoán thin lại nâng lên thành B */
        return { code: 'thin', note: 'Model khớp, nhưng lượt này không thấy suy nghĩ', conf: baseConf, obs: order[i] };
      }
      return { code: 'same', note: shortName(order[i]) + (fromBody ? ' (Response body)' : '') + (aliasOnly ? ' (Cùng một model, chỉ khác hậu tố tên)' : ''), conf: baseConf, obs: order[i] };
    }

    /* Khác nhà sản xuất: Bảng phân cấp không thể so sánh, trực tiếp tính là bị tráo; đồng thời echo chỉ phản hồi lại tên request ⇒ Khác biệt gia tộc tự nhiên loại trừ echo */
    if (fa && fb && fa !== fb) {
      return {
        code: 'diff',
        note: 'Khác gia tộc: ' + shortName(a) + ' (' + fa + ') → ' + shortName(b) + ' (' + fb + ')',
        conf: fromBody ? 'A' : baseConf, obs: order[i]
      };
    }

    var ta = tierOf(a), tb = tierOf(b);
    var ga = genOf(a), gb = genOf(b);
    var genMoved = ga > 0 && gb > 0 && Math.abs(ga - gb) >= 0.05;
    var tierDrop = ta > 0 && tb > 0 && tb < ta;
    var tierUp = ta > 0 && tb > 0 && tb > ta;

    /* Hạ bậc là quan trọng nhất: Nói rõ "hạ mấy bậc", tiện thể kèm theo thế hệ — dạng 3.8 Flash → 3.1 Flash phải nhìn ra được */
    if (tierDrop) {
      /* Thế hệ mới hơn nhưng bậc thấp hơn (dạng 1.5 Pro → 3.8 Flash): Hai bên nói riêng rẽ, không gượng ép phán "hạ bậc" */
      var mixed = genMoved && gb > ga;
      return {
        code: 'diff',
        note: shortName(order[i]) + ' (' +
          (mixed
            ? 'Thế hệ ' + ga + ' → ' + gb + ' (mới hơn), nhưng bậc T' + ta + ' → T' + tb + ' (thấp hơn)'
            : (genMoved ? 'Thế hệ ' + ga + ' → ' + gb + ', ' : '') + 'Bậc T' + ta + ' → T' + tb + ', hạ bậc') +
          ')',
        conf: baseConf, obs: order[i]
      };
    }
    /* Bậc không hạ, thế hệ bị hạ: Vẫn tính là bị tráo, chỉ là lời giải thích tập trung vào thế hệ */
    if (genMoved && gb < ga) {
      return {
        code: 'diff',
        note: shortName(order[i]) + ' (Thế hệ ' + ga + ' → ' + gb + ', hạ thế hệ' +
          (tierUp ? ', nhưng bậc T' + ta + ' → T' + tb + ' cao hơn' : '') + ')',
        conf: baseConf, obs: order[i]
      };
    }
    /* Đổi thành model mới hơn: Không phải hạ cấp, nhưng cũng không phải cái bạn yêu cầu */
    if (genMoved && gb > ga) {
      return {
        code: 'diff',
        note: shortName(order[i]) + ' (Thế hệ ' + ga + ' → ' + gb + ', đổi sang model mới hơn)',
        conf: baseConf, obs: order[i]
      };
    }
    if (tierUp) {
      return {
        code: 'diff',
        note: shortName(order[i]) + ' (Bậc T' + ta + ' → T' + tb + ', đổi sang cấu hình cao hơn)',
        conf: baseConf, obs: order[i]
      };
    }
    /* Response body khai báo một model khác: Cho dù cùng bậc, cũng là bị tráo.
       Nhưng tên này do kênh tự viết, không phải thẻ căn cước của thượng nguồn — khi chưa lấy được modelVersion cần nói rõ. */
    if (fromBody) {
      return {
        code: 'diff',
        note: 'Response body tự khai báo ' + shortName(b) + ' ≠ Request ' + shortName(a) +
          (ev.modelVersion ? '' : ' (Kênh không gửi lại số phiên bản, danh tính thực sự không rõ)'),
        conf: baseConf, obs: order[i]
      };
    }
    return { code: 'echo', note: 'Model khác nhau nhưng không thể định bậc: ' + shortName(order[i]), conf: 'C', obs: order[i] };
  }
  return {
    code: 'unknown',
    note: ev.internal ? 'Request nội bộ (database/điền bảng): Không có sản phẩm chat, response body cũng không gửi lại model' :
      (ver === 'no' ? 'Kênh không thể kiểm chứng, không có bằng chứng danh tính' : 'Thượng nguồn không gửi lại định danh model'),
    conf: 'C'
  };
}

function finish(ev, meta) {
  /* Khi lịch sử chat chưa submit (hoặc submit chậm), đừng vội nói "không có chính văn":
     Trong response body rõ ràng có văn bản thì cứ chờ nó đáp xuống, rồi lấy nó làm cứu cánh dự phòng. */
  /* v0.12: Request nội bộ không lấy body, cũng sẽ không có PEEKS để chờ — trước đây chỗ này sẽ quay không tải 6 giây mới lưu bản ghi */
  if (!ev.sawText && ev.status === 200 && ev.rid && !ev.internal) {
    var pk0 = PEEKS[ev.rid];
    if (!ev.__peekAt) ev.__peekAt = nowMs();
    var waited = nowMs() - ev.__peekAt;
    /* Chờ suốt cho nó đáp xuống: Kết thúc luồng stream và đọc xong peek không đồng bộ, đơn lượt 900ms thường không đủ */
    if ((!pk0 || !pk0.done) && waited < 6000) {
      ev.__peekDefer = (ev.__peekDefer || 0) + 1;
      setTimeout(function () { try { finish(ev, meta); } catch (eD) {} }, 700);
      return null;
    }
    if (pk0 && pk0.hasText) {
      ev.sawText = true;
      ev.bodyText = true;
      if (!ev.outputChars || ev.outputChars < pk0.textChars) ev.outputChars = pk0.textChars;
    } else if (pk0 && pk0.done) {
      /* Response body cũng đọc xong rồi, thực sự không có chữ: Đây mới là phản hồi rỗng thật */
      ev.emptyConfirmed = true;
    }
  }
  /* v0.94 Phạm vi kiểm tra: Mặc định chỉ kiểm tra Gemini. Các gia tộc khác vẫn gửi bình thường, nhận bình thường,
     không phán đoán (trong verdictOf trực tiếp trả về skip), không xây dựng baseline, nhưng Phá giáp / Chống cắt cụt / Chống OOC không bị ảnh hưởng. */
  var v = verdictOf(ev);
  /* v0.6 Chống cắt cụt: Phán đoán trước "lượt này tại sao dừng", kết quả phán đoán đi cùng bản ghi (khi tắt mức thì không thèm nhìn) */
  var tRes = null;
  try { if (cfg && cfg.trunc && cfg.trunc !== 'off') tRes = truncInspect(ev); } catch (eTR) {}
  if (v && ev.bodyText && !ev.chatSaw) {
    ev.bodyOnly = true;
    v.note = (v.note ? v.note + '; ' : '') + 'Chính văn đến từ response body (chat chưa submit)';
  }
  var rec = {
    at: nowMs(),
    req: shortName(ev.requestedModel),
    obs: shortName(v.obs || (ev.observed.length ? ev.observed[0] : '—')),
    src: (function () {
      try {
        if (v.obs) { var k = ev.observed.indexOf(v.obs); return k >= 0 ? (ev.observedSrc[k] || '') : ''; }
      } catch (eSrc) {}
      return (ev.observedSrc && ev.observedSrc[0]) || '';
    })(),
    retired: !!(ev.observed.length && RETIRED_MODEL_RE.test(String(ev.observed[0]))),
    code: v.code,
    conf: v.conf || 'C',
    verifiable: ev.verifiable || 'unknown',
    alias: cfg.alias || '',
    verdict: (VERDICT[v.code] || VERDICT.unknown).label,
    note: v.note,
    status: ev.status,
    ttft: ev.firstMs,
    total: ev.totalMs,
    chars: ev.outputChars,
    think: ev.hasThink ? 1 : ((ev.hasReasonField || ev.usageSeen) ? 0 : null),
    changed: (meta && meta.changed) || [],
    edits: (meta && meta.edits) || 0,
    added: (meta && meta.added) || 0,
    rid: ev.rid || 0,
    internal: !!ev.internal,
    bodyText: !!ev.bodyText,
    audit: (meta && meta.audit) || null,
    foreign: (meta && meta.foreign) || 0,
    base: (meta && meta.base) || '',
    errModel: ev.errModel || '',
    tooLong: !!ev.tooLong
  };
  /* v0.6 Chống cắt cụt: Chỉ khi thực sự nhận diện được cắt cụt mới thêm hai trường, hình dạng bản ghi của lượt bình thường không đổi */
  if (tRes && tRes.code) { rec.trunc = tRes.code; rec.truncNote = tRes.note; }
  /* Kênh echo: Tên không khớp không thể làm bằng chứng cho việc "bị tráo", hạ xuống thành "echo" */
  if (rec.code === 'diff' && rec.verifiable === 'no') {
    rec.code = 'echo';
    rec.verdict = 'Echo';
    rec.note = 'Kênh này sẽ echo lại tên model của bạn, tên không khớp không thể dùng làm bằng chứng';
  }
  try { ledAdd(rec); } catch (eLed) {}
  pushLog(rec);
  /* v0.82 Baseline hành vi: Sau khi bản ghi vào kho thì bổ sung một mẫu (đóng van / request nội bộ / quá ít chữ tự động bỏ qua) */
  try { basePush(rec); } catch (eBase) {}
  /* v0.84 Fingerprint cấu trúc: Chỉ ghi lại cấu trúc response body, các lượt bị tráo / không suy nghĩ tự động bỏ qua */
  try { shapePush(rec); } catch (eShape) {}
  render();
  var kind = (VERDICT[v.code] || VERDICT.unknown).color;
  if (v.code === 'diff' || v.code === 'blocked' || v.code === 'gate') {
    banner('🔴 ' + rec.verdict + ': ' + v.note + ' (Yêu cầu ' + rec.req + ')', kind);
  } else if (v.code === 'thin') {
    banner('🟠 ' + rec.verdict + ': ' + v.note + ' (Yêu cầu ' + rec.req + ')', kind);
  } else if (v.code === 'empty') {
    banner('⚪ ' + rec.verdict + ': ' + v.note + ' (Yêu cầu ' + rec.req + ')', kind);
  } else if (v.code === 'same') {
    /* v0.82 Baseline hành vi: Tên thì khớp, cảm giác tay không đúng — loại này là loại cần được nhìn thấy nhất, đừng để nó chỉ nằm im trong card */
    var bSame = '';
    try { var bjS = baseJudge(rec); if (bjS && bjS.why !== 'slow') bSame = bjS.line; } catch (eBS) {}
    /* v0.84 Fingerprint cấu trúc: Khi cả tên và cảm giác tay đều qua, định dạng thay đổi cũng phải để lại một câu */
    var sShape = '';
    try { sShape = shapeLine(rec); } catch (eShape2) {}
    banner('🟢 Khớp: ' + v.note + ' (' + (rec.ttft ? (rec.ttft / 1000).toFixed(1) + 's TTFT, ' : '') + rec.chars + ' chữ)' + (bSame ? '　⚠ ' + bSame : '') + (sShape ? '　🔬 ' + sShape : ''), kind);
  } else {
    banner('⚪ ' + rec.verdict + ': ' + v.note, kind);
  }
  /* v7.1 Phá giáp: Khắc phục hậu kỳ gắn ở đây — mỗi lần kết thúc sinh văn bản đều chắc chắn đi qua điểm này */
  /* v0.6 Chống cắt cụt: Trước Phá giáp phán đoán quy thuộc cắt cụt trước — mức nhẹ chỉ gợi ý, mức vừa bù một lần (giá trị trả về quyết định Phá giáp có quản nữa hay không) */
  var tCode = '';
  try { tCode = truncAfterFinish(ev, tRes) || ''; } catch (eTrunc) {}
  /* Chống cắt cụt đã nhận phần cắt cụt, Phá giáp đừng can thiệp thêm nữa; phản hồi rỗng/từ chối vẫn thuộc về Phá giáp */
  if (tCode) { try { ev.__truncCode = tCode; } catch (eTC) {} }
  try { jailAfterFinish(ev); } catch (eJail) {}
  /* v7.3: Phán đoán là "bị tráo / không suy nghĩ" tự động bật card bằng chứng (sau 1.6s, chờ lấy mẫu response body đáp xuống) */
  try {
    if (cfg.cardAuto && (v.code === 'diff' || v.code === 'thin')) {
      setTimeout(function () {
        try {
          /* v8.0.3: Hộp xác nhận Phá giáp / Card đã mở được ưu tiên, đừng chèn mất thứ người dùng đang thao tác trên tay */
          if (CARD && CARD.open) return;
          if (typeof jailAskPending === 'function' && jailAskPending()) return;
          openCard(rec);
        } catch (eC) {}
      }, 1600);
    }
  } catch (eCard) {}
  return rec;
}

/* ---------------- Phân tích error body (chỉ clone khi >=400) ---------------- */

/* Error body chỉ phân tích "thượng nguồn đã nói gì", tuyệt đối không đụng vào sawText.
   v8.29 đã return bỏ toàn bộ hàm, kéo theo việc đóng chết blocked — cái phanh "bị chặn không bù" của Phá giáp biến thành đồ giả.
   Hiện tại tách thành hai việc: model chỉ giữ lại để hiển thị (không pushObs, 4xx không phán đoán bị tráo), blocked / quá dài mới là dữ liệu đầu vào cho phán đoán. */
function salvageError(text, ev) {
  if (typeof text !== 'string' || !text) return;
  var mre = /"(?:modelVersion|model)"\s*:\s*"([^"]{1,120})"/g;
  var m;
  while ((m = mre.exec(text)) !== null) {
    if (!ev.errModel) ev.errModel = String(m[1]).trim();
  }
  if (/131072|maximum context length|context_length_exceeded|reduce the length/i.test(text)) ev.tooLong = true;
  if (/PROHIBITED_CONTENT|BLOCKLIST|SAFETY|SPII|RECITATION/.test(text)) {
    var bm = /(PROHIBITED_CONTENT|BLOCKLIST|SAFETY|SPII|RECITATION)/.exec(text);
    ev.blocked = bm ? bm[1] : 'BLOCKED';
  }
  /* v0.12: Câu này là điểm khởi đầu cho chuỗi tự kích của 8.29, xóa vĩnh viễn — mô tả lỗi không phải chính văn */
}

function readErrorBody(res, ev) {
  try {
    if (typeof res.clone !== 'function') return;
    res.clone().text().then(function (t) {
      salvageError(t, ev);
      if (!ev.errModel) ev.errModel = '';
      ev.sawText = ev.sawText || false;
      if (!ev.error) ev.error = '';
      finish(ev, null);
    }).catch(function () { finish(ev, null); });
  } catch (e) { finish(ev, null); }
}


/* ---------------- Lấy mẫu đường vòng response body (chỉ phục vụ Evidence Card, không làm nghẽn luồng chính) ---------------- */

/* Quét các trường thực sự mang chính văn như "text"/"content" trong response body để ước tính lượng ký tự.
   Không dùng Regex: Ký tự thoát (escape) quá dễ viết sai, vả lại ở đây chỉ cần một giá trị xấp xỉ + có hay không. */
function bodyTextChars(s) {
  var total = 0;
  var i = 0;
  var n = s.length;
  while (i < n && total < 200000) {
    var k1 = s.indexOf('"text"', i);
    var k2 = s.indexOf('"content"', i);
    var at, klen;
    if (k1 < 0 && k2 < 0) break;
    if (k1 < 0) { at = k2; klen = 9; }
    else if (k2 < 0) { at = k1; klen = 6; }
    else if (k1 < k2) { at = k1; klen = 6; }
    else { at = k2; klen = 9; }
    var q = s.indexOf('"', at + klen);
    if (q < 0) break;
    var j = q + 1;
    var cnt = 0;
    var closed = false;
    while (j < n) {
      var c = s.charAt(j);
      if (c === '\\') { cnt++; j += 2; continue; }
      if (c === '"') { closed = true; break; }
      cnt++;
      j++;
    }
    if (closed) total += cnt;
    i = j + 1;
  }
  return total;
}

function absorbPeek(text, rid, ev) {
  try {
    var s = String(text || '');
    if (!s) return;
    /* Phần đầu chứa chính văn, phần đuôi chứa usage: Chỉ cắt phần đầu sẽ làm mất trọn đoạn thống kê token ở frame cuối cùng */
    if (s.length > 420000) s = s.slice(0, 300000) + '\n' + s.slice(-120000);
    var hasUsage = /"(?:thoughtsTokenCount|reasoning_tokens|candidatesTokenCount|promptTokenCount)"/.test(s);
    var pick = function (re) { var m = re.exec(s); return m ? m[1] : ''; };
    var mv = pick(/"(?:modelVersion)"\s*:\s*"([^"]{1,80})"/);
    var md = pick(/"model"\s*:\s*"([^"]{1,80})"/);
    var tt = pick(/"thoughtsTokenCount"\s*:\s*(\d+)/);
    var rt = pick(/"reasoning_tokens"\s*:\s*(\d+)/);
    var ct = pick(/"candidatesTokenCount"\s*:\s*(\d+)/);
    var pt = pick(/"promptTokenCount"\s*:\s*(\d+)/);
    var fin = pick(/"finishReason"\s*:\s*"([A-Z_]+)"/) || pick(/"finish_reason"\s*:\s*"([a-z_]+)"/);
    var hit = mv || md;
    var at = hit ? s.indexOf(hit) : 0;
    var raw = hit ? s.slice(Math.max(0, at - 90), at + 240) : s.slice(0, 260);
    raw = raw.replace(/\s+/g, ' ').trim();
    /* Fingerprint cấu trúc: Trong đoạn response này rốt cuộc xuất hiện mấy trường thống kê token (nối bằng dấu phẩy sau khi sắp xếp).
       Bản thân tên key chính là fingerprint — cùng một kênh rất hiếm khi đổi cách đặt tên, đổi model / đổi triển khai mới thay đổi. */
    var UKEYS = ['candidatesTokenCount', 'completion_tokens', 'promptTokenCount',
      'prompt_tokens', 'reasoning_tokens', 'thoughtsTokenCount', 'totalTokenCount', 'total_tokens'];
    var ukeys = [];
    for (var ui = 0; ui < UKEYS.length; ui++) {
      if (s.indexOf('"' + UKEYS[ui] + '"') >= 0) ukeys.push(UKEYS[ui]);
    }
    /* Trong response body rốt cuộc có chính văn hay không — đây là một nguồn sự thật độc lập với bản ghi chat */
    var tlen = 0;
    try { tlen = bodyTextChars(s); } catch (eTL) { tlen = 0; }
    PEEKS[rid] = {
      at: nowMs(),
      textChars: tlen,
      hasText: tlen > 0,
      model: md,
      modelVersion: mv,
      thoughts: tt ? Number(tt) : null,
      reasoning: rt ? Number(rt) : null,
      out: ct ? Number(ct) : null,
      prompt: pt ? Number(pt) : null,
      finish: fin,
      raw: raw,
      usageKeys: ukeys.join(','),
      done: true
    };
    /* Model do response body tự khai báo là bằng chứng mạnh: Vừa ghi log, vừa đưa vào phán đoán */
    try {
      if (ev && mv) ev.modelVersion = String(mv);
      if (ev && hit) pushObs(ev, hit, 'body');
      /* Đã từng thấy usage thì tính là "thực sự đã đọc được": Sau đó thoughts==0 là bằng chứng, không còn là "chưa thấy" nữa */
      if (ev && hasUsage) {
        ev.usageSeen = true;
        ev.usageZeroThink = !(tt && Number(tt) > 0 || rt && Number(rt) > 0);
      }
      if (ev && !ev.internal && (tt && Number(tt) > 0 || rt && Number(rt) > 0)) {
        ev.hasThink = true;
        ev.hasReasonField = true;
        ev.thoughtTok = Number(tt || rt || 0);
      }
      if (ev && tlen > 0) { ev.bodyChars = tlen; }
      /* v0.6 Chống cắt cụt: Chép finish đã trích xuất sẵn vào event, phán đoán cần dùng đến nó (giá trị rỗng không ghi đè) */
      if (ev && fin) ev.finish = fin;
    } catch (eEv) {}
    if (typeof render === 'function' && CARD && CARD.open && CARD.rid === rid) {
      try {
        /* v8.0.3: Chỉ đổi dữ liệu, giữ nguyên tab người dùng đang xem và vị trí cuộn */
        var keepTab = CARD.tab || 'human';
        var keepTop = 0;
        try {
          var sc = DOC.getElementById('ar6-card');
          if (sc) { var inner = sc.querySelector('[data-ar6-cardbody]'); if (inner) keepTop = inner.scrollTop || 0; }
        } catch (eS) {}
        var lg = readLog(), target = null;
        for (var li = 0; li < lg.length; li++) { if (lg[li] && lg[li].rid === rid) { target = lg[li]; break; } }
        openCard(target || null, keepTab);
        try {
          var sc2 = DOC.getElementById('ar6-card');
          if (sc2) { var in2 = sc2.querySelector('[data-ar6-cardbody]'); if (in2) in2.scrollTop = keepTop; }
        } catch (eS2) {}
      } catch (e0) {}
    }
  } catch (e) {}
}

function peekBody(res, ev) {
  try {
    if (!cfg.peek || cfg.safe) return null;
    if (ev && ev.internal) return null;   /* Response body của request nội bộ không phải chính văn, không thu thập */
    if (!res || typeof res.clone !== 'function') return;
    var rid = ev && ev.rid;
    if (!rid) return;
    var cl = res.clone();
    if (!cl) return;
    if (cl.body && typeof cl.body.getReader === 'function') {
      var rd = cl.body.getReader();
      var dec = null;
      try { dec = HOST.TextDecoder ? new HOST.TextDecoder() : null; } catch (e1) { dec = null; }
      var buf = '';
      var tail = '';
      var total = 0;
      var done = false;
      var finishPeek = function () {
        if (done) return;
        done = true;
        /* usage / finish_reason đều nằm ở frame cuối cùng của SSE: Chỉ giữ phần đầu sẽ cắt mất trọn đoạn của nó */
        absorbPeek(tail ? (buf + '\n' + tail) : buf, rid, ev);
        /* Đọc được nội dung rỗng cũng phải để lại dấu vết: Nếu không sẽ không thể phân biệt giữa "thực sự không có chính văn" và "hoàn toàn không lấy được" */
        if (!PEEKS[rid]) PEEKS[rid] = { at: nowMs(), textChars: 0, hasText: false, done: true, raw: '' };
      };
      var step = function () {
        rd.read().then(function (r) {
          if (done) return;
          if (r.done) { finishPeek(); return; }
          total += r.value && r.value.length ? r.value.length : 0;
          var piece = '';
          try { piece = dec ? dec.decode(r.value, { stream: true }) : ''; } catch (e2) { piece = ''; }
          if (total <= 400000) buf += piece;
          else {
            tail += piece;
            if (tail.length > 60000) tail = tail.slice(-60000);
          }
          /* Dự phòng: Thực sự gặp response siêu lớn thì không đọc nữa, tránh làm tràn bộ nhớ */
          if (total > 8000000) { try { rd.cancel(); } catch (e3) {} finishPeek(); return; }
          step();
        })['catch'](function () { finishPeek(); });
      };
      step();
      return;
    }
    cl.text().then(function (t) {
      absorbPeek(t, rid, ev);
      if (!PEEKS[rid]) PEEKS[rid] = { at: nowMs(), textChars: 0, hasText: false, done: true, raw: '' };
    })['catch'](function () {});
  } catch (e) {}
}

/* ---------------- Bộ quan sát host zero-lock ---------------- */

function stCtx() {
  try {
    var st = HOST.SillyTavern;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e) {}
  return null;
}

function isBusy() {
  try {
    if (HOST.is_send_press || HOST.is_generating) return true;
    var body = DOC && DOC.body;
    if (body && body.classList && body.classList.contains('generating')) return true;
    var stop = DOC && DOC.getElementById && DOC.getElementById('mes_stop');
    if (stop && stop.style && stop.style.display !== 'none') return true;
  } catch (e) {}
  return false;
}

var WATCHERS = [];   /* Timer của các bộ quan sát đang chạy, khi dispose sẽ dọn sạch đồng loạt */

function stopWatchers() {
  try {
    for (var i2 = 0; i2 < WATCHERS.length; i2++) clearInterval(WATCHERS[i2]);
    WATCHERS.length = 0;
  } catch (e) {}
}

/* Kênh nhanh event cốt lõi: Có event thì lấy event làm chuẩn, không có thì fallback về polling */
var EV_TICK = { seq: 0, lastTokenAt: 0, lastEndAt: 0, bound: false };
function bindStreamEvents() {
  if (EV_TICK.bound) return true;
  try {
    var w = SELF_WIN || null;
    if (!w || typeof w.eventOn !== 'function') return false;
    try { w.eventOn('stream_token_received', function () { EV_TICK.lastTokenAt = nowMs(); }); } catch (e1) {}
    try { w.eventOn('generation_ended', function () { EV_TICK.lastEndAt = nowMs(); EV_TICK.seq++; }); } catch (e2) {}
    EV_TICK.bound = true;
    return true;
  } catch (e) { return false; }
}

function startWatcher(ev, meta, reqStart) {
  var ctx = stCtx();
  if (!ctx || !Array.isArray(ctx.chat)) {
    ev.sawText = true;
    finish(ev, meta);
    return;
  }
  var baseLen = ctx.chat.length;
  var baseMes = baseLen ? String(ctx.chat[baseLen - 1] && ctx.chat[baseLen - 1].mes || '') : '';
  var lastLen = 0;
  var lastChange = nowMs();
  var sawBusy = false;
  var polls = 0;
  var evSeq0 = EV_TICK.seq;
  var evEndAt = 0;
  var graceUntil = 0;
  bindStreamEvents();

  var timer = setInterval(function () {
    polls++;
    var t = nowMs();
    try {
      if (isBusy()) sawBusy = true;
      var c = ev.internal ? null : stCtx();
      var chat = c && Array.isArray(c.chat) ? c.chat : null;
      if (chat && chat.length) {
        var msg = chat[chat.length - 1];
        var isAi = msg && !msg.is_user;
        /* v8.29: /continue, swipe, regenerate không thêm tin nhắn mới, tin cuối cùng bị ghi đè tại chỗ cũng phải nhận diện.
           Điều kiện nhận diện = Chat dài ra, hoặc "tin cuối là AI + chính văn không rỗng + khác với lúc bắt đầu nhận diện". */
        var grew = chat.length > baseLen;
        var mesNow = String((msg && msg.mes) || '');
        var contOnly = !grew && isAi && mesNow.length > 0 && mesNow !== baseMes;
        if (isAi && (grew || contOnly)) {
          var mesStr = mesNow;
          var reason = '';
          try {
            var ex = msg.extra || {};
            reason = String(ex.reasoning || ex.thinking || '');
            /* Chỉ lấy nhãn trên các tin nhắn nằm trong cửa sổ sinh nội dung của lượt này; model trong chat cũ / bản ghi import là nhãn lịch sử */
            var freshMsg = true;
            try {
              var stamp = (ex.gen_finished) || msg.gen_finished || (ex.gen_started) || msg.send_date || '';
              var ts = Date.parse(stamp);
              /* Không phân giải được thì coi như "hết mới": Thà thiếu một nhãn còn hơn nhận nhầm tin nhắn của người khác */
              if (isNaN(ts) || ts + 8000 < reqStart) freshMsg = false;
            } catch (eS) { }
            if (freshMsg && ex.model && normModel(ex.model)) pushObs(ev, ex.model, 'msg');
            if (freshMsg && ex.api_model) pushObs(ev, ex.api_model, 'msg');
          } catch (e2) {}
          var joined = mesStr + (reason ? '\n' + reason : '');
          if (joined.length > 0 && !ev.firstMs) ev.firstMs = Math.max(1, t - reqStart);
          if (joined.length !== lastLen) { lastLen = joined.length; lastChange = t; }
          if (joined.length) {
            ev.sawText = true;
            ev.chatSaw = true;
            /* Khi chỉ viết tiếp (tin nhắn không tăng thêm), sản lượng lượt này = Chính văn hiện tại − Chính văn lúc nhận diện.
               Số âm là "viết lại thành ngắn hơn": Khi đó toàn bộ tin đều mới viết lại, không thể báo là 1 chữ;
               cũng không thể lấy 1 làm cứu cánh dự phòng — đó là bịa số, panel sẽ hiển thị "Chính văn 1 chữ". */
            var grewChars = mesStr.length - baseMes.length;
            ev.outputChars = contOnly ? (grewChars > 0 ? grewChars : mesStr.length) : joined.length;
            /* Phá giáp cần phán đoán "chính văn" và "phần kết", chuỗi tư duy không tính là chính văn */
            ev.mesChars = mesStr.length;
            ev.tail = mesStr.slice(-600);
            if (reason.trim() || /<(?:thinking|think|interleaving|SUOT)\b/i.test(mesStr)) {
              ev.hasThink = true;
              ev.hasReasonField = true;
              ev.thoughtTok = estimateTokens(reason);
            }
          }
        }
      }
      var ended = EV_TICK.seq > evSeq0;
      if (ended && !evEndAt) evEndAt = EV_TICK.lastEndAt || t;
      /* Có chính văn mới tính là có kết quả; event báo kết thúc cũng tính (lúc này chat thường đã được submit) */
      var progress = ev.internal ? (ev.sawText ? 1 : 0) : lastLen;
      var settled = progress > 0 && (!isBusy() || t - lastChange > 2200 || ended);
      var stopped = !ev.internal && sawBusy && !isBusy() && progress > 0 && t - reqStart > 1200 && t - lastChange > 900;
      var noCtx = !stCtx() && polls >= 3;
      var timeout = t - reqStart > 120000;
      var wants = settled || stopped || noCtx || timeout || (ended && t - reqStart > 600);
      if (wants && progress === 0 && !timeout) {
        /* Tái kiểm tra gia hạn: Trong giai đoạn stream, chat.mes có thể vẫn chưa submit, đừng vội phán đoán phản hồi rỗng */
        if (!graceUntil) graceUntil = t + 1500;
        if (t < graceUntil) return;
      }
      if (wants) {
        clearInterval(timer);
        ev.totalMs = Math.max(1, t - reqStart);
        finish(ev, meta);
      }
    } catch (e3) {
      clearInterval(timer);
      try { ev.totalMs = Math.max(1, nowMs() - reqStart); finish(ev, meta); } catch (e4) {}
    }
  }, 150);
  WATCHERS.push(timer);
}

/* ---------------- Xử lý request ---------------- */

function handleFetch(next, thisArg, args) {
  var input = args[0];
  var init = args[1];
  var url = urlOf(input);
  if (!isGenerateUrl(url)) return next.apply(thisArg, args);
  /* Phá giáp dùng bộ đếm này để phán đoán "yêu cầu viết tiếp rốt cuộc đã gửi đi hay chưa" */
  try { JL.seq++; } catch (eJ) {}
  if (input && typeof input === 'object' && typeof input.clone === 'function') {
    return next.apply(thisArg, args);
  }

  var rawBody = init && typeof init.body === 'string' ? init.body : '';
  var plan = null;
  var outArgs = args;
  var internal = false;
  try {
    var parsedForInternal = null;
    try { parsedForInternal = rawBody ? JSON.parse(rawBody) : null; } catch (ePI) {}
    internal = isInternalRequest(init, parsedForInternal);
  } catch (eInt) { internal = false; }
  try {
    plan = planRequest(rawBody, url, internal);
    if (cfg.enabled && plan.changed.length && plan.body !== rawBody) {
      var newInit = {};
      for (var k in init) newInit[k] = init[k];
      newInit.body = plan.body;
      outArgs = [input, newInit];
    }
    if (plan.model) lastReq = { url: url, raw: rawBody, model: plan.model, base: plan.base || '' };
  } catch (e) { plan = null; }

  var started = nowMs();
  inflight++;

  var p = next.apply(thisArg, outArgs);
  if (!p || typeof p.then !== 'function') { inflight--; return p; }

  return p.then(function (res) {
    inflight--;
    try {
      var ev = newEvidence(plan ? plan.model : '', res.status, 'sse');
      ev.internal = internal;
      try { ev.verifiable = verifiableCode(); } catch (eVer) { ev.verifiable = 'unknown'; }
      if (res.status === 204) { ev.sawText = true; finish(ev, plan); return res; }
      if (res.status >= 400) { readErrorBody(res, ev); return res; }
      ev.rid = ++PEEK_SEQ;
      var watching = false;
      if (cfg.observe && !cfg.safe) { startWatcher(ev, plan, started); watching = true; }
      var pk = peekBody(res, ev);
      /* v8.0.3: Khi bộ quan sát bị tắt thì 200 cũng phải lưu lại một bản ghi (chỉ tính bằng chứng response body), nếu không cả lượt không được ghi lại, Phá giáp mất liên lạc */
      if (!watching && pk && typeof pk.then === 'function') {
        pk.then(function () {
          try { if (!ev.__finished) { ev.__finished = true; finish(ev, plan); } } catch (eF) {}
        }, function () {
          try { if (!ev.__finished) { ev.__finished = true; finish(ev, plan); } } catch (eF) {}
        });
      } else if (!watching) {
        /* v0.12: Khi không có bộ quan sát và cũng không lấy body (request nội bộ hoặc đã tắt peek), lượt này sẽ không có ai kết thúc thu dọn.
           Thu dọn trực tiếp — nếu không request nội bộ sẽ không có cả bản ghi, sổ cái và log đều không thấy nó. */
        try { if (!ev.__finished) { ev.__finished = true; finish(ev, plan); } } catch (eF2) {}
      }
      return res;
    } catch (e2) {
      try { HOST.console && HOST.console.warn('[AR6] post-response error', e2 && e2.message); } catch (eW) {}
      return res;
    }
  }, function (err) {
    inflight--;
    try {
      var ev2 = newEvidence(plan ? plan.model : '', 0, 'none');
      ev2.error = String(err && err.message || err || 'fetch failed').slice(0, 80);
      ev2.totalMs = Math.max(1, nowMs() - started);
      finish(ev2, plan);
    } catch (e3) {}
    throw err;
  });
}

/* ---------------- Cài đặt / Khôi phục hook ---------------- */

/* Từng lớp chúng ta đã cài đặt (khi dispose sẽ đồng loạt đặt thành pass-through mà không xóa wrapper của người khác) */
var ourWrappers = [];
/* Dành riêng cho đầu dò: Lớp fetch nguyên bản được bắt sớm nhất */
var probeFetch = null;
/* Lớp gắn lên lần cuối cùng + lớp tiếp theo mà nó tiếp quản lúc đó (chỉ dùng để khôi phục an toàn) */
var exposedFetch = null;
var exposedPrev = null;

function installFetchHook() {
  try {
    if (!HOST || typeof HOST.fetch !== 'function') return false;
    /* Tái sử dụng hook người khác đã cài đặt: Cũng tính là "đã gắn", nếu không banner sẽ báo sai "chưa gắn hook" */
    if (HOST.fetch.__ar6 && !HOST.fetch.__ar6dead) { exposedFetch = HOST.fetch; hooked = true; return true; }
    if (HOST.fetch === exposedFetch) { hooked = true; return true; }
    /* ★ Then chốt: prev là hằng số riêng tư của lần cài đặt này, bất kỳ lần cài lại nào sau đó cũng không ghi đè nó.
       Triển khai cũ đọc origFetch dùng chung, nếu extension khác cũng bọc một lớp fetch, sẽ tạo thành
       đệ quy vô hạn (tràn ngăn xếp) dạng W2 → wrapper khác → W1 → wrapper khác → W1… */
    var prev = HOST.fetch;
    var dead = false;
    if (!origFetch) origFetch = prev;
    if (!probeFetch) probeFetch = prev;
    var wrapped = function (input, init) {
      if (dead) return prev.apply(this, arguments);
      try { return handleFetch(prev, this, arguments); }
      catch (err) {
        try { HOST.console && HOST.console.warn('[AR6] hook error, fallback', err); } catch (e1) {}
        return prev.apply(this, arguments);
      }
    };
    wrapped.__ar6 = true;
    ourWrappers.push({ fn: wrapped, kill: function () { dead = true; wrapped.__ar6dead = true; } });
    exposedFetch = wrapped;
    exposedPrev = prev;
    HOST.fetch = wrapped;
    hooked = true;
    return true;
  } catch (e) { return false; }
}

function unhookFetch() {
  try {
    /* 1) Làm cho toàn bộ các lớp chúng ta từng cài đặt lập tức thoái lui thành pass-through thuần túy (không xóa chuỗi, tránh phá hỏng wrapper của người khác) */
    for (var i = 0; i < ourWrappers.length; i++) {
      try { ourWrappers[i].kill(); } catch (e0) {}
    }
    ourWrappers.length = 0;
    /* 2) Chỉ khôi phục khi chúng ta thực sự ở lớp ngoài cùng, tuyệt đối không ghi đè wrapper do người khác cài đặt sau đó */
    if (exposedFetch && HOST.fetch === exposedFetch && exposedPrev) HOST.fetch = exposedPrev;
    exposedFetch = null;
    exposedPrev = null;
    HOOK_TARGET.fetch = null;
    hooked = false;
  } catch (e) {}
}

var HOOK_TARGET = { fetch: null, xhr: null };

function ensureHooks() {
  /* Đã dispose: Không được vì pageshow/timer/chuỗi thử lại mà gắn hook trở lại */
  if (DISPOSED) return false;
  if (cfg.safe) { unhookFetch(); unhookXhr(); renderStatus(); return false; }
  var ok = installFetchHook();
  if (ok && HOST.fetch.__ar6) HOOK_TARGET.fetch = HOST.fetch;
  if (cfg.xhr) installXhrHook(); else unhookXhr();
  renderStatus();
  return ok;
}

var XHR_DEAD = false;   /* Sau khi gỡ bỏ phương thức prototype cũ chỉ pass-through, không sửa đổi request */

function installXhrHook() {
  try {
    XHR_DEAD = false;
    var X = HOST.XMLHttpRequest;
    if (!X || !X.prototype) return false;
    if (X.prototype.send && X.prototype.send.__ar6) return true;
    var origOpen = X.prototype.open;
    var origSend = X.prototype.send;
    var wrappedOpen = function (m, u) {
      if (XHR_DEAD) return origOpen.apply(this, arguments);
      try { this.__ar6url = String(u || ''); } catch (e) {}
      return origOpen.apply(this, arguments);
    };
    var wrappedSend = function (body) {
      if (XHR_DEAD) return origSend.call(this, body);
      try {
        var u = this.__ar6url || '';
        if (isGenerateUrl(u) && cfg.enabled && typeof body === 'string' && body.trim().charAt(0) === '{') {
          var plan = planRequest(body, u);
          if (plan.changed.length && plan.body !== body) { body = plan.body; }
          this.__ar6plan = plan;
        }
      } catch (e) {}
      return origSend.call(this, body);
    };
    wrappedOpen.__ar6 = true;
    wrappedSend.__ar6 = true;
    wrappedSend.__ar6orig = origSend;
    wrappedOpen.__ar6orig = origOpen;
    X.prototype.open = wrappedOpen;
    X.prototype.send = wrappedSend;
    HOOK_TARGET.xhr = { X: X, origOpen: origOpen, origSend: origSend };
    return true;
  } catch (e) { return false; }
}

function unhookXhr() {
  try {
    XHR_DEAD = true;
    var rec = HOOK_TARGET.xhr;
    if (!rec) return;
    if (rec.X.prototype.open.__ar6) rec.X.prototype.open = rec.origOpen;
    if (rec.X.prototype.send.__ar6) rec.X.prototype.send = rec.origSend;
    HOOK_TARGET.xhr = null;
  } catch (e) {}
}

/* ---------------- Đầu dò ---------------- */

function httpJson(url, opts, timeoutMs) {
  var f = probeFetch || origFetch || HOST.fetch;
  return new Promise(function (resolve, reject) {
    var done = false;
    var timer = setTimeout(function () {
      if (!done) { done = true; reject(new Error('timeout')); }
    }, timeoutMs || 20000);
    try {
      f(url, opts).then(function (res) {
        return res.text().then(function (t) {
          if (done) return;
          done = true; clearTimeout(timer);
          resolve({ status: res.status, text: t });
        });
      }).catch(function (e) {
        if (done) return;
        done = true; clearTimeout(timer);
        reject(e);
      });
    } catch (e) {
      if (!done) { done = true; clearTimeout(timer); reject(e); }
    }
  });
}

function stripApiSuffix(b) {
  return String(b || '').replace(/\/+$/, '')
    .replace(/\/(?:chat\/completions|completions|messages)$/, '')
    .replace(/\/v1beta\d*$/, '')
    .replace(/\/v1$/, '');
}

function openAIUrl(base) {
  var b = String(base || '').replace(/\/chat\/completions\/?$/, '').replace(/\/+$/, '');
  if (!b) return '';
  return b + '/chat/completions';
}

function nativeUrl(base, model) {
  var m = String(model || '').replace(/:streamGenerateContent$/, '').replace(/:generateContent$/, '');
  return stripApiSuffix(base) + '/v1beta/models/' + encodeURIComponent(m) + ':generateContent';
}

var probeBusy = false;

function runNativeProbe() {
  if (probeBusy) return;
  var base = cfg.dualBase || (lastReq && lastReq.base) || '';
  var key = cfg.dualKey || '';
  var model = (lastReq && lastReq.model) || '';
  if (!base || !model) { banner('⚪ Đầu dò cần gửi trước một lượt, hoặc điền Base trong panel', 'gray'); return; }
  probeBusy = true;
  banner('🔬 Đầu dò native đang request…', 'gray');
  var body = { contents: [{ role: 'user', parts: [{ text: 'ping' }] }], generationConfig: { maxOutputTokens: 8, temperature: 0 } };
  var headers = { 'content-type': 'application/json' };
  if (key) headers['x-goog-api-key'] = key;
  httpJson(nativeUrl(base, model), { method: 'POST', headers: headers, body: JSON.stringify(body) }, 25000)
    .then(function (r) {
      probeBusy = false;
      if (r.status >= 400 && /invalid|unsupported|400|422/.test(String(r.status))) {
        return httpJson(nativeUrl(base, model), { method: 'POST', headers: headers, body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: 'ping' }] }] }) }, 25000)
          .then(function (r2) { reportNative(r2, model); });
      }
      reportNative(r, model);
    })
    .catch(function (e) {
      probeBusy = false;
      banner('🔴 Đầu dò native thất bại: ' + String(e && e.message || e).slice(0, 60), 'bad');
    });
}

function reportNative(r, model) {
  var mv = '';
  try {
    var j = JSON.parse(r.text);
    mv = String((j.modelVersion || j.model || '') || '');
  } catch (e) {}
  var vt = mv ? tierOf(mv) : 0;
  var rt = tierOf(model);
  if (!mv) banner('⚪ Endpoint native trả về ' + r.status + ', không có modelVersion (reverse proxy này có thể không hỗ trợ /v1beta)', 'gray');
  else if (rt > 0 && vt > 0 && vt < rt) banner('🔴 Endpoint native xác nhận hạ bậc: Yêu cầu T' + rt + ' → Thực tế ' + mv, 'bad');
  else banner('🟢 Endpoint native trả về modelVersion=' + mv, 'ok');
  render();
}

function runDualProbe() {
  if (probeBusy) return;
  var base = openAIUrl(cfg.dualBase);
  var key = cfg.dualKey || '';
  var model = (lastReq && lastReq.model) || '';
  if (!base || !model) { banner('⚪ Fingerprint kênh đôi cần gửi trước một lượt, hoặc điền Base trong panel', 'gray'); return; }
  probeBusy = true;
  banner('🔬 Fingerprint kênh đôi đang request…', 'gray');
  var headers = { 'content-type': 'application/json' };
  if (key) headers['authorization'] = 'Bearer ' + key;
  var ghost = model + '-zzz-not-a-real-model';
  function ask(m) {
    return httpJson(base, {
      method: 'POST', headers: headers,
      body: JSON.stringify({ model: m, messages: [{ role: 'user', content: 'hi' }], max_tokens: 8, stream: false })
    }, 25000).then(function (r) { return r.status; }).catch(function () { return 0; });
  }
  Promise.all([ask(model), ask(ghost)]).then(function (codes) {
    probeBusy = false;
    var real = codes[0], g = codes[1];
    if (!real || real >= 400) banner('🔴 Request tên thật thất bại (HTTP ' + real + '), liên kết không khả dụng', 'bad');
    else if (!g) banner('⚪ Request tên ma không gửi đi được (lỗi mạng), không thể phán đoán', 'gray');
    else if (g === 200) banner('🟠 Chế độ nới lỏng: Tên ma cũng trả về 200 ⇒ Gateway không kiểm tra model, trường model gửi về không đáng tin cậy', 'warn');
    /* 401/403 là xác thực chưa qua, 402 là hết tiền, 429 là giới hạn tần suất, 5xx là thượng nguồn bị sập —
       các trường hợp này đều chưa đi tới bước "kiểm tra tên model", không thể coi là "phân phối theo tên". */
    else if (g >= 400 && g < 500 && g !== 401 && g !== 403 && g !== 402 && g !== 429) banner('🟢 Chế độ nghiêm ngặt: Tên ma bị từ chối (HTTP ' + g + ') ⇒ Gateway phân phối theo tên, trường model đáng tin cậy', 'ok');
    else banner('⚪ Tên ma trả về HTTP ' + g + ': Vừa không phải "từ chối tên model", vừa không phải 200, không thể phán đoán', 'gray');
    render();
  });
}

/* ===== 9_card.js ===== */
/* ============================================================================
 * Anti-Route v7.3-test — 9/9 Evidence Card (Dành cho người xem, chụp được màn hình, chuyển tiếp được)
 *
 * Mục đích: Biến cảm giác "tôi thấy model bị hạ thông minh" thành một chiếc card có thể trực tiếp chụp màn hình.
 * Trái: Thứ tôi yêu cầu là gì
 * Phải: Thượng nguồn nói nó đã trả về cái gì (nguyên văn response body)
 * Dưới: Bằng chứng hình thái của lượt này (token suy nghĩ / TTFT / số chữ / tốc độ)
 * Đáy: Đoạn response thô sơ chưa qua gia công — khiến người ta không thể cãi rằng "đây là do script tự bịa"
 *
 * Thiết luật: Chỉ đọc không ghi, tuyệt đối không làm nghẽn tiến trình sinh; toàn bộ DOM đều là inline style (không phụ thuộc vào CSS của trang).
 * ========================================================================== */

var CARD = { open: false, rid: 0 };

var CARD_COLOR = {
 diff: '#f85149',
 thin: '#d29922',
 echo: '#8b949e',
 unknown: '#8b949e',
 same: '#3fb950',
 quota: '#a371f7',
 blocked: '#f85149',
 gate: '#d29922',
 empty: '#8b949e',
 error: '#8b949e'
};

function cardColor(code) {
 return CARD_COLOR[code] || '#8b949e';
}

function cardRate(rec) {
 var n = Number(rec.total) || 0;
 var c = Number(rec.chars) || 0;
 if (!n || !c) return 0;
 return Math.round(c * 1000 / n);
}

/* Dùng ký tự khối vuông vẽ xu hướng: Không cần canvas, chụp màn hình vẫn rõ ràng */
function cardSpark(vals) {
 var chars = '▁▂▃▄▅▆▇█';
 var arr = (vals || []).filter(function (v) { return typeof v === 'number' && isFinite(v); });
 if (!arr.length) return '';
 var min = Math.min.apply(null, arr);
 var max = Math.max.apply(null, arr);
 var span = max - min;
 var out = '';
 for (var i = 0; i < arr.length; i++) {
 var idx = span <= 0 ? 4 : Math.round((arr[i] - min) / span * 7);
 if (idx < 0) idx = 0; if (idx > 7) idx = 7;
 out += chars.charAt(idx);
 }
 return out;
}

function cardPeek(rec) {
 try {
 if (!rec || rec.rid == null) return null;
 return PEEKS[rec.rid] || null;
 } catch (e) { return null; }
}

function cardOneLine(rec) {
 var pk = cardPeek(rec);
 var req = rec.req || '?';
 var obs = rec.obs && rec.obs !== '—' ? rec.obs : '';
 var tail = '';
 if (rec.code === 'diff') {
 tail = obs ? ('Yêu cầu ' + req + ' → Thượng nguồn trả về ' + obs) : ('Yêu cầu ' + req + ', nhưng bằng chứng không khớp với yêu cầu');
 } else if (rec.code === 'thin') {
 tail = 'Yêu cầu ' + req + ', chính văn ' + rec.chars + ' chữ, token suy nghĩ là 0';
 } else if (rec.code === 'echo') {
 tail = 'Yêu cầu ' + req + ', nhãn trả về khác với yêu cầu, nhưng kênh này không đọc model (Echo)';
 } else if (rec.code === 'same') {
 tail = 'Yêu cầu ' + req + ', kết quả trả về khớp';
 } else {
 tail = 'Yêu cầu ' + req + ', không thể phán đoán (' + (rec.verdict || '') + ')';
 }
 if (pk && pk.modelVersion) tail += '｜modelVersion: ' + pk.modelVersion;
 return tail;
}

function cardText(rec) {
 if (!rec) return '';
 var d = new Date(Number(rec.at) || Date.now());
 var pad = function (n) { return (n < 10 ? '0' : '') + n; };
 var ts = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' +
 pad(d.getHours()) + ':' + pad(d.getMinutes());
 var pk = cardPeek(rec);
 var lines = [];
 lines.push('[Bằng chứng Anti-Route] ' + ts);
 lines.push('Phán đoán: ' + (rec.verdict || '') + ' (Cấp bằng chứng ' + (rec.conf || 'C') + ')');
 lines.push(cardOneLine(rec));
 lines.push('Nguyên nhân: ' + (rec.note || ''));
 lines.push('Token suy nghĩ: ' + (pk && pk.thoughts != null ? pk.thoughts : (rec.think ? 'Quan sát thấy' : '0/Chưa quan sát thấy')) +
 ' ｜ TTFT: ' + (rec.ttft ? rec.ttft + 'ms' : '—') +
 ' ｜ Chính văn: ' + (rec.chars || 0) + ' chữ ｜ Tốc độ: ' + cardRate(rec) + ' chữ/giây');
 if (pk && (pk.model || pk.modelVersion)) {
