 }
 return '<div style="display:flex;gap:2px;align-items:flex-end">' + h + '</div>';
}

/* v0.5.1: Kích thước lớp nổi. Khối chứa fixed trong iframe phía mobile có thể bị host đè bẹp (chiều cao ≈ 0),
   khi đó inset:0 sẽ sụp xuống thành một đường thẳng, align-items:center đẩy card ra khỏi màn hình một nửa.
   Ở đây mở rộng tường minh theo đơn vị viewport (vw/vh không bị ảnh hưởng bởi khối chứa), phía desktop giữ nguyên inset:0 ban đầu. */
function cardOverlayCss() {
  var mob = false;
  try { mob = (typeof uiMode === 'function' && uiMode() === 'mobile'); } catch (e) {}
  if (!mob) return 'position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:12px;';
  return 'position:fixed;left:0;top:0;width:100vw;height:var(--TH-viewport-height,100vh);' +
    'display:flex;align-items:center;justify-content:center;padding:12px;overflow-y:auto;';
}

/* Chiều cao tối đa của content box: Phía mobile tính theo chiều cao khả dụng thực tế do host cung cấp, phía desktop giữ nguyên vh ban đầu */
function cardBoxMaxH(vhPct) {
