 if (c === 'thin') return { t: 'Model không đổi, nhưng nó không suy nghĩ', s: 'Câu trả lời vẫn còn đó, nhưng không có bất kỳ tiến trình suy nghĩ nào — thường thấy khi mức suy nghĩ bị đè xuống thấp nhất.', c: '#d29922' };
