 '<div style="font-size:11px;color:#8b949e;margin-top:3px">Chỉ thống kê bằng chứng thật: Khi tên model khớp nhưng kênh chỉ echo, mục đó chỉ tính là "Yếu".</div></div>';
 /* v0.82 Baseline hành vi: Một dòng chữ vàng nhỏ, chỉ nhắc nhở cảm giác tay, không động vào phán đoán phía trên */
 if (bl) {
 h += '<div style="margin:0 16px 10px;font-size:12px;color:#d29922;line-height:1.5">Baseline hành vi: ' + esc(bl) + '</div>';
 }
 /* v0.84 Fingerprint cấu trúc: Trúng khớp mới thêm một dòng, cũng chỉ mang tính nhắc nhở */
 if (sl) {
 h += '<div style="margin:0 16px 10px;font-size:12px;color:#d29922;line-height:1.5">Fingerprint cấu trúc: ' + esc(sl) + '</div>';
 }
 h += '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding:10px 16px 14px;border-top:1px solid #21262d">';
 h += '<button data-ar6-card="copy" style="min-height:42px;background:#238636;border:0;border-radius:10px;color:#fff;font-size:14px;font-weight:600">Sao chép văn bản</button>';
 h += '<button data-ar6-card="close" style="min-height:42px;background:#21262d;border:1px solid #30363d;border-radius:10px;color:#c9d1d9;font-size:14px">Đóng</button>';
 h += '</div>';
 h += '<div style="padding:0 16px 12px;font-size:10px;color:#484f58">' + esc(new Date(Number(rec.at) || Date.now()).toLocaleString()) + ' · Anti-Route v' + esc(VERSION || '') + ' · Kênh ' + esc(rec.base || '—') + '</div>';
 h += '</div></div>';
 return h;
}

function cardHTML(rec, tab) {
 var t = tab === 'human' ? 'human' : 'engine';
 if (t === 'human') return cardHumanHTML(rec);
 /* v8.0.3: Tab đã được lồng vào container của card, ở đây không ghép vào lớp ngoài cùng của overlay nữa */
 return cardEngineHTML(rec);
}

function closeCard() {
 CARD.open = false;
 try {
 var el = DOC.getElementById('ar6-card');
 if (el && el.parentNode) el.parentNode.removeChild(el);
 } catch (e) {}
 /* v8.0.3: mountHTML sẽ append cả các node anh em như <style> vào body, cùng dọn dẹp đồng loạt */
 try {
 var ex = DOC.querySelectorAll('[data-ar6-extra="1"]');
 for (var i = 0; i < ex.length; i++) { if (ex[i] && ex[i].parentNode) ex[i].parentNode.removeChild(ex[i]); }
 } catch (e2) {}
}

function mountHTML(html) {
 /* Tại cùng một thời điểm chỉ giữ một lớp nổi: Dọn lớp cũ trước, tránh bị xếp chồng lên nhau thành một đống */
 try { closeCard(); } catch (eOld) {}
 var frag = DOC.createElement('div');
 frag.innerHTML = html;
 var node = null;
 var guard = 0;
 while (guard++ < 40) {
 var c = frag.firstChild;
 if (!c) break;
 try { frag.removeChild(c); } catch (eR) {}
 if (c && c.id === 'ar6-card') node = c;
 else { try { c.setAttribute('data-ar6-extra', '1'); } catch (eX) {} }
 DOC.body.appendChild(c);
 }
 if (!node) { try { node = DOC.getElementById('ar6-card'); } catch (eG) {} }
 return node;
}

function openCard(rec, tab) {
 try {
 if (!rec) {
 var log = readLog();
 rec = log && log[0];
 if (!rec) { banner('Chưa có bản ghi nào, hãy chạy trước một lượt', 'gray'); return; }
 }
 closeCard();
 var node = mountHTML(cardHTML(rec, tab));
 if (!node) throw new Error('mount failed');
 CARD.open = true;
 CARD.rid = rec.rid || 0;
 node.addEventListener('click', function (ev) {
 var t = ev.target;
 var act = t && t.getAttribute && (t.getAttribute('data-ar6-card') || '');
 if (act === 'copy') { cardCopy(rec); return; }
 if (act === 'tab') { openCard(rec, t.getAttribute('data-tab')); return; }
 if (act === 'close' || t === node) closeCard();
 });
 } catch (e) {
 try { banner('Render Evidence Card thất bại: ' + String(e && e.message || e), 'bad'); } catch (e2) {}
 }
}

