 function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
 function over() { return tabs.scrollWidth - tabs.clientWidth; }

 /* Căn kích thước/vị trí của con trượt khớp với trạng thái hiện tại của thanh tab; khi các tab vừa đủ chỗ hoặc con trượt đã chiếm trọn không còn hành trình, ẩn toàn bộ thanh trượt */
 function sync() {
