  try {
    if (DISPOSED) return null;
    if (!DOC || !DOC.body) return null;
    var el = DOC.getElementById(ROOT_ID);
    if (!el) {
      el = DOC.createElement('div');
      el.id = ROOT_ID;
      DOC.body.appendChild(el);
    }
    return el;
  } catch (e) { return null; }
}

