/* Sub-chip: Công tắc tổng tắt, hoặc mục này đã nhường cho preset → chuyển xám.
   Chuyển xám chỉ là "trông như không thể bấm", việc chặn thực sự nằm ở oocToggle, đừng viết logic vào style. */
function oocChip(item) {
  var off = String(cfg.ooc || 'off') !== 'on';
  var grey = off || oocChoice(item) === 'preset';
  return chip(oocChipLabel(item), oocOnOf(item), grey ? 'data-off="1"' : '');
}

/* Bấm một sub-chip: Công tắc tổng tắt → chỉ nhắc nhở; đã nhường cho preset → thu hồi lại; nếu không thì bật/tắt + hỏi một lần khi cần */
function oocToggle(item) {
  var key = OOC_CFGKEY[item];
  if (!key) return;
  if (String(cfg.ooc || 'off') !== 'on') {
    banner('Mở công tắc tổng trước (🎭 Chống OOC)', 'gray');
    return;
  }
  if (oocChoice(item) === 'preset') {
    oocSetChoice(item, 'script');
    cfg[key] = true;
    try { saveCfg(); } catch (e0) {}
    render();
    banner((OOC_LABEL[item] || item) + ': Đổi lại dùng của chúng ta', 'ok');
    return;
  }
  var next = !oocOnOf(item);
  cfg[key] = next;
  try { saveCfg(); } catch (e1) {}
  render();
  banner((OOC_LABEL[item] || item) + ': ' + (next ? 'Bật' : 'Tắt'), next ? 'ok' : 'gray');
  if (!next) return;
  /* Vừa bật: Nếu preset cũng quản lý mục này, hỏi trước một câu xem dùng của bên nào */
  var ask = [], sig = null;
  try { ask = oocAsk(); } catch (e2) { ask = []; }
  if (ask.indexOf(item) < 0) return;
  try { sig = oocSig(); } catch (e3) { sig = null; }
  if (!sig || !sig.hits || !sig.hits[item]) return;
  var hits = {};
  hits[item] = sig.hits[item];
  oocConflictDialog(hits, function () { try { render(); } catch (e4) {} });
}

