/* Popup xung đột: Preset cũng quản lý các mục này, hỏi một lần xem dùng của bên nào. */
function oocConflictDialog(hits, cb) {
  if (!hits) { if (cb) cb(''); return; }
  var keys = [];
  for (var k in hits) {
    if (Object.prototype.hasOwnProperty.call(hits, k)) keys.push(k);
  }
  if (!keys.length) { if (cb) cb(''); return; }

  var h = '<style>#ar6-card,#ar6-card *{box-sizing:border-box;min-width:0}</style>';
  h += '<div id="ar6-card" style="' + cardOverlayCss() +
    'z-index:2147483600;background:rgba(1,4,9,.86);font-family:system-ui,-apple-system,\'Segoe UI\',sans-serif">';
  h += '<div style="width:402px;max-width:calc(100vw - 20px);max-height:' + cardBoxMaxH(92) +
    ';overflow-x:hidden;overflow:auto;background:#0d1117;color:#e6edf3;border:1px solid #30363d;' +
    'border-radius:16px;box-shadow:0 12px 48px rgba(0,0,0,.6);padding:16px 16px 13px">';

  h += '<div style="font-size:14px;font-weight:600;margin-bottom:4px">Preset cũng quản lý ' +
    (keys.length > 1 ? 'hai' : 'một') + ' mục này</div>';
  h += '<div style="font-size:11px;color:#8b949e;margin-bottom:10px">Cả hai nơi cùng can thiệp một nội dung sẽ dễ đá nhau — hãy chọn một bên</div>';

  for (var i = 0; i < keys.length; i++) {
    var kk = keys[i];
    h += '<div style="display:flex;gap:8px;align-items:baseline;padding:7px 0;' +
      'border-top:1px solid rgba(255,255,255,.06);font-size:12px">' +
      '<div style="flex:0 0 66px;color:#8b949e">' + esc(OOC_LABEL[kk] || kk) + '</div>' +
      '<div style="flex:1;min-width:0;color:#e6edf3;word-break:break-word">' +
      esc(String(hits[kk] || '')) + '</div></div>';
  }

  h += '<div style="display:flex;gap:8px;margin-top:14px">' +
    '<button class="ar6-b on" data-ar6-card="ours" style="flex:1;justify-content:center">Dùng của chúng ta</button>' +
    '<button class="ar6-b" data-ar6-card="preset" style="flex:1;justify-content:center">Dùng của preset</button>' +
    '</div>';

  h += '<label style="display:flex;gap:7px;align-items:center;margin-top:11px;font-size:11px;' +
    'color:#8b949e;cursor:pointer">' +
    '<input type="checkbox" data-ar6-chk="1" style="accent-color:#E8C46A">' +
    '<span>Sau này đều theo hướng này, đừng hỏi lại</span></label>';

  h += '</div></div>';

  var node = null;
  try { node = mountHTML(h); } catch (e6) { node = null; }
  if (!node) { if (cb) cb(''); return; }

  node.addEventListener('click', function (ev) {
    var t = ev && ev.target, btn = null;
    while (t && t !== node) {
      if (t.getAttribute && t.getAttribute('data-ar6-card')) { btn = t; break; }
      t = t.parentNode;
    }
    if (!btn) return;
    var act = btn.getAttribute('data-ar6-card');
    var choice = act === 'preset' ? 'preset' : 'script';
    var j, m;
    for (j = 0; j < keys.length; j++) {
      oocSetChoice(keys[j], choice);
      m = OOC_CFGKEY[keys[j]];
      /* Dùng của chúng ta: Mục này bắt buộc phải thực sự bật; Dùng của preset: Tắt công tắc, chip gán nhãn "Nghe preset" */
      if (m) cfg[m] = choice === 'script';
    }
    var chk = null;
    try { chk = node.querySelector('[data-ar6-chk="1"]'); } catch (e7) { chk = null; }
    if (chk && chk.checked) {
      cfg.oocPolicy = choice;
      banner(choice === 'preset' ? 'Chống OOC: Sau này các mục xung đột đều nghe theo preset' : 'Chống OOC: Sau này các mục xung đột đều dùng của chúng ta', 'gray');
    }
    try { saveCfg(); } catch (e8) {}
    try { closeCard(); } catch (e9) {}
    if (cb) cb(act);
  });
}

function onPanelClick(e) {
  /* Khử trùng lặp dự phòng: Chỉ có hiệu lực trên "click ngay sau pointerdown" (Android chạm nhẹ một cái sẽ bắn liên tiếp 2 sự kiện,
     mà việc render lại đã tráo đổi node khiến timestamp trong closure cũ mất tác dụng). Nhấp click thuần túy liên tiếp không bị ảnh hưởng. */
  {
    var a0 = e && e.target && e.target.getAttribute ? e.target.getAttribute('data-ar6') : '';
    if (a0) {
      var ty0 = (e && e.type) || 'click';
      var nowT = Date.now();
      if (nowT < ACT_FREEZE) return;                       /* Trong thời gian ngắt mạch thì không xử lý */
      var gap = ACT_GAP[a0];
      if (gap && nowT - gap.t0 <= 1500) {
        gap.n++;
        if (gap.n > 6) {                                   /* Cùng một hành động trong 1.5s > 6 lần ⇒ đóng băng 2s */
          ACT_FREEZE = nowT + 2000;
          gap.n = 0; gap.t0 = nowT;
          if (nowT - ACT_TRIP_AT > 8000) {
            ACT_TRIP_AT = nowT;
            try { banner('Nút bấm bị kích hoạt liên tục, đã tạm khóa 2 giây (nghi vấn host gửi trùng lặp click)', 'warn'); } catch (eB) {}
          }
          return;
        }
        if (nowT - gap.t0 < 250) return;                   /* Cùng một hành động trong 250ms chỉ nhận một lần */
      } else {
        ACT_GAP[a0] = { n: 1, t0: nowT };
      }
      var rec0 = ACT_TS[a0];
      if (ty0 === 'click' && rec0 && rec0.type === 'pointerdown' && nowT - rec0.ts < 600) return;
      ACT_TS[a0] = { type: ty0, ts: nowT };
    }
  }
  var t = e.target;
  while (t && t !== DOC.body && !(t.getAttribute && t.getAttribute('data-ar6'))) t = t.parentNode;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-ar6');
  if (!act) return;

  if (act === 'verify') {
    banner('🔭 Đang xác minh kênh (đầu dò bí danh ma)…', 'gray');
    runChannelVerify().then(function (r) {
      if (r.why === 'echo') { banner('⚠️ Kênh không đọc model (hồi hiển): Không thể xác minh danh tính, phán định hạ cấp thành "hồi hiển"', 'warn'); return; }
      if (r.why === 'rejected') { banner('✅ Kênh có thể kiểm tra: Tên ma bị từ chối (HTTP ' + r.status + '), trường model có thể dùng làm bằng chứng', 'ok'); return; }
      banner('❔ ' + (r.note || 'Không thể phán đoán'), 'warn');
    })['catch'](function (e) { banner('Xác minh gặp lỗi: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'alias') {
    banner('🏷 Đang quét bí danh (5 ứng viên, mỗi mục 16 token)…', 'gray');
    runAliasSweep().then(function (r) {
      if (!r.ok) { banner('Quét thất bại: ' + (r.msg || 'Không rõ'), 'bad'); return; }
      var ok = 0;
      for (var i = 0; i < r.rows.length; i++) if (r.rows[i].ok) ok++;
      banner('🏷 Quét bí danh hoàn tất: ' + ok + '/' + r.rows.length + ' khả dụng, xem chi tiết ở bảng điều khiển', ok ? 'ok' : 'warn');
    })['catch'](function (e) { banner('Quét gặp lỗi: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'level') {
    banner('🧠 Đang so sánh hai cấp độ HIGH / minimal…', 'gray');
    runLevelCheck().then(function (r) {
      if (!r.ok) { banner('Kiểm tra cấp độ thất bại: ' + (r.msg || 'Không rõ'), 'bad'); return; }
      if (r.verdict === 'honored') banner('✅ ' + r.note, 'ok');
      else if (r.verdict === 'ignored') banner('⚠️ ' + r.note, 'warn');
      else banner(r.note, 'gray');
    })['catch'](function (e) { banner('Kiểm tra cấp độ gặp lỗi: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'slim') {
    var raw = '';
    try { raw = (lastReq && (lastReq.raw || JSON.stringify(lastReq.body || {}))) || ''; } catch (eR) { raw = ''; }
    var rep0 = slimReport(raw);
    if (!rep0) { banner('🪶 Hãy chạy một lượt đối thoại trước, rồi mới kiểm tra tinh giản', 'gray'); return; }
    banner('🪶 ' + rep0.advice, Number(rep0.chars) > 12000 ? 'warn' : 'ok');
    return;
  }
  if (act === 'idprobe') {
    if (ID.running) { banner('Sàng lọc danh tính đang chạy, vui lòng đợi…', 'gray'); return; }
    banner('Đang chạy sàng lọc danh tính (8 token xấu, một request nhỏ)…', 'gray');
    runIdentityProbe().then(function (r) {
      if (!r.ok) { banner('Sàng lọc danh tính thất bại: ' + (r.msg || 'Không rõ'), 'bad'); return; }
      if (r.verdict === 'fail') banner('⚠️ ' + r.label + ': ' + r.note, 'bad');
      else if (r.verdict === 'pass') banner('✅ ' + r.label + ': ' + r.note, 'ok');
      else banner(r.label + ': ' + r.note, 'gray');
    })['catch'](function (e) { banner('Sàng lọc danh tính gặp lỗi: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'card') { openCard(null, 'engine'); return; }
  if (act === 'help') { openHelp('how'); return; }
  if (act === 'report') { openCard(null, 'human'); return; }
  if (act === 'expand') { PAD_OPEN = false; minimized = false; syncMin(); render(); return; }
  if (act === 'min') { PAD_OPEN = false; minimized = true; syncMin(); render(); return; }
  if (act === 'padclose') { closePad(); return; }
  if (act === 'padpanel') { PAD_OPEN = false; minimized = false; syncMin(); render(); return; }
  if (act === 'tuck') {
    PAD_OPEN = false;
    cfg.floatMode = 'tuck';
    cfg.fEdge = ((isFinite(Number(cfg.fxN)) ? Number(cfg.fxN) : 1) < 0.5) ? 'l' : 'r';
    minimized = true; syncMin(); render();
    banner('Đã thu gọn hít mép: Mép màn hình vẫn để lại một tay cầm, nhấp vào là mở lại', 'gray');
    return;
  }
  if (act === 'hide') {
    /* Lối vào phiên bản cũ: Không còn ẩn hoàn toàn nữa mà chuyển thành hít mép (hidden là cánh cửa một chiều) */
    cfg.floatMode = 'tuck';
    cfg.fEdge = ((isFinite(Number(cfg.fxN)) ? Number(cfg.fxN) : 1) < 0.5) ? 'l' : 'r';
    minimized = true; syncMin(); render();
    banner('Đã thu gọn hít mép (nhấp tay cầm ở mép để quay lại)', 'gray');
    return;
  }

  if (act === '🩺 安全:开' || act === '🩺 安全:关' || act === '🩺 An toàn:Bật' || act === '🩺 An toàn:Tắt') {
    cfg.safe = !cfg.safe;
    saveCfg();
    ensureHooks();
    banner(cfg.safe ? '🩺 Chế độ an toàn: Đã dừng hook (chỉ giữ lại bảng điều khiển)' : '🛡️ Đã khôi phục hook', cfg.safe ? 'warn' : 'ok');
    render();
    return;
  }
  if (act && (act.indexOf('● 已开启') >= 0 || act.indexOf('● Đã bật') >= 0 || act === '● 已开启' || act === '○ 已关闭' || act === '● Đã bật' || act === '○ Đã tắt')) {
    cfg.enabled = !cfg.enabled; saveCfg(); render();
    banner(cfg.enabled ? 'Bảo vệ đã bật' : 'Bảo vệ đã tắt', cfg.enabled ? 'ok' : 'gray');
    return;
  }
  if (act.indexOf('🩹 补前先问:') === 0 || act.indexOf('🩹 Hỏi trước khi bù:') === 0 || act.indexOf('🔔 确认:') === 0 || act.indexOf('🔔 Xác nhận:') === 0) {
    cfg.jailConfirm = (cfg.jailConfirm === false);
    saveCfg(); render();
    banner(cfg.jailConfirm ? '🔔 Trước khi bù sẽ hỏi bạn trước' : '🔔 Không hỏi nữa, tự động bù', cfg.jailConfirm ? 'ok' : 'warn');
    return;
  }
  if (act === 'jailnow') {
    var lastAi = jailLastAi();
    if (!lastAi) { banner('🩹 Không có chính văn để viết tiếp (tin nhắn cuối không phải của AI)', 'gray'); return; }
    var tailTxt = String(lastAi.msg.mes || '');
    var whyTxt = jailTruncWhy(tailTxt, tailTxt.length);
    var jObj = { code: whyTxt ? 'trunc' : (tailTxt.trim() ? 'ok' : 'empty'), note: whyTxt || (tailTxt.trim() ? 'Thủ công bù một lần' : 'Mục này không có chính văn') };
    var gMan = jailGate(String(lastAi.idx) + '|' + String(lastAi.msg.send_date || ''));
    if (!gMan.ok) {
      banner(gMan.why === 'max' ? '🩹 Lượt này đã bù ' + JL.count + ' lần rồi' : '🩹 Hiện tại không thể bù (' + gMan.why + ')', 'warn');
      return;
    }
    jailOffer(jObj);
    return;
  }
  /* v0.6 Kháng cắt cụt: Vòng lặp ba nấc Tắt → Nấc nhẹ → Nấc vừa → Tắt */
  if (act.indexOf('✂️ 抗截断:') === 0 || act.indexOf('✂️ Kháng cắt cụt:') === 0 || act.indexOf('✂️ Chống cắt cụt:') === 0) {
    cfg.trunc = truncNext(cfg.trunc);
    var tm = '✂️ Kháng cắt cụt: ' + truncLabel(cfg.trunc);
    if (cfg.trunc === 'light') tm += ' (Mỗi lượt dán prompt vào đuôi tin nhắn cuối: Neo số từ + Khế ước kết thúc + Không dùng lời kết; Không sửa tham số, không viết bù)';
    if (cfg.trunc === 'medium') tm += ' (Toàn bộ nấc nhẹ + Tự động bù một lần khi độ dài/ngắt câu/tạm dừng bất thường; Bị kiểm duyệt chặn sẽ không bù)';
    saveCfg(); render();
    banner(tm, cfg.trunc === 'off' ? 'gray' : 'warn');
    return;
  }
  /* v0.7 Nấc nhẹ v2: Chip neo số từ, 0 → 800 → 1200 → 1800 → 0 */
  if (act.indexOf('📏 字数锚:') === 0 || act.indexOf('📏 Neo số từ:') === 0 || act.indexOf('📏 Neo số chữ:') === 0) {
    cfg.truncLen = truncLenNext(cfg.truncLen);
    var lm = cfg.truncLen > 0
      ? ('📏 Neo số từ: Chính văn không dưới ' + cfg.truncLen + ' chữ' + (truncLevel(cfg.trunc) === 'off' ? ' (Kháng cắt cụt vẫn đang tắt, hãy bấm "✂️ Kháng cắt cụt" để mở trước)' : ''))
      : '📏 Neo số từ: Tắt (Không yêu cầu độ dài, chỉ giữ khế ước kết thúc)';
    saveCfg(); render();
    banner(lm, cfg.truncLen > 0 ? 'warn' : 'gray');
    return;
  }
  if (act.indexOf('🩹 破甲:') === 0 || act.indexOf('🩹 Phá giáp:') === 0) {
    var nx = jailNext();
    /* v0.3: Vào nấc siêu cấp phải hỏi trước một lần; bước này chưa đổi cfg, người dùng bấm "Bật" mới có hiệu lực */
    if (nx === 'strong') { jailSuperAsk(); return; }
    cfg.jail = nx;
    var jm = '🩹 Phá giáp: ' + jailLabel();
    if (nx !== 'off' && !cfg.observe) { cfg.observe = true; jm += ' (Đã tự động mở bộ quan sát, việc viết bù cần dựa vào nó để kích hoạt)'; }
    if (nx === 'strong') {
      var jp = [];
      if (cfg.jailTok) jp.push('Token bảo đảm');
      if (cfg.jailSafe) jp.push('Gỡ an toàn');
      if (cfg.jailPre) jp.push('Hộp duyệt trước');
      if (cfg.jailText) jp.push('Khế ước xuất chữ');
      jm += ' (Sửa request: ' + (jp.length ? jp.join(' + ') : 'Chưa bật mục con, tương đương chỉ cứu vãn sau sự việc') + ')';
    }
    saveCfg(); ensureHooks(); render();
    banner(jm, nx === 'off' ? 'gray' : 'warn');
    return;
  }
  if (act.indexOf('保底token:') === 0 || act.indexOf('Token bảo đảm:') === 0) { cfg.jailTok = !cfg.jailTok; saveCfg(); render(); return; }
  if (act.indexOf('解安全:') === 0 || act.indexOf('Gỡ an toàn:') === 0) { cfg.jailSafe = !cfg.jailSafe; saveCfg(); render(); return; }
  if (act.indexOf('预审框:') === 0 || act.indexOf('Hộp duyệt trước:') === 0) { cfg.jailPre = !cfg.jailPre; saveCfg(); render(); return; }
  if (act.indexOf('输出契约:') === 0 || act.indexOf('Khế ước xuất chữ:') === 0) { cfg.jailText = !cfg.jailText; saveCfg(); render(); return; }

  /* v8.31 Tầng tự sự: Vòng lặp ba nấc Tắt → Nhẹ → Mạnh → Tắt */
  if (act.indexOf('🧭 防全知:') === 0 || act.indexOf('🧭 Chống toàn tri:') === 0) {
    var nxKnow = narrNext(cfg.know);
    /* Trước khi bật phải nói rõ cái giá: Cấm viết tiếng lòng, cấm quyết định thay người khác */
    if (narrTipNeeded(nxKnow, cfg.knowTip)) { knowTipDialog(nxKnow); return; }
    cfg.know = nxKnow; saveCfg(); render();
    banner('🧭 Chống toàn tri: ' + narrTag(cfg.know), cfg.know === 'off' ? 'gray' : 'ok');
    return;
  }
  if (act.indexOf('💄 去媚:') === 0 || act.indexOf('💄 Bỏ nịnh:') === 0) {
    cfg.charm = narrNext(cfg.charm); saveCfg(); render();
    banner('💄 Bỏ nịnh: ' + narrTag(cfg.charm), cfg.charm === 'off' ? 'gray' : 'ok');
    return;
  }

  /* v0.76 Chống OOC: Công tắc tổng + 4 mục con. Tiền tố đều kèm emoji và dấu cách, không đụng hàng với tầng tự sự */
  if (act.indexOf('🎭 反OOC:') === 0 || act.indexOf('🎭 Chống OOC:') === 0) {
    var oocNow = String(cfg.ooc || 'off') === 'on' ? 'off' : 'on';
    cfg.ooc = oocNow; saveCfg(); render();
    banner('🎭 Chống OOC: ' + (oocNow === 'on' ? 'Bật' : 'Tắt'), oocNow === 'on' ? 'ok' : 'gray');
    return;
  }
  if (act.indexOf('🧩 点名:') === 0 || act.indexOf('🧩 Điểm danh:') === 0) { oocToggle('roll'); return; }
  if (act.indexOf('🚫 反模板:') === 0 || act.indexOf('🚫 Chống văn mẫu:') === 0 || act.indexOf('🚫 Chống rập khuôn:') === 0) { oocToggle('tpl'); return; }
  if (act.indexOf('🔒 变更门槛:') === 0 || act.indexOf('🔒 Ngưỡng biến đổi:') === 0 || act.indexOf('🔒 Ngưỡng thay đổi:') === 0) { oocToggle('chg'); return; }
  if (act.indexOf('🗣 口吻一致:') === 0 || act.indexOf('🗣 Nhất quán khẩu khí:') === 0 || act.indexOf('🗣 Giữ nguyên giọng điệu:') === 0) { oocToggle('voice'); return; }
  if (act.indexOf('🪶 微扰') === 0 || act.indexOf('🪶 Vi nhiễu') === 0) {
    cfg.refract = cfg.refract === 'off' ? 'light' : (cfg.refract === 'light' ? 'mid' : 'off');
    saveCfg(); render();
    banner('🪶 Nấc vi nhiễu: ' + profileLabel(), cfg.refract === 'off' ? 'gray' : 'ok');
    return;
  }
  if (act.indexOf('🧠 思考') === 0 || act.indexOf('🧠 Suy nghĩ') === 0) {
    cfg.think = cfg.think === 'high' ? 'off' : 'high'; saveCfg(); render();
    banner(cfg.think === 'high' ? '🧠 Chỉ khi thiếu trường mới bù reasoning_effort=high' : '🧠 Nấc suy nghĩ nhường lại cho preset', 'gray');
    return;
  }
  if (act.indexOf('📌 钉参数') === 0 || act.indexOf('📌 Ghim tham số') === 0) {
    cfg.pin = !cfg.pin; saveCfg(); render();
    banner('📌 Ghim tham số ' + (cfg.pin ? 'Bật' : 'Tắt'), cfg.pin ? 'ok' : 'gray');
    return;
  }
  /* v0.82 Baseline hành vi: Mặc định bật, cung cấp một nơi có thể tắt */
  if (act.indexOf('📈 行为基线') === 0 || act.indexOf('📈 Baseline hành vi') === 0) {
    cfg.base = (String(cfg.base || 'on') === 'on') ? 'off' : 'on'; saveCfg(); render();
    banner('📈 Baseline hành vi ' + (cfg.base === 'on' ? 'Bật' : 'Tắt'), cfg.base === 'on' ? 'ok' : 'gray');
    return;
  }
  /* v0.84 Fingerprint cấu trúc: Mặc định bật, chỉ nhắc nhở; tắt đi tức là không ghi không phán định */
  if (act.indexOf('🔬 返回格式') === 0 || act.indexOf('🔬 Định dạng trả về') === 0) {
    cfg.shape = (String(cfg.shape || 'on') === 'on') ? 'off' : 'on'; saveCfg(); render();
    banner('🔬 Định dạng trả về ' + (cfg.shape === 'on' ? 'Bật' : 'Tắt'), cfg.shape === 'on' ? 'ok' : 'gray');
    return;
  }

  /* v0.94 Chỉ kiểm tra Gemini: Mặc định bật. Tắt đi sẽ quay về "kiểm tra tất cả" */
  if (act.indexOf('🟦 只查 Gemini') === 0 || act.indexOf('🟦 Chỉ kiểm tra Gemini') === 0) {
    cfg.onlyGemini = (cfg.onlyGemini === false);
    saveCfg(); render();
    banner(cfg.onlyGemini === false
      ? '🟦 Kiểm tra tất cả model (không phải Gemini cũng vào sổ cái)'
      : '🟦 Chỉ kiểm tra Gemini (các model khác không phán định, không vào sổ cái)',
      cfg.onlyGemini === false ? 'gray' : 'ok');
    return;
  }

  /* v0.94 Một chạm: Kiểm tra + Cài đặt. Không bắt buộc phải mở công tắc trước, cũng không bắt buộc phải điền địa chỉ trước */
  if (act.indexOf('⬆ 检查更新') === 0 || act.indexOf('⬆ Kiểm tra cập nhật') === 0) {
    banner('⬆ Đang kiểm tra xem có bản mới không…', 'gray');
    updQuick().then(function (r) {
      if (r && r.ok && r.installed) {
        banner('✅ Đã cài v' + r.version + ', refresh trang một lần để có hiệu lực (chưa có hiệu lực thì bấm "↩ Hoàn tác cập nhật")', 'ok');
      } else if (r && r.ok && !r.newer) {
        banner('✅ Đã là bản mới nhất v' + VERSION, 'ok');
      } else {
        banner('⬆ Cập nhật không thành: ' + updErrText((r && r.err) || '?', r), 'warn');
      }
      try { render(); } catch (eQ) {}
    })['catch'](function () { banner('⬆ Cập nhật không thành: Lỗi mạng', 'warn'); });
    return;
  }

  /* v0.94 Cài bản mới một chạm: Cài xong không tự động refresh, để người dùng tự nhấp, cũng chừa đường "Hoàn tác" */
  if (act.indexOf('⬇ 装新版') === 0 || act.indexOf('⬇ Cài bản mới') === 0) {
    banner('⬇ Đang tải bản mới…', 'gray');
    updInstall().then(function (r) {
      if (r && r.ok) {
        banner('✅ Đã cài v' + r.version + ', refresh trang một lần để có hiệu lực (chưa có hiệu lực thì bấm "↩ Hoàn tác cập nhật")', 'ok');
      } else {
        var why = (r && r.err) || '?';
        banner('⬇ Cài đặt thất bại: ' + updErrText(why, r), 'warn');
      }
      try { render(); } catch (eR) {}
    }).then(null, function () { banner('⬇ Cài đặt thất bại: Lỗi mạng', 'warn'); });
    return;
  }

  if (act.indexOf('↩ 撤销更新') === 0 || act.indexOf('↩ Hoàn tác cập nhật') === 0) {
    var uu2 = updUndo();
    banner(uu2 && uu2.ok ? '↩ Đã quay về phiên bản trước, refresh trang một lần để có hiệu lực' : '↩ Hoàn tác thất bại: Không có phiên bản để quay về', uu2 && uu2.ok ? 'ok' : 'warn');
    try { render(); } catch (eU2) {}
    return;
  }

  /* v0.94 Kiểm tra phiên bản mới: Mặc định tắt, người dùng tự mở mới kiểm tra. Khi mở tiện tay kiểm tra một lần,
     nếu không người dùng phải đợi lần sau mở bảng điều khiển mới biết có bản mới hay không */
  if (act.indexOf('⟳ 开面板自动查') === 0 || act.indexOf('⟳ Tự kiểm tra khi mở bảng') === 0) {
    cfg.upd = (String(cfg.upd || 'off') === 'check') ? 'off' : 'check';
    saveCfg(); render();
    banner('⟳ Tự kiểm tra khi mở bảng ' + (cfg.upd === 'check' ? 'Bật' : 'Tắt'), cfg.upd === 'check' ? 'ok' : 'gray');
    if (cfg.upd === 'check') {
      updCheck(true).then(function (r) {
        if (r && r.ok && r.newer) {
          banner('⬆ ' + updLine() + '  Bấm "⬇ Cài bản mới" để cài trực tiếp', 'warn');
          render();
        }
        /* Các thất bại khác hoàn toàn im lặng: Không tra cứu được không phải lỗi của người dùng */
      })['catch'](function () {});
    }
    return;
  }

  if (act.indexOf('👁 观察器') === 0 || act.indexOf('👁 Bộ quan sát') === 0) {
    cfg.observe = !cfg.observe; saveCfg(); render();
    banner('👁 Bộ quan sát zero-lock ' + (cfg.observe ? 'Bật' : 'Tắt'), cfg.observe ? 'ok' : 'gray');
    return;
  }

  if (act.indexOf('🎯 范围:') === 0 || act.indexOf('🎯 Phạm vi:') === 0) {
    cfg.scope = cfg.scope === 'all' ? 'skip' : (cfg.scope === 'skip' ? 'only' : 'all');
    saveCfg(); render();
    banner('Phạm vi phát hiện: ' + scopeLabel() + (cfg.scope === 'all' ? ' (Tất cả model đều phán định)' : ''), cfg.scope === 'all' ? 'gray' : 'ok');
    return;
  }
  if (act === 'savescope') {
    var si = DOC.querySelector('[data-ar6="scope"]');
    if (si) cfg.scopeList = String(si.value || '').trim();
    saveCfg(); render();
    banner('Phạm vi đã lưu: ' + (cfg.scopeList || ' (Trống = không lọc)'), 'ok');
    return;
  }

  if (act === 'native') { runNativeProbe(); return; }
  if (act === 'dual') { runDualProbe(); return; }
  if (act === 'fp') { banner(fpCard().replace(/\n/g, ' ｜ '), 'gray'); return; }
  if (act === 'exportlog') { copyTo(exportText(), '📤 Xuất bản ghi'); return; }
  if (act === 'abtest') {
    if (AB_STATE.running) { banner('⚖️ Đang chạy đối chiếu, vui lòng đợi…', 'gray'); return; }
    banner('⚖️ Đang chạy đối chiếu A/B (không cấu hình / có cấu hình mỗi loại 2 lần)…', 'gray');
    abProbe().then(function (r) {
      banner(r.ok ? ('⚖️ ' + r.note) : ('⚖️ Đối chiếu thất bại: ' + (r.msg || 'Không rõ')), r.ok ? 'gray' : 'bad');
    })['catch'](function (e) { banner('⚖️ Gặp lỗi: ' + String((e && e.message) || e), 'bad'); });
    return;
  }
  if (act === 'self') { runSelfTestUI(); return; }
  /* Xóa sạch: Sổ cái + baseline cùng xóa một lúc. Nếu chỉ xóa sổ cái thì baseline vẫn là cái cũ,
     người dùng tưởng là "bắt đầu lại từ đầu", thực chất vẫn đang lấy mốc tham chiếu cũ để đưa ra kết luận. */
  if (act === 'clear') {
    try { HOST.localStorage.removeItem(LOG_KEY); } catch (e) {}
    try { HOST.localStorage.removeItem(BASE_KEY); } catch (e2) {}
    try { HOST.localStorage.removeItem(SHAPE_KEY); } catch (e3) {}
    selfTestResult = null;
    banner('🧹 Sổ cái và baseline đều đã được xóa sạch', 'ok');
    render();
    return;
  }
  /* Dựng lại baseline: Bấm liên tiếp 2 lần để xác nhận (trên điện thoại confirm thường bị chặn, hơn nữa bước này chỉ xóa dữ liệu máy cục bộ,
     dùng nhấp đúp xác nhận tiện hơn popup nhiều) */
  if (act === 'rebuild') {
    var nowR = Date.now();
    if (nowR - REBUILD_AT > 5000) {
      REBUILD_AT = nowR;
      banner('⚠ Bấm lại "Dựng lại baseline" một lần nữa để xác nhận: Xóa sạch thời gian TTFT / tốc độ xuất chữ / định dạng trả về đã học, trong 8 lượt tiếp theo sẽ không hiển thị nhắc nhở', 'warn');
      return;
    }
    REBUILD_AT = 0;
    try { HOST.localStorage.removeItem(BASE_KEY); } catch (e4) {}
    try { HOST.localStorage.removeItem(SHAPE_KEY); } catch (e5) {}
    banner('🧹 Baseline đã xóa sạch: Trong 8 lượt tới sẽ học lại từ đầu, thời gian này sẽ không đưa ra gợi ý cảm giác tay / định dạng', 'ok');
    render();
    return;
  }
  if (act === 'save') {
    var b = DOC.querySelector('[data-ar6="base"]');
    var k = DOC.querySelector('[data-ar6="key"]');
    var uu = DOC.querySelector('[data-ar6="updurl"]');
    if (b) cfg.dualBase = String(b.value || '').trim();
    if (k) cfg.dualKey = String(k.value || '').trim();
    if (uu) cfg.updUrl = String(uu.value || '').trim();
    saveCfg();
    banner('Đã lưu Base/Key', 'ok');
    return;
  }
  if (act === 'copy') {
    var lr = lastReq;
    var txt = lr ? ('model=' + lr.model + '\nbase=' + lr.base + '\n\n' + String(lr.raw || '').slice(0, 4000)) : '(Chưa bắt được request nào)';
    copyTo(txt, 'Request gần nhất');   /* Không bắt promise sẽ thành báo thành công giả: Copy thất bại cũng phải báo thất bại */
    return;
  }
  if (act === 'selftoggle') {
    var box = DOC.getElementById('ar6-selftest');
    if (box) box.style.display = box.style.display === 'none' ? 'block' : 'none';
    return;
  }
}

function onPanelInput(e) {
  var t0 = e && e.target;
  if (t0 && t0.getAttribute && t0.getAttribute('data-ar6-pad')) {
    var ax = t0.getAttribute('data-ar6-pad');
    var v = Math.max(0, Math.min(100, Number(t0.value) || 0)) / 100;
    if (ax === 'x') { cfg.fxN = v; cfg.fEdge = v < 0.5 ? 'l' : 'r'; }
    else cfg.fyN = v;
    try { floatApplyPosition(root(), true); } catch (eP) {}
    return;
  }
  var t = e.target;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-ar6');
  var pos = t.getAttribute('data-ar6-pos');
  if (pos) {
    var v = Math.max(0, Math.min(1, (Number(t.value) || 0) / 100));
    if (pos === 'x') {
      cfg.fxN = v;
      cfg.fEdge = v <= 0.02 ? 'l' : (v >= 0.98 ? 'r' : '');
    } else {
      cfg.fyN = v;
    }
    try {
      var rr = DOC.getElementById(ROOT_ID);
      if (rr && minimized) {
        /* v8.3: Trạng thái mở rộng chỉ đổi tọa độ, không đụng kích thước box (nếu không cả bảng điều khiển sẽ bị bóp thành quả cầu) */
        floatApplyPosition(rr, true);
        var lab = t.parentNode && t.parentNode.querySelector('b');
        if (lab) lab.textContent = Math.round(v * 100) + '%';
      }
    } catch (eP) {}
    return;   /* Vị trí chỉ xem trước: Không render, không lưu database */
  }
  if (act === 'base') cfg.dualBase = String(t.value || '');
  if (act === 'key') cfg.dualKey = String(t.value || '');
  if (act === 'updurl') cfg.updUrl = String(t.value || '');
  if (act === 'base' || act === 'key' || act === 'updurl') saveCfg();
}

/* v8.1: Thả tay khỏi thanh trượt mới lưu database */
function onPanelChange(e) {
  var t = e.target;
  if (!t || !t.getAttribute) return;
  if (t.getAttribute('data-ar6-pad')) { try { saveCfg(); } catch (e) {} return; }
  if (t.getAttribute('data-ar6-pos')) { try { saveCfg(); } catch (e) {} }
}

/* ---------------- Điểm vào render ---------------- */

function installFloatDrag(el, box) {
  try {
    if (!el || !box || el.__ar6drag) return;
    var head = el.querySelector(".ar6-h");
    if (!head) return;
    el.__ar6drag = true;
    head.style.touchAction = "none";
    head.style.cursor = "move";
    var sx = 0, sy = 0, ox = 0, oy = 0, moving = false;
    head.addEventListener("pointerdown", function (e) {
      try {
        if (e.target && e.target.closest && e.target.closest("button")) return;
        var r = box.getBoundingClientRect();
        box.style.left = Math.round(r.left) + "px";
        box.style.top = Math.round(r.top) + "px";
        box.style.right = "auto";
        box.style.bottom = "auto";
        sx = e.clientX; sy = e.clientY; ox = r.left; oy = r.top; moving = true;
        if (head.setPointerCapture) head.setPointerCapture(e.pointerId);
        if (e.preventDefault) e.preventDefault();
      } catch (e1) {}
    }, { passive: false });
    head.addEventListener("pointermove", function (e) {
      if (!moving) return;
      try {
        var w = box.offsetWidth || 300, h = box.offsetHeight || 200;
        var vw = HOST.innerWidth || 360, vh = HOST.innerHeight || 640;
        var nx = Math.max(6, Math.min(vw - w - 6, ox + (e.clientX - sx)));
        var ny = Math.max(6, Math.min(vh - Math.max(h, 60) - 6, oy + (e.clientY - sy)));
        box.style.left = Math.round(nx) + "px";
        box.style.top = Math.round(ny) + "px";
      } catch (e2) {}
    });
    var up = function () {
      if (!moving) return;
      moving = false;
      try {
        var r2 = box.getBoundingClientRect();
        cfg.mx = Math.round(r2.left);
        cfg.my = Math.round(r2.top);
        saveCfg();
      } catch (e3) {}
    };
    head.addEventListener("pointerup", up);
    head.addEventListener("pointercancel", up);
  } catch (e) {}
}

/* v8.31: Thanh công cụ chỉ giữ một lối vào duy nhất để vào bảng điều khiển. Logic mở rộng thống nhất với đường Đũa phép,
   chỉ là không tính lại neo "hít góc dưới bên phải" — người dùng vào từ nút của host thì vị trí cứ kế thừa lần trước. */
function openPanel() {
  minimized = false;
  try { PAD_OPEN = false; } catch (eO0) {}
  try { cfg.min = false; if (typeof saveCfg === 'function') saveCfg(); } catch (eO1) {}
  try { closeCard(); } catch (eO2) {}
  render();
  try { var rO = root(); if (rO) fitPanel(rO); } catch (eO3) {}
  try { verifyVisible(); } catch (eO4) {}
  try { banner('🛡 Bảng điều khiển chống route đã mở', 'ok'); } catch (eO5) {}
}

function openPanelFromWand() {
  minimized = false;
  try { PAD_OPEN = false; } catch (eP0) {}
  try { cfg.min = false; if (typeof saveCfg === 'function') saveCfg(); } catch (eP1) {}
  try { closeCard(); } catch (eP2) {}
  render();
  try {
    var r = root();
    if (r) {
      /* v8.30: Trước đây ở đây ghi đè toàn bộ inline style bằng kết quả của panelStyle(...),
         sẽ xóa mất height/maxHeight/overflow:hidden vừa được mountAll→fitPanel thiết lập,
         trên điện thoại bấm Đũa phép mở lại thì bảng điều khiển tụt về chiều cao phần trăm cố định + cuộn ngoài — nguyên nhân trực tiếp của "chỉ có nửa trên".
         Bây giờ chỉ xóa transform tồn đọng khi kéo thả, toàn bộ kích thước hình học giao trọn cho một mình fitPanel xử lý. */
      try { r.style.transform = ''; r.style.transition = ''; } catch (eT0) {}
      var vw = (HOST.visualViewport && HOST.visualViewport.width) || HOST.innerWidth || 390;
      var w = uiMode() === 'mobile' ? Math.min(vw * 0.92, 380) : 440;
      cfg.mx = Math.max(8, Math.round(vw - w - 12));
      cfg.my = Math.max(72, Math.round(((HOST.visualViewport && HOST.visualViewport.height) || HOST.innerHeight || 700) * 0.18));
      saveCfg();
      r.style.left = cfg.mx + 'px';
      r.style.top = cfg.my + 'px';
      r.style.right = 'auto';
      r.style.bottom = 'auto';
      try { fitPanel(r); } catch (eFP2) {}
      try { verifyVisible(); } catch (eVV) {}
    }
  } catch (eP3) {}
  return true;
}

function syncMin() { cfg.min = !!minimized; if (typeof saveCfg === 'function') saveCfg(); }

function render() { if (DISPOSED) return; try { mountAll(); } catch (e) { try { HOST.console.warn('[AR6] render error', e); } catch (e2) {} } }

function renderStatus() {
  try {
    var r = DOC && DOC.getElementById(ROOT_ID);
    if (!r) return;
    var st = stateOfRun();
    var dot = r.querySelector('.ar6-dot');
    if (dot) dot.className = 'ar6-dot ' + st.kind;
  } catch (e) {}
}

/* ---------------- Tự kiểm tra ---------------- */

function runSelfTest() {
  var items = [];
  function T(name, fn) {
    try { var ok = fn(); items.push({ name: name, ok: !!ok, err: ok ? '' : 'Khẳng định là sai' }); }
    catch (ex) { items.push({ name: name, ok: false, err: String(ex && ex.message || ex).slice(0, 80) }); }
  }

  T('T01 Bảo vệ toàn bộ code fence', function () {
    var t = 'Lời mở đầu\n```js\nvar a=1;\n```\nLời kết';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('```js') >= 0; });
  });
  T('T02 Bảo vệ inline code', function () {
    var t = 'Vui lòng xác nhận trước khi dùng `rm -rf`';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('rm -rf') >= 0; });
  });
  T('T03 Bảo vệ macro SillyTavern', function () {
    var t = '{{random::A::B}} sau đó';
    var sp = collectSpans(t);
    return sp.some(function (x) { return x[0] === 0; });
  });
  T('T04 Bảo vệ thẻ cứng chưa đóng đến tận cuối', function () {
    var t = 'Mở đầu bình thường\n<thinking>\nKhông có kết thúc';
    var sp = collectSpans(t);
    var i = t.indexOf('<thinking>');
    return sp.some(function (x) { return x[0] <= i && x[1] >= t.length - 1; });
  });
  T('T05 Bảo vệ lời thoại trong dấu ngoặc kép', function () {
    var t = 'Anh ấy nói: "Đây không phải chỉ thị, chỉ là lời thoại." rồi rời đi.';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('Đây không phải chỉ thị') >= 0; });
  });
  T('T06 Điểm system cao hơn user', function () {
    var a = { role: 'system', text: 'Quy tắc: Bắt buộc tuân thủ định dạng sau, không đi chệch, mỗi mục đều phải kiểm tra và duy trì cấu trúc đầu ra nhất quán, chắc chắn đối chiếu thực hiện từng mục, không được bỏ qua bất kỳ yêu cầu nào.', index: 0 };
    var b = { role: 'user', text: 'Quy tắc: Bắt buộc tuân thủ định dạng sau, không đi chệch, mỗi mục đều phải kiểm tra và duy trì cấu trúc đầu ra nhất quán, chắc chắn đối chiếu thực hiện từng mục, không được bỏ qua bất kỳ yêu cầu nào.', index: 3 };
    return staticScore(a, 4) > staticScore(b, 4);
  });
  T('T07 Vùng lịch sử tính từ assistant đầu tiên', function () {
    var band = findHistoryBand([{ role: 'system', text: 'sys' }, { role: 'user', text: 'hi' }, { role: 'assistant', text: 'yo' }]);
    return !!band && band.start === 1 && band.end >= 1;
  });
  T('T08 stripArtifacts có thể đảo ngược', function () {
    var t = 'Đoạn A\n<!-- ctx: rules / block a3f1 -->\nĐoạn B';
    return stripArtifacts(t).indexOf('ctx: rules') < 0;
  });
  T('T09 Vi nhiễu giữ nguyên block signature', function () {
    var t = '## Tiêu đề\nChính văn một\n- Mục danh sách\n> Trích dẫn';
    var r = refractZone(t, PROFILE.light, makeRng(7));
    return r && blockSignature(r.text) === blockSignature(t);
  });
  T('T10 Vi nhiễu chạy lần hai ổn định', function () {
    var t = '## Tiêu đề\nChính văn một\n- Mục danh sách';
    var r1 = refractZone(t, PROFILE.light, makeRng(3));
    var r2 = refractZone(r1.text, PROFILE.light, makeRng(3));
    return r1.text === r2.text;
  });
  T('T11 Trong code block không vi nhiễu', function () {
    var t = '```\n## Không phải tiêu đề\n```';
    var r = refractZone(t, PROFILE.mid, makeRng(5));
    return !r.changed || r.text === t;
  });
  T('T12 Ghim tham số gỡ bỏ models[]', function () {
    var body = JSON.stringify({ model: 'gemini-4-argon', models: ['a', 'b'], allow_fallbacks: true, messages: [{ role: 'user', content: 'hi' }] });
    var p = planRequest(body, 'https://x/chat-completions/generate');
    var o = JSON.parse(p.body);
    return !('models' in o) && o.allow_fallbacks === false;
  });
  T('T13 Ghim tham số không bịa trường ảo', function () {
    var body = JSON.stringify({ model: 'g', messages: [{ role: 'user', content: 'hi' }] });
    var p = planRequest(body, 'https://x/chat-completions/generate');
    var o = JSON.parse(p.body);
    return !('models' in o) && !('route' in o);
  });
  T('T14 Nấc suy nghĩ không ghi đè trường đã có', function () {
    var body = JSON.stringify({ model: 'g', reasoning_effort: 'medium', messages: [{ role: 'user', content: 'hi' }] });
    var p = planRequest(body, 'https://x/chat-completions/generate');
    return JSON.parse(p.body).reasoning_effort === 'medium';
  });
  T('T15 URL không phải generate thì không viết lại', function () {
    var body = JSON.stringify({ model: 'g' });
    var p = planRequest(body, 'https://x/api/backends/chat-completions/status');
    return p.changed.length === 0 && p.body === body;
  });
  T('T16 Cùng model phán định khớp', function () {
    var ev = newEvidence('gemini-4-argon', 200, 'sse');
    ev.sawText = true; ev.hasThink = true; ev.observed.push('google/gemini-4-argon');
    return verdictOf(ev).code === 'same';
  });
  T('T17 Giảm nấc phán định bị tráo', function () {
    var ev = newEvidence('gemini-4-argon', 200, 'sse');
    ev.sawText = true; ev.hasThink = true; ev.observed.push('gemini-3.1-flash-lite');
    return verdictOf(ev).code === 'diff';
  });
  T('T18 4xx không phán định bị tráo', function () {
    var ev = newEvidence('gemini-4-argon', 429, 'json');
    ev.sawText = false;
    return verdictOf(ev).code === 'quota';
  });
  T('T19 normModel bóc tách tiền tố kênh', function () {
    return normModel('pggo-google/gemini-4-argon:generateContent') === 'gemini-4-argon';
  });
  T('T20 estimateTokens ước lượng tiếng Trung', function () {
    var n = estimateTokens('一二三四五六七八九十');
    return n >= 7 && n <= 11;
  });

  selfTestResult = { at: Date.now(), items: items };
  return selfTestResult;
}

function runSelfTestUI() {
  var res = runSelfTest();
  var pass = res.items.filter(function (i) { return i.ok; }).length;
  var bad = res.items.filter(function (i) { return !i.ok; });
  banner('🩺 Tự kiểm tra ' + pass + '/' + res.items.length + (bad.length ? (', thất bại: ' + bad[0].name) : ', tất cả đã vượt qua'), bad.length ? 'bad' : 'ok');
  render();
}

/* ---------------- Nút bấm script ---------------- */

var BTN_BOUND = {};
var BTN_OK = 0;

var BTN_TOTAL = 8;
/* v8.31: Nút của host giảm từ 8 xuống 1 (trong bảng điều khiển có đủ hết), còn có thể tắt hẳn về 0.
   Hằng số BTN_TOTAL này giữ lại chỉ để tương thích với các assertion cũ, thực tế xem theo btnTotal(). */
function btnTotal() { return 1; }
function btnReady() { return BTN_OK >= btnTotal(); }
function btnSummary() {
  return btnTotal() === 0 ? 'Chỉ đũa phép' : (BTN_OK + '/' + btnTotal());
}

function bindScriptButtons() {
  if (bound) return true;
  /* Then chốt: Tavern Helper chạy script bên trong iframe, eventOn/getButtonEvent được tiêm vào "window của chính script",
     không nằm ở tầng cao nhất; nếu chỉ tra cứu HOST/parent/top sẽ trượt toàn bộ ⇒ nút trên thanh công cụ vĩnh viễn không phản hồi */
  var scope = [];
  function push(w) {
    if (!w) return;
    for (var q = 0; q < scope.length; q++) if (scope[q] === w) return;
    scope.push(w);
  }
  push(SELF_WIN);
  try { push(SELF_WIN && SELF_WIN.parent); } catch (e) {}
  push(HOST);
  try { push(HOST && HOST.parent); } catch (e) {}
  try { push(HOST && HOST.top); } catch (e) {}

  /* Mỗi hành động đăng ký nhiều bí danh: Tên nút trong JSON + tên tàn dư bản cũ + tên thuần đã bỏ emoji */
  /* v8.31: Nút của host giảm từ 8 xuống 1 lối vào duy nhất — trong bảng điều khiển mục nào cũng có, thanh công cụ chỉ là cửa vào.
     Tên cũ đều giữ lại làm bí danh: Nếu người dùng cầm cấu hình nút nhập từ bản cũ, bấm vào vẫn mở được bảng điều khiển bình thường. */
  var ACTIONS = [
    { key: 'panel', names: ['🛡 Chống route', '🛡️ Chống route', 'Chống route', '🛡️ Tự kiểm tra trạng thái', 'Tự kiểm tra trạng thái', 'Tự kiểm tra', '🛡 防路由', '🛡️ 防路由', '防路由', '🛡️ 状态自检', '状态自检', '自检'],
      fn: function () { openPanel(); } }
  ];

  for (var i = 0; i < scope.length; i++) {
    var w = scope[i];
    if (!w) continue;
    try {
      if (typeof w.eventOn !== 'function' || typeof w.getButtonEvent !== 'function') continue;
      for (var a = 0; a < ACTIONS.length; a++) {
        var act = ACTIONS[a];
        if (act.panelOnly) continue;
        if (BTN_BOUND[act.key]) continue;
        for (var n = 0; n < act.names.length; n++) {
          var ev = null;
          try { ev = w.getButtonEvent(act.names[n]); } catch (eB) { ev = null; }
          if (!ev) continue;
          (function (fn, nm) {
            try {
              w.eventOn(ev, function () {
                try { fn(); }
                catch (eRun) {
                  try { HOST.console.warn('[AR7] Thực thi nút bấm thất bại: ' + nm, eRun); } catch (eL) {}
                  try { banner('Thực thi nút bấm thất bại: ' + String(eRun && eRun.message || eRun).slice(0, 50), 'bad'); } catch (eB2) {}
                }
              });
              if (!BTN_BOUND[act.key]) {
                BTN_BOUND[act.key] = true;
                BTN_OK++;
              }
            } catch (eOn) {}
          })(act.fn, act.names[n]);
        }
      }
    } catch (e) {}
  }
  if (BTN_OK > 0 && !btnBoundAt) btnBoundAt = Date.now();
  for (var q = 0; q < ACTIONS.length; q++) {
    if (!BTN_BOUND[ACTIONS[q].key]) {
      try { HOST.console.warn('[AR7] Nút thanh công cụ chưa được gán: ' + ACTIONS[q].names[0]); } catch (eW) {}
    }
  }
  try { if (BTN_OK > 0 && !DISPOSED) render(); } catch (eS) {}
  if (BTN_OK >= ACTIONS.length) { bound = true; return true; }
  return BTN_OK > 0;
}

/* ---------------- Vòng đời ---------------- */

function step(name, fn) {
  try { fn(); }
  catch (e) { try { HOST.console.warn('[AR6] ' + name + ' thất bại: ', e); } catch (e2) {} }
}

function boot() {
  DISPOSED = false;
  if (booted) { render(); return; }
  /* Cùng trang đã có một instance đang chạy (cài cả 2 gói desktop và mobile, hoặc nhập trùng lặp): Nhường chỗ.
     Không gắn trùng lặp giao diện, hook và đũa phép, nếu không sẽ xuất hiện tình trạng bảng điều khiển bị xóa sạch, callback nút bấm tê liệt, menu xuất hiện 2 mục cùng tên.
     Dùng một hợp đồng thuê có heartbeat để phán đoán, 30 giây không có heartbeat mới cho phép tiếp quản (tránh chiếm giữ vĩnh viễn sau khi crash). */
  var hold = null;
  try { hold = (HOST && HOST.__AR6HOLD) || null; } catch (eO) { hold = null; }
  if (hold && hold.token !== BOOT_TOKEN && hold.alive !== false && (Date.now() - (hold.at || 0)) < 30000) {
    try { HOST.console && HOST.console.info('[AR6] Đã có instance đang chạy, lần này không tải giao diện và hook'); } catch (eO2) {}
    return;
  }
  booted = true;
  step('Cấu hình', function () { cfg = readCfg(); minimized = !!cfg.min; });
  step('Host', function () { if (!HOST || !DOC) throw new Error('Tài liệu host không khả dụng'); });
  step('Style', function () { ensureStyle(DOC); });
  step('Hook', function () { ensureHooks(); });
  step('Bảng điều khiển', function () { render(); });
  step('Banner', function () {
    var where = (HOST === HOST.top) ? 'Tầng đỉnh' : 'iframe';
    var msg = (hooked ? '' : '') + 'Ánh Sáng Luke V' + VERSION + ' đã sẵn sàng · ' +
      (cfg.enabled ? 'Bảo vệ BẬT' : 'Bảo vệ TẮT') + ' · Host ' + where + (hooked ? '' : ' · Hook chưa được gắn');
    banner(msg, hooked ? 'ok' : 'bad');
  });
  step('Gợi ý hướng dẫn', function () {
    if (!localStorage.getItem('ar6.helpSeen')) {
      localStorage.setItem('ar6.helpSeen', '1');
      setTimeout(function () { try { banner('Lần đầu sử dụng? Bấm vào "Hướng dẫn" ở góc trên bên phải bảng điều khiển, hoặc nhấn giữ quả cầu nổi', 'gray'); } catch (eH) {} }, 2600);
    }
  });
  /* v0.94 Kiểm tra phiên bản mới: Đặt sau banner sẵn sàng, tránh 2 thông báo tranh nhau một vị trí banner;
     Khi công tắc tắt hoặc không tìm thấy, updBoot sẽ tự động im lặng */
  step('Kiểm tra phiên bản', function () { updBoot(); });
  step('Nút bấm', function () { bindScriptButtons(); });
  step('Đũa phép', function () { try { mountWandEntry(); } catch (eM) {} });
  step('Chiếm chỗ', function () {
    /* Tranh quyền thuê: Instance cùng trang sau này thấy heartbeat sẽ tự động nhường chỗ; 30 giây không nhảy sẽ do instance mới tiếp quản */
    try {
      HOST.__AR6HOLD = { token: BOOT_TOKEN, alive: true, at: Date.now() };
      if (BOOT_TIMER) clearInterval(BOOT_TIMER);
      BOOT_TIMER = setInterval(function () {
        try {
          if (HOST.__AR6HOLD && HOST.__AR6HOLD.token === BOOT_TOKEN) HOST.__AR6HOLD.at = Date.now();
          else if (BOOT_TIMER) { clearInterval(BOOT_TIMER); BOOT_TIMER = null; }
        } catch (eH) {}
      }, 5000);
    } catch (eL) {}
  });
  step('Dự phòng', function () {
    if (bootTimer) clearInterval(bootTimer);
    var tries = 0, lastOk = -1;
    bootTimer = setInterval(function () {
      tries++;
      try {
        ensureHooks();
        bindScriptButtons();
        /* v8.0.3: Chỉ khi thực sự gắn thêm được nút mới vẽ lại, nếu không sẽ liên tục reset cuộn và focus nhập liệu */
        if (BTN_OK !== lastOk) { lastOk = BTN_OK; if (!DISPOSED) render(); }
        if (tries >= 4) { clearInterval(bootTimer); bootTimer = null; }
      } catch (e) {}
    }, 1500);
  });
  try { HOST.console.log(TAG + ' v' + VERSION + ' đã khởi động; Chế độ=' + uiMode() + '; Hook=' + hooked); } catch (e) {}
}

function dispose() {
  DISPOSED = true;
  try {
    if (BOOT_TIMER) { clearInterval(BOOT_TIMER); BOOT_TIMER = null; }
    /* Chỉ giải phóng hợp đồng thuê của chính mình, không đụng vào instance khác */
    if (HOST && HOST.__AR6HOLD && HOST.__AR6HOLD.token === BOOT_TOKEN) HOST.__AR6HOLD.alive = false;
  } catch (eDz) {}
  step('Dừng quan sát', function () { stopWatchers(); });
  try { if (bootTimer) { clearInterval(bootTimer); bootTimer = null; } } catch (e) {}
  try { if (bannerTimer) { clearTimeout(bannerTimer); bannerTimer = null; } } catch (e) {}
  step('Khôi phục fetch', unhookFetch);
  step('Khôi phục XHR', unhookXhr);
  step('Gỡ bảng điều khiển', function () {
    try { closeCard(); } catch (eC) {}
    var el = DOC && DOC.getElementById(ROOT_ID);
    if (el && el.parentNode) el.parentNode.removeChild(el);
    var bn = DOC && DOC.getElementById('ar6-bn');
    if (bn && bn.parentNode) bn.parentNode.removeChild(bn);
  });
  step('Gỡ đũa phép', function () { try { unmountWandEntry(); } catch (eW) {} });
  step('Dọn dẹp tàn dư', function () {
    try { closeCard(); } catch (eC) {}
    ['ar6-bn2'].forEach(function (id) {
      var el = DOC && DOC.getElementById(id);
      if (el && el.parentNode) el.parentNode.removeChild(el);
    });
    var st = DOC ? DOC.querySelectorAll('style#ar6-style,style#ar6-style82') : [];
    for (var i = 0; i < st.length; i++) if (st[i].parentNode) st[i].parentNode.removeChild(st[i]);
